import { CallExpressionShape, IdentifierShape, PropertyAccessShape } from '@servicenow/sdk-build-core'
import { NowIdShape } from '@servicenow/sdk-build-plugins'
import {
    ACTIVITY_DEFAULTS,
    ACTIVITY_REF_CALLEE,
    ACTIVITY_TABLE,
    LANE_DEFAULTS,
    LANE_TABLE,
} from '../constants/playbook-plugin-constants'
import type { ObjectShape, Record as SdkRecord, Shape } from '@servicenow/sdk-build-core'
import { addressFrom, ownLaneVarName, type GuidToVarPath } from './guid-to-var-path-map'
import { startsAfterActivities, startsAfterLanes } from './var-naming'

// Parsing (Fluent → database) accepts both the top-level Run.* form and the
// namespaced wfa.playbook.run.* form so existing fluent keeps working.
export const RUN_CALLEE_TO_START_RULE: Record<string, string> = {
    'wfa.playbook.run.Immediately': 'immediate',
    'wfa.playbook.run.After': 'after_items',
    'wfa.playbook.run.Manually': 'manual',
}

// Generation (database → Fluent) emits the namespaced wfa.playbook.run.* form.
export const START_RULE_TO_RUN_CALLEE: Record<string, string> = {
    immediate: 'wfa.playbook.run.Immediately',
    after_items: 'wfa.playbook.run.After',
    manual: 'wfa.playbook.run.Manually',
}

/** Both the top-level and namespaced callees for Run.After(). */
export const RUN_AFTER_CALLEES = new Set(['wfa.playbook.run.After'])

/** True when a callee string is either Run.After or wfa.playbook.run.After. */
export function isRunAfterCallee(callee: string): boolean {
    return RUN_AFTER_CALLEES.has(callee)
}

/** toRecord direction: CallExpressionShape → database string */
export function resolveStartRuleToDatabase(startRule: unknown): unknown {
    if (startRule instanceof CallExpressionShape) {
        return RUN_CALLEE_TO_START_RULE[startRule.getCallee()] ?? startRule
    }
    return startRule
}

/** The resolved database value of Run.Manually() / wfa.playbook.run.Manually(). */
export const MANUAL_START_RULE_VALUE = RUN_CALLEE_TO_START_RULE['wfa.playbook.run.Manually']

/**
 * toRecord direction: resolves a `variantOverrides[]` entry's own `startRule`/`order` fields to
 * `sys_pd_activity_override` properties (`start_rule_name`/`order`) — everything about the
 * override EXCEPT its Run.After() dependency args (`starts_after_activities`/`starts_after_lanes`),
 * which need a separate, later resolution pass (see PlaybookDefinitionPlugin's `variantOverrides`
 * pass, DEF0906759) since they may reference an activity/lane not yet created.
 *
 * Shared by ActivityPlugin's initial create AND that later pass's update-in-place call — both
 * write the SAME coalesced `sys_pd_activity_override` record (coalesced on `override_parent` +
 * `variant`), and `factory.createRecord()` REPLACES a coalesced record's properties on a repeat
 * call rather than merging them, so both call sites must build these fields identically.
 */
export function buildOverrideBaseProperties(overrideObj: ObjectShape): Record<string, string | Shape> {
    const properties: Record<string, string | Shape> = {}

    const startRuleShape = overrideObj.get('startRule')
    if (startRuleShape && !startRuleShape.isUndefined()) {
        const resolvedStartRule = resolveStartRuleToDatabase(startRuleShape)
        properties['start_rule_name'] = typeof resolvedStartRule === 'string' ? resolvedStartRule : startRuleShape
    }

    const orderShape = overrideObj.get('order')
    if (orderShape && !orderShape.isUndefined()) {
        const orderValue = orderShape.ifNumber()?.getValue()
        properties['order'] = orderValue !== undefined ? String(orderValue) : orderShape
    }

    return properties
}

/**
 * True when a start rule (either a raw CallExpressionShape or an already-resolved database
 * string) resolves to Run.Manually() — i.e. the activity is optional and may never run, so
 * nothing may depend on it or reference its output.
 */
export function isOptionalActivity(startRule: unknown): boolean {
    return resolveStartRuleToDatabase(startRule) === MANUAL_START_RULE_VALUE
}

const TABLE_CONFIG: Record<string, { startsAfterField: string; defaultStartRule: string }> = {
    [LANE_TABLE]: { startsAfterField: 'starts_after_lanes', defaultStartRule: LANE_DEFAULTS.START_RULE },
    [ACTIVITY_TABLE]: { startsAfterField: 'starts_after_activities', defaultStartRule: ACTIVITY_DEFAULTS.START_RULE },
}

/** toShape direction: database record → Run.*() CallExpressionShape */
export function resolveStartRuleToShape(
    record: SdkRecord,
    guidToVarPath?: GuidToVarPath,
    branchGuidMap?: Map<string, { activityVarName: string; fluentBranchId: string }>
): { startRuleShape: CallExpressionShape | ReturnType<SdkRecord['get']>; startRuleValue: string } {
    const config = TABLE_CONFIG[record.getTable()]
    if (!config) {
        return { startRuleShape: record.get('start_rule'), startRuleValue: '' }
    }

    const startRuleRaw = record.get('start_rule')?.ifString()?.getValue() ?? ''
    const startRuleValue = START_RULE_TO_RUN_CALLEE[startRuleRaw]
        ? startRuleRaw
        : (record.get('start_rule_name')?.ifString()?.getValue() ?? config.defaultStartRule)
    const runCallee = START_RULE_TO_RUN_CALLEE[startRuleValue]
    const isRunAfter = isRunAfterCallee(runCallee)
    const startRuleShape = isRunAfter
        ? resolveRunAfterShape(record, guidToVarPath, branchGuidMap)
        : runCallee
          ? new CallExpressionShape({ source: record, callee: runCallee, args: [] })
          : record.get('start_rule')

    return { startRuleShape, startRuleValue }
}

/**
 * Resolves a Run.After()-style start rule to its dependency args.
 *
 * `record` is the source of the `starts_after_*` fields (a base activity/lane, or a
 * `sys_pd_activity_override` row). `laneContextRecord` is the record whose enclosing lane
 * determines which dependencies are same-lane bare identifiers vs. cross-lane dotted paths —
 * for a base activity/lane this is the same record, but `sys_pd_activity_override` has no
 * `lane` field of its own, so callers reconstructing an override's start rule must pass the
 * override's parent activity record here instead.
 *
 * `forwardRefGuids`, when provided, is the set of dependency guids (from
 * `forwardReferencingOverrideDependencies` in variant-override-ordering.ts) that would
 * otherwise require a forward reference to a not-yet-declared `const activity_i`. For those
 * guids only, this emits `wfa.playbook.activityRef(Now.ID['<guid>'])` instead of a bare
 * identifier, since that literal lookup never requires the target's lexical declaration to
 * exist yet (DEF0906759).
 */
export function resolveRunAfterShape(
    record: SdkRecord,
    guidToVarPath?: GuidToVarPath,
    branchGuidMap?: Map<string, { activityVarName: string; fluentBranchId: string }>,
    laneContextRecord: SdkRecord = record,
    forwardRefGuids?: Set<string>
): CallExpressionShape {
    const args: Shape[] = []
    const fromLane = ownLaneVarName(laneContextRecord, guidToVarPath)
    const startsAfterBranchesValue = record.get('starts_after_branches')?.ifString()?.getValue() ?? ''
    const branchEntries = startsAfterBranchesValue
        .split(',')
        .map((g) => g.trim())
        .filter(Boolean)
    const branchActivityGuids = new Set(
        branchEntries
            .map((entry) => {
                const dotIndex = entry.indexOf('.')
                return dotIndex >= 0 ? entry.substring(0, dotIndex) : ''
            })
            .filter(Boolean)
    )

    // A dependency is always in scope at the call site: a sibling in this record's own lane, a lane,
    // or a stage-level activity — each a bare identifier. Anything else has no name to write here, so
    // it is dropped rather than rendered some other way. Exception: a guid in `forwardRefGuids`
    // would be a forward reference to a not-yet-declared const, so it's emitted as a
    // `wfa.playbook.activityRef(Now.ID[...])` literal lookup instead (DEF0906759) — this never
    // requires the target's lexical declaration to exist yet, regardless of textual order.
    const pushDependency = (guid: string) => {
        if (forwardRefGuids?.has(guid)) {
            args.push(
                new CallExpressionShape({
                    source: record,
                    callee: ACTIVITY_REF_CALLEE,
                    args: [new NowIdShape({ source: record, id: guid })],
                })
            )
            return
        }
        const address = addressFrom(guidToVarPath, guid, fromLane)
        if (address?.form === 'bare') {
            args.push(new IdentifierShape({ source: record, name: address.name }))
        }
    }

    for (const guid of startsAfterLanes(record)) {
        pushDependency(guid)
    }

    for (const guid of startsAfterActivities(record)) {
        if (branchActivityGuids.has(guid)) {
            continue
        }
        pushDependency(guid)
    }

    // Resolve starts_after_branches → PropertyAccessShape (e.g. activity_0.branches.critical)
    // Platform format: <decisionActivitySysId>.<branchId> (e.g. "abc123.def456")
    for (const entry of branchEntries) {
        const dotIndex = entry.indexOf('.')
        const branchGuid = dotIndex >= 0 ? entry.substring(dotIndex + 1) : entry
        const branchInfo = branchGuidMap?.get(branchGuid)
        if (branchInfo) {
            args.push(
                new PropertyAccessShape({
                    source: record,
                    elements: [branchInfo.activityVarName, 'branches', branchInfo.fluentBranchId] as [
                        string,
                        string,
                        ...string[],
                    ],
                })
            )
        }
    }

    return new CallExpressionShape({ source: record, callee: START_RULE_TO_RUN_CALLEE.after_items, args })
}
