import { CallExpressionShape, type ObjectShape, type Shape } from '@servicenow/sdk-build-core'
import { isRunAfterCallee } from './start-rule-resolver'
import type { PlaybookGraph } from './playbook-graph'

export interface RedundantEdge {
    /** The Now.ID key of the node that has the redundant dependency (e.g. 'lane_c') */
    nodeId: string
    /** The Now.ID key of the dependency that is redundant (e.g. 'lane_a') */
    redundantDepId: string
    /** The Now.ID key of the other dependency through which redundantDepId is already reachable (e.g. 'lane_b') */
    throughId: string
    /** The call expression shape of the node, used as the diagnostic source */
    shape: Shape
    /** Display label derived from the node's callee name (e.g. 'Lane', 'Activity') */
    nodeTypeLabel: string
}

const NOW_ID_PATTERN = /^Now\.ID\[['"]([^'"]+)['"]\]$/

/**
 * Extract the Now.ID key string from a shape by inspecting its code representation.
 * Returns the key (e.g. 'lane_a') if the shape generates Now.ID['lane_a'], or undefined.
 * Works for NowIdShape and any ElementAccessExpressionShape whose getCode() returns
 * the Now.ID[...] pattern — no instanceof or module-identity assumptions needed.
 */
export function getNowIdKey(shape: Shape): string | undefined {
    return shape.getCode().match(NOW_ID_PATTERN)?.[1]
}

/**
 * Extract the Now.ID key string from a node config's $id field.
 * Returns undefined if the $id is not a Now.ID element access expression.
 */
function getNodeIdKey(config: ObjectShape): string | undefined {
    return getNowIdKey(config.get('$id'))
}

/**
 * Resolve a node's call expression to the config object containing its $id.
 *
 * Supports both shapes used by playbook APIs:
 *  - Lane({ config: { $id, ... }, activities: ... })       → config at arg 0, nested under 'config'
 *  - Activity(def, { $id, ... })                            → config at arg 1
 *  - Flat objects at arg 0 (test fixtures, custom callees)  → config at arg 0
 */
export function getConfigWithId(callExpr: CallExpressionShape): ObjectShape | undefined {
    for (const argIndex of [0, 1]) {
        const arg = callExpr.getArgument(argIndex)?.ifObject()
        if (!arg) {
            continue
        }
        const nested = arg.get('config')?.isUndefined() === false ? arg.get('config').ifObject() : arg
        if (nested && getNowIdKey(nested.get('$id')) !== undefined) {
            return nested
        }
    }
    return undefined
}

/**
 * Extract the Now.ID keys of all nodes referenced in a Run.After() call.
 * Resolves both direct call expressions and identifier references (e.g. lane_0, activity_0).
 * Handles both flat ({ $id, ... }) and nested ({ config: { $id, ... } }) config shapes,
 * as well as Activity's two-arg signature where config is at arg 1.
 */
function getRunAfterDepKeys(config: ObjectShape, variables: Map<string, CallExpressionShape>): string[] {
    const startRuleShape = config.get('startRule')
    if (!startRuleShape?.is(CallExpressionShape)) {
        return []
    }

    const runAfterCall = startRuleShape.as(CallExpressionShape)
    if (!isRunAfterCallee(runAfterCall.getCallee())) {
        return []
    }

    const keys: string[] = []
    for (const arg of runAfterCall.getArguments()) {
        let callExpr: CallExpressionShape | undefined

        if (arg.is(CallExpressionShape)) {
            callExpr = arg.as(CallExpressionShape)
        } else if (arg.isIdentifier()) {
            callExpr = variables.get(arg.asIdentifier().getName())
        }

        if (!callExpr) {
            continue
        }

        const cfg = getConfigWithId(callExpr)
        const key = cfg ? getNowIdKey(cfg.get('$id')) : undefined
        if (key) {
            keys.push(key)
        }
    }

    return keys
}

/**
 * Build a dependency graph (nodeId → direct Run.After dependency ids) from a flat list of
 * nodes. Shared by `detectRedundantEdges` (scoped to one collection at a time) and
 * `computeAncestorIds` (a single combined graph across the whole playbook).
 */
function buildGraph(
    children: Array<{ callExpr: CallExpressionShape; childConfig: ObjectShape }>,
    variables: Map<string, CallExpressionShape>
): Map<string, string[]> {
    const graph = new Map<string, string[]>()
    for (const { childConfig } of children) {
        const id = getNodeIdKey(childConfig)
        if (!id) {
            continue
        }
        graph.set(id, getRunAfterDepKeys(childConfig, variables))
    }
    return graph
}

/**
 * Build the transitive closure (all reachable nodes) from a given node using DFS.
 * Uses a cache to avoid recomputing for the same node.
 */
function buildReachabilitySet(
    nodeId: string,
    graph: Map<string, string[]>,
    cache: Map<string, Set<string>>
): Set<string> {
    if (cache.has(nodeId)) {
        return cache.get(nodeId)!
    }

    // Mark as in-progress with empty set to handle cycles gracefully
    const reachable = new Set<string>()
    cache.set(nodeId, reachable)

    for (const dep of graph.get(nodeId) ?? []) {
        reachable.add(dep)
        for (const transitive of buildReachabilitySet(dep, graph, cache)) {
            reachable.add(transitive)
        }
    }

    return reachable
}

/**
 * Detect redundant edges in a collection of nodes that use Run.After() for ordering.
 *
 * An edge from node N to dependency D is redundant when D is already reachable
 * from N through another one of N's direct dependencies.
 *
 * Example: if nodes are A → B → C, and C also directly lists A in Run.After(),
 * then C → A is redundant because C → B → A already covers it.
 *
 * This mirrors the "Redundant start rule" warning in Playbook Designer and applies
 * to any ordered collection (lanes, activities, etc.).
 *
 * @param children - The parsed call expressions and their configs from processChildCollectionToRecord
 * @param variables - Map of identifier names to their resolved call expressions (e.g. 'lane_0' → Lane(...))
 * @returns Array of redundant edges, each containing the shape for diagnostic reporting
 */
export function detectRedundantEdges(
    children: Array<{ callExpr: CallExpressionShape; childConfig: ObjectShape }>,
    variables: Map<string, CallExpressionShape>
): RedundantEdge[] {
    // Build graph: nodeId → direct dependency ids
    const graph = buildGraph(children, variables)
    const nodeCallExprs = new Map<string, CallExpressionShape>()
    for (const { callExpr, childConfig } of children) {
        const id = getNodeIdKey(childConfig)
        if (id) {
            nodeCallExprs.set(id, callExpr)
        }
    }

    // Build reachability cache for all nodes
    const reachabilityCache = new Map<string, Set<string>>()

    const redundantEdges: RedundantEdge[] = []

    for (const [nodeId, deps] of graph.entries()) {
        // Need at least 2 dependencies to have a redundant one
        if (deps.length < 2) {
            continue
        }

        for (const dep of deps) {
            // Check if dep is reachable from any other direct dependency of this node
            const otherDeps = deps.filter((d) => d !== dep)
            for (const otherDep of otherDeps) {
                const reachable = buildReachabilitySet(otherDep, graph, reachabilityCache)
                if (reachable.has(dep)) {
                    const callExpr = nodeCallExprs.get(nodeId)!
                    const callee = callExpr.getCallee()
                    const nodeTypeLabel =
                        callee
                            .split('.')
                            .at(-1)
                            ?.replace(/^\w/, (c) => c.toUpperCase()) ?? callee
                    redundantEdges.push({
                        nodeId,
                        redundantDepId: dep,
                        throughId: otherDep,
                        shape: callExpr,
                        nodeTypeLabel,
                    })
                    break // Only report once per redundant dep
                }
            }
        }
    }

    return redundantEdges
}

/**
 * Compute the set of activity Now.ID keys that are guaranteed ancestors of `targetId` — i.e.
 * activities guaranteed to have completed before `targetId` runs, given the playbook's lane
 * and activity Run.After dependency structure.
 *
 * Used to gate which activities a variant condition may reference via `activityRef()` when a
 * custom `evaluateVariantChildrenAfter` point is set: only ancestors of that point are safe to
 * reference (see `docs/api/playbook-api.md`).
 *
 * Key space: operates entirely on Now.ID keys (never GUIDs) — same space `computeAncestorIds`'s
 * caller already resolves `evaluateVariantChildrenAfter` in.
 *
 * Takes an already-built `PlaybookGraph` (`collectPlaybookGraph`, also used by the
 * `evaluateVariantChildrenAfter` target-validity checks in `playbook-definition-plugin.ts`)
 * rather than building its own or doing a bespoke traversal, so both consumers share a single
 * source of truth for lane/activity declarations and their `startRule` dependency edges,
 * computed exactly once per playbook.
 *
 * Algorithm:
 *  1. Build a combined dependency graph over every lane and activity from the graph's nodes,
 *     using each node's own `plainDeps` plus its `branchDeps`' owning decision (a Run.After
 *     on a decision's branch still requires that decision itself to have completed), plus one
 *     synthetic containment edge per nested activity: activity → its enclosing lane. This lets
 *     `targetId` (if nested) inherit whatever lanes/activities its own enclosing lane
 *     structurally depends on.
 *  2. Bake the reverse containment expansion directly into that same graph: for every lane
 *     other than `targetId`'s OWN enclosing lane, add an edge from the lane to each activity
 *     nested in it. `targetId`'s own enclosing lane is deliberately excluded — being nested in
 *     the same lane does not make sibling activities ancestors of one another.
 *  3. Compute reachability from `targetId` over that single graph in one pass. Because the
 *     lane→activities expansion from step 2 is already part of the graph, `buildReachabilitySet`
 *     naturally continues from each newly-reached activity through its own transitive deps too.
 *  4. Filter the result down to activity ids only (lane keys are structural bookkeeping, never
 *     valid `activityRef()` targets).
 */
/**
 * Collect the Now.ID key and `variant` field shape of every variant-only activity (one whose
 * config sets `variant`) in the playbook's static graph. Used to validate each variant-only
 * activity is a guaranteed descendant of `evaluateVariantChildrenAfter` (platform rule
 * VARIANT_ACTIVITY_BEFORE_EVALUATION_POINT) — see `playbook-definition-plugin.ts`.
 */
export function collectVariantOnlyActivityKeys(
    playbookGraph: PlaybookGraph | undefined
): Array<{ key: string; variantShape: Shape }> {
    if (!playbookGraph) {
        return []
    }
    const result: Array<{ key: string; variantShape: Shape }> = []
    for (const node of playbookGraph.nodes.values()) {
        if (node.kind !== 'activity') {
            continue
        }
        const variantShape = node.config.get('variant')
        if (variantShape && !variantShape.isUndefined()) {
            result.push({ key: node.nowIdKey, variantShape })
        }
    }
    return result
}

export function computeAncestorIds(targetId: string, playbookGraph: PlaybookGraph | undefined): Set<string> {
    if (!playbookGraph) {
        return new Set()
    }
    const { nodes } = playbookGraph

    const activityIds = new Set<string>()
    const containment = new Map<string, string>() // activityId -> laneId
    for (const node of nodes.values()) {
        if (node.kind === 'activity') {
            activityIds.add(node.nowIdKey)
            if (node.laneNowIdKey) {
                containment.set(node.nowIdKey, node.laneNowIdKey)
            }
        }
    }
    const ownEnclosingLane = containment.get(targetId)

    const graph = new Map<string, string[]>()
    for (const node of nodes.values()) {
        const deps = [...node.plainDeps, ...node.branchDeps.map((dep) => dep.decisionKey)]
        if (node.kind === 'activity' && node.laneNowIdKey) {
            deps.push(node.laneNowIdKey) // activity -> its own enclosing lane
        }
        graph.set(node.nowIdKey, deps)
    }
    // lane -> its activities, EXCEPT targetId's own enclosing lane (siblings aren't ancestors)
    for (const [activityId, laneId] of containment) {
        if (laneId === ownEnclosingLane) {
            continue
        }
        graph.get(laneId)?.push(activityId)
    }

    const reachable = buildReachabilitySet(targetId, graph, new Map())
    return new Set([...reachable].filter((id) => activityIds.has(id)))
}
