/**
 * Resolves a variable entry into a Shape for use as an input or experience property.
 * Prefers the sys_element_mapping value (pill reference) over sys_variable_value when present.
 * Returns undefined if the field is excluded by allowedFields.
 */
function resolveVarEntryToShape(
    entry: ResolvedVariable,
    allowedFields: Set<string> | undefined,
    elementMappingByField: Map<string, string>,
    varRecord: SdkRecord,
    pillContext: PillTransformContext | undefined
): Shape | undefined {
    if (allowedFields !== undefined && !allowedFields.has(entry.name)) {
        return undefined
    }
    const value = varRecord.get('value')
    const str = value.ifString()?.getValue()
    const pillStr = elementMappingByField.get(entry.name)
    const effectiveStr = pillStr || str
    if (entry.type === 'template_value') {
        return convertToTemplateValue(value, effectiveStr, pillContext)
    }
    const transformed =
        effectiveStr && pillContext ? transformStandardPills(effectiveStr, varRecord, pillContext) : undefined
    return transformed ?? convertValueToType(value, entry.type)
}

/**
 * Reconstructs a Go Back target-reference field (`go_back_to_target_stage` /
 * `go_back_to_target_activity`) as a scope-aware raw lane/activity reference: a bare identifier for
 * a lane, a stage-level activity, or a same-lane activity, and a `laneVar.activityVar` dot-walk for
 * an activity in another lane (`addressFrom` in guid-to-var-path-map.ts makes that call).
 *
 * Returns undefined when the guid isn't in the map (a stale reference, or the map wasn't threaded
 * through) or resolves to the wrong kind of record — e.g. a `go_back_to_target_stage` field whose
 * stored guid belongs to an activity. Callers omit the field entirely rather than emit a broken
 * reference.
 */
function resolveGoBackTargetShape(
    source: SdkRecord,
    isStage: boolean,
    targetGuid: string | undefined,
    fromLaneVarName: string | undefined,
    guidToVarPath: GuidToVarPath | undefined
): Shape | undefined {
    if (!targetGuid) {
        return undefined
    }
    if (guidToVarPath?.get(targetGuid)?.kind !== (isStage ? 'lane' : 'activity')) {
        return undefined
    }
    const address = addressFrom(guidToVarPath, targetGuid, fromLaneVarName)
    if (!address) {
        return undefined
    }
    // An explicit `value` (keyed on the target's own guid, distinct from any other target) is
    // required here: `IdentifierShape`/`PropertyAccessShape` default to an unresolved value, and
    // the round-trip merge's property-level equality check resolves both the freshly-built shape
    // and whatever the previous source text parses to before comparing — two *different* targets
    // that both fail to resolve still collapse to the same "unresolved" placeholder and register
    // as equal, so a stale identifier name from prior source text silently survives a rebuild even
    // after the referenced activity/lane's own variable name changes. Giving the shape a concrete,
    // guid-derived value sidesteps that false-equal collapse.
    const lastElement = new IdentifierShape({ source, name: address.name, value: Shape.from(source, targetGuid) })
    return address.form === 'bare'
        ? lastElement
        : new PropertyAccessShape({ source, elements: [address.laneVarName, lastElement] })
}

export interface ActivityToShapeResult {
    success: true
    value: CallExpressionShape
    usesParentRecord: boolean
    /** For Decision activities: maps branch GUID → Fluent branch id (slugified label or 'else') */
    branchMap?: Map<string, string>
}

/**
 * Parses a Decision activity's `branches` sys_variable_value JSON string into the Fluent
 * `branches` array shape, plus a map of branch GUID -> Fluent branch id (used to resolve
 * `starts_after_branches` cross-references elsewhere).
 *
 * Returns undefined when the JSON is malformed or not an array — the caller then leaves
 * `branches` and the branch map unset, exactly as it would for a missing variable record.
 */
export function parseDecisionBranchesToShape(
    jsonStr: string,
    source: SdkRecord,
    activityPillContext?: PillTransformContext
): { branches: ArrayShape; branchMap: Map<string, string> } | undefined {
    let parsed: unknown
    try {
        parsed = JSON.parse(jsonStr)
    } catch {
        return undefined
    }
    if (!Array.isArray(parsed)) {
        return undefined
    }

    const branchMap = new Map<string, string>()
    const branchObjects = parsed.map((branch: Record<string, unknown>) => {
        const branchGuid = String(branch['id'] ?? '')
        const rawLabel = String(branch['label'] ?? '')
        const label = branchGuid === 'ELSE' ? 'Else' : rawLabel
        const fluentId = branchGuid === 'ELSE' ? 'else' : slugifyString(label) || branchGuid
        const props: Record<string, unknown> = {
            id: fluentId,
            label,
        }
        if (branch['condition'] !== undefined && branch['condition'] !== '') {
            const decoded = decodeKeywordsToken(String(branch['condition']))
            const transformed = activityPillContext
                ? transformConditionPills(decoded, source, activityPillContext)
                : undefined
            props['condition'] = transformed ?? decoded
        }
        // Emit only when set, following the default-omission convention.
        if (branch['isIdealPath'] === true) {
            props['isIdealPath'] = true
        }
        if (branchGuid) {
            branchMap.set(branchGuid, fluentId)
        }
        return props
    })

    return { branches: new ArrayShape({ source, elements: branchObjects }), branchMap }
}

// Detects a dotwalk off the enclosing lanes callback's `params` argument — either
// `params.parentRecord` or `params.variants.<key>` (variant references). Both require that
// callback to declare its `params` parameter, so both are treated the same way by callers that
// use this to decide whether to emit that parameter.
function shapeUsesParamsParameter(shape: Shape | undefined): boolean {
    if (!shape) {
        return false
    }
    const obj = shape.ifObject()
    const arr = shape.ifArray()
    if (shape instanceof PropertyAccessShape) {
        const [root, second] = shape.getElements()
        return (
            root?.getName() === 'params' && (second?.getName() === 'parentRecord' || second?.getName() === 'variants')
        )
    } else if (shape instanceof CallExpressionShape) {
        return shape.getArguments(false).some((arg) => shapeUsesParamsParameter(arg))
    } else if (shape instanceof TemplateExpressionShape) {
        return shape.getSpans().some((span) => shapeUsesParamsParameter(span.getExpression()))
    } else if (shape instanceof TemplateValueShape) {
        return shape
            .getTemplateValue()
            .entries()
            .some(([, value]) => shapeUsesParamsParameter(value))
    } else if (obj) {
        return obj.entries().some(([, value]) => shapeUsesParamsParameter(value))
    } else if (arr) {
        return arr.getElements().some((element) => shapeUsesParamsParameter(element))
    }
    return false
}

export function activityRecordToShape(
    record: SdkRecord,
    database: Database,
    // Whole-playbook variable info, built once in PlaybookDefinitionPlugin's toShape handler
    // (see guid-to-var-path-map.ts). Absent when a lone activity record is converted on its own,
    // in which case sibling references fall back to Now.ID and Go Back target fields are omitted.
    guidToVarPath?: GuidToVarPath,
    branchGuidMap?: Map<string, { activityVarName: string; fluentBranchId: string }>,
    pillContext?: PillTransformContext,
    timerRecords?: SdkRecord[],
    // sys_pd_activity_override descendants for the whole playbook (not pre-filtered to this
    // activity — filtered below by override_parent).
    overrideRecords?: SdkRecord[],
    // Variant guid -> property-name key, for reconstructing `params.variants.<key>` references in
    // `variant`/`variantOverrides[].variant`. Mirrors activityGuidToNowId's role for activityRef().
    variantGuidToKey?: Map<string, string>,
    // guid -> position within this activity's own lane, per the base topological order that
    // fixes `const activity_i` declaration order (see buildActivityPositionMap in
    // variant-override-ordering.ts). Built once per lane by the caller and threaded through so
    // variantOverrides reconstruction can detect a dependency that would require a forward
    // reference to a not-yet-declared const (see the DEF0906759 comment below). Absent for
    // lane-less activities (stage-level Decisions/global optional activities), which this
    // detection doesn't cover.
    activityPositionInLane?: Map<string, number>
): ActivityToShapeResult | { success: false } {
    const { startRuleShape, startRuleValue } = resolveStartRuleToShape(record, guidToVarPath, branchGuidMap)
    const isManual = isOptionalActivity(startRuleValue)

    const activityDefSysId = record.get('activity_definition')?.ifString()?.getValue() ?? ''

    // Build an activity-scoped pill context with the current activity's sys_id and its
    // backing flow/action's own label (for decomposing {{vl.<label>...}} pills).
    const activityPillContext: PillTransformContext | undefined = pillContext
        ? {
              ...pillContext,
              currentActivitySysId: record.getId().getValue(),
              currentActivityBackingLabel: ACTIVITY_DEF_BACKING_LABEL[activityDefSysId],
          }
        : undefined

    // Find matching timer record for this activity
    const timerRecord = timerRecords
        ? findTimerRecord(timerRecords, record.getId().getValue(), 'sys_pd_activity')
        : undefined

    // Reconstruct actionOverrides from sys_pd_activity_action_override descendants, ordered
    // by display_order. action_assignment is always emitted as the raw sys_id — those rows
    // are app/experience-specific platform configuration, not authored via Fluent, so there's
    // no OOTB name to resolve it to.
    const actionOverrideRecords = database
        .query(ACTIVITY_ACTION_OVERRIDE_TABLE, { activity: record.getId().getValue() })
        .sort(
            (a, b) =>
                (a.get('display_order')?.toNumber().getValue() ?? 0) -
                (b.get('display_order')?.toNumber().getValue() ?? 0)
        )
    const actionOverrides = actionOverrideRecords.length
        ? actionOverrideRecords.map((overrideRecord) => ({
              actionAssignment: overrideRecord.get('action_assignment')?.ifString()?.getValue() ?? '',
              label: overrideRecord.get('label')?.ifString()?.getValue() ?? '',
              displayOrder: overrideRecord.get('display_order')?.toNumber().getValue() ?? 0,
          }))
        : undefined

    // Variant-only activity: `variant` on sys_pd_activity marks this activity as scoped to a
    // single variant. Reconstruct as `params.variants.<key>`; omitted when unset (a
    // normal base/shared activity).
    const variantGuid = record.get('variant')?.ifString()?.getValue()
    const variantRefShape = variantGuid
        ? buildVariantRefShape(record, variantGuid, variantGuidToKey ?? new Map(), PERMISSIONS_PARAM_NAME)
        : undefined

    // variantOverrides: sys_pd_activity_override rows whose override_parent is this activity.
    // Only start_rule_name/order are independent override targets in v1 (see
    // sys_pd_activity_override dictionary + plan). start_rule_name's own starts_after_* fields
    // ARE reconstructed (DEF0906759) via resolveRunAfterShape() below, mirroring the base
    // activity/lane's own start_rule handling above.
    const activityOverrideRecords = (overrideRecords ?? []).filter(
        (o) => o.get('override_parent')?.ifString()?.getValue() === record.getId().getValue()
    )
    const variantOverrideShapes = activityOverrideRecords.map((overrideRecord) => {
        const overrideVariantGuid = overrideRecord.get('variant')?.ifString()?.getValue() ?? ''
        const overrideVariantRef = buildVariantRefShape(
            overrideRecord,
            overrideVariantGuid,
            variantGuidToKey ?? new Map(),
            PERMISSIONS_PARAM_NAME
        )
        const overrideStartRuleName = overrideRecord.get('start_rule_name')?.ifString()?.getValue()
        const overrideStartRuleCallee = overrideStartRuleName
            ? START_RULE_TO_RUN_CALLEE[overrideStartRuleName]
            : undefined
        // `order` is persisted as a string (see activity-plugin.ts's `String(overrideOrderValue)`),
        // so `ifNumber()` never matches here — coerce explicitly, guarding against the blank
        // string a no-op/omitted override leaves behind (Number('') is 0, not "absent").
        const overrideOrderStringValue = overrideRecord.get('order')?.ifString()?.getValue()
        const overrideOrderValue =
            overrideOrderStringValue !== undefined && overrideOrderStringValue !== ''
                ? Number(overrideOrderStringValue)
                : undefined

        // DEF0906759: an override's own Run.After() dependency can point at an activity
        // declared LATER than its own override_parent in base order — a forward reference
        // to a not-yet-declared const, and (when the override direction reverses an existing
        // base edge between the same two activities) a genuine mutual dependency that can't be
        // resolved by any textual declaration order. `forwardReferencingOverrideDependencies`
        // identifies exactly those dependency guids so resolveRunAfterShape can emit
        // `wfa.playbook.activityRef(Now.ID[...])` for them instead of a bare identifier.
        const forwardRefGuids = activityPositionInLane
            ? forwardReferencingOverrideDependencies(overrideRecord, activityPositionInLane)
            : undefined

        return new ObjectShape({
            source: overrideRecord,
            properties: {
                variant: overrideVariantRef,
                ...(overrideStartRuleCallee
                    ? {
                          startRule: isRunAfterCallee(overrideStartRuleCallee)
                              ? resolveRunAfterShape(
                                    overrideRecord,
                                    guidToVarPath,
                                    branchGuidMap,
                                    record,
                                    forwardRefGuids
                                )
                              : new CallExpressionShape({
                                    source: overrideRecord,
                                    callee: overrideStartRuleCallee,
                                    args: [],
                                }),
                      }
                    : {}),
                ...(overrideOrderValue !== undefined ? { order: overrideOrderValue } : {}),
            },
        })
    })

    // The AI-agent fields are only meaningful when an agent is enabled, so the whole block
    // below is gated on enable_ai_agent. Read the raw column up front to drive that gate.
    const isAiAgentEnabled = record.get('enable_ai_agent')?.toBoolean().getValue()
    // ai_agent_obj_additional_detail only applies in Autonomous mode; read the raw
    // execution mode up front so that field can be conditionally omitted below.
    const aiAgentExecutionModeValue = record.get('ai_agent_execution_mode')?.ifString()?.getValue() ?? ''

    // Decision activities branch on per-branch conditions, not a top-level
    // conditionToRun, so we omit conditionToRun from their config.
    const isDecisionActivity = activityDefSysId === DECISION_DEF_SYS_ID

    // `enable_ai_agent` on the record is round-tripped platform state — it isn't sufficient
    // on its own to decide whether emitting AI fields is safe, since the backing definition
    // might not support AI agents at all (e.g. stale data, or a definition that dropped AI
    // support). Emitting AI fields for a non-AI-capable definition would produce Fluent that
    // doesn't compile, since ActivityConfigFor excludes those fields entirely for such
    // definitions. Require both: the instance has it enabled, and the definition supports it.
    const shouldEmitAiFields = Boolean(isAiAgentEnabled) && AI_CAPABLE_ACTIVITY_DEF_SYS_IDS.has(activityDefSysId)

    // AI fields are further filtered per activity definition (same convention as
    // ACTIVITY_DEF_INPUT_DISPLAY_PREFS/ACTIVITY_DEF_EXPERIENCE_DISPLAY_PREFS): when the
    // definition sys_id has no entry, all populated AI fields are emitted.
    const allowedAiFields = ACTIVITY_DEF_AI_FIELD_DISPLAY_PREFS[activityDefSysId]
    const isAiFieldAllowed = (column: string) => allowedAiFields === undefined || allowedAiFields.has(column)

    const configShape = record.transform(({ $ }) => ({
        $id: $.val(NowIdShape.from(record)),
        label: $.from('label'),
        name: $.from('name'),
        ...(isManual ? {} : { order: $.from('order').toNumber() }),
        description: $.from('description'),
        startRule: $.val(startRuleShape),
        ...(isDecisionActivity || isManual
            ? {}
            : {
                  conditionToRun: $.from('condition_to_run').map((v: Shape) => {
                      if (!activityPillContext) {
                          return v
                      }
                      const str = v.ifString()?.getValue()
                      if (!str) {
                          return v
                      }
                      return transformConditionPills(str, record, activityPillContext) ?? v
                  }),
              }),
        restartRule: $.from('restart_rule'),
        // AI-agent fields are internal round-trip-only and only meaningful when the agent
        // is enabled on an AI-capable definition. When shouldEmitAiFields is true we surface
        // enableAiAgent plus each other allowed field; otherwise we omit the entire AI block.
        // Within the block, every allowed field is emitted with its actual resolved value —
        // including a genuinely empty string/list — rather than compared against a `.def(...)`
        // default and omitted when it matches. That means the field is always explicitly present
        // on the generated instance, so the reverse (Fluent -> XML) transform can tell "no value"
        // (an explicit '' / []) apart from "field entirely omitted" (via `ObjectShape.has()`) and
        // apply the activity definition's own default only in the latter case. Booleans are
        // preserved as-is.
        ...(shouldEmitAiFields
            ? {
                  ...(isAiFieldAllowed('enable_ai_agent')
                      ? { enableAiAgent: $.from('enable_ai_agent').toBoolean() }
                      : {}),
                  ...(isAiFieldAllowed('ai_agent_objective') ? { aiAgentObjective: $.from('ai_agent_objective') } : {}),
                  ...(isAiFieldAllowed('ai_agent_obj_additional_detail') && aiAgentExecutionModeValue === 'on'
                      ? { aiAgentObjAdditionalDetail: $.from('ai_agent_obj_additional_detail') }
                      : {}),
                  ...(isAiFieldAllowed('ai_agent_execution_mode')
                      ? { aiAgentExecutionMode: $.from('ai_agent_execution_mode') }
                      : {}),
                  ...(isAiFieldAllowed('ai_agent_run_with_roles')
                      ? {
                            aiAgentRunWithRoles: $.from('ai_agent_run_with_roles').map((v: Shape) => {
                                const str = v.ifString()?.getValue() ?? ''
                                return str
                                    ? str
                                          .split(',')
                                          .map((s) => s.trim())
                                          .filter(Boolean)
                                    : []
                            }),
                        }
                      : {}),
                  ...(isAiFieldAllowed('ai_agent_run_as') ? { aiAgentRunAs: $.from('ai_agent_run_as') } : {}),
                  ...(isAiFieldAllowed('ai_agent_user') ? { aiAgentUser: $.from('ai_agent_user') } : {}),
                  // A platform defect can render an empty glide_list as the literal string
                  // "undefined" rather than an empty value; treat it as empty here so it
                  // doesn't round-trip as a bogus agent reference.
                  ...(isAiFieldAllowed('conversational_agents')
                      ? {
                            conversationalAgents: $.from('conversational_agents').map((v: Shape) => {
                                const str = v.ifString()?.getValue() ?? ''
                                return str
                                    ? str
                                          .split(',')
                                          .map((s) => s.trim())
                                          .filter((s) => Boolean(s) && s !== 'undefined')
                                    : []
                            }),
                        }
                      : {}),
                  ...(isAiFieldAllowed('ai_agent_supported_actions')
                      ? {
                            aiAgentSupportedActions: $.from('ai_agent_supported_actions').map((v: Shape) => {
                                const str = v.ifString()?.getValue() ?? ''
                                return str
                                    ? str
                                          .split(',')
                                          .map((s) => s.trim())
                                          .filter((s) => Boolean(s) && s !== 'undefined')
                                    : []
                            }),
                        }
                      : {}),
                  ...(isAiFieldAllowed('launch_agent_when_activity_start')
                      ? { launchAgentWhenActivityStart: $.from('launch_agent_when_activity_start').toBoolean() }
                      : {}),
              }
            : {}),
        ...(timerRecord && !isManual
            ? {
                  startWithDelay: $.val(timerAttributesToShape(timerRecord, activityPillContext)),
              }
            : {}),
        ...(actionOverrides ? { actionOverrides: $.val(actionOverrides) } : {}),
        ...(variantRefShape ? { variant: $.val(variantRefShape) } : {}),
        ...(variantOverrideShapes.length > 0
            ? {
                  variantOverrides: $.val(new ArrayShape({ source: record, elements: variantOverrideShapes })),
              }
            : {}),
    }))

    const activityDefKey = ACTIVITY_DEF_SYS_ID_TO_KEY[activityDefSysId]
    if (!activityDefKey) {
        return { success: false }
    }

    // Determine which input and experience property fields are allowed for this
    // activity definition. Only emit fields that are listed in its inputDisplayPreferences /
    // experienceDisplayPreferences so that internal-only default fields (not
    // intended to be user-configurable) are excluded from the generated Fluent output.
    const allowedInputFields: Set<string> | undefined = ACTIVITY_DEF_INPUT_DISPLAY_PREFS[activityDefSysId]
    const allowedExperienceFields: Set<string> | undefined = ACTIVITY_DEF_EXPERIENCE_DISPLAY_PREFS[activityDefSysId]

    const elements = activityDefKey.split('.')
    if (elements.length < 2) {
        return { success: false }
    }

    const activityDefShape = new PropertyAccessShape({
        source: record,
        elements: elements as [unknown, unknown, ...unknown[]],
    })

    // Build inputs and experienceProperties from sys_variable_value descendants
    const variableValueRecords = database.query(SYS_VARIABLE_VALUE_TABLE, {
        document_key: record.getId().getValue(),
    })

    // Query sys_element_mapping records to recover pill references.
    // The platform stores pill values in sys_element_mapping.value (not
    // sys_variable_value.value), so we must consult both to faithfully
    // round-trip pill-containing fields.
    const elementMappingRecords = database.query(SYS_ELEMENT_MAPPING_TABLE, {
        id: record.getId().getValue(),
    })
    // Inputs and experience properties can share the same field name.
    // Use the `table` column to tell them apart:
    //   inputs:               table = var__m_sys_hub_{flow|action}_input_<sysId>
    //   experience properties: table = var__m_sys_pd_activity_type_prop_<sysId>
    const inputElementMappingByField = new Map<string, string>()
    const expPropElementMappingByField = new Map<string, string>()
    for (const emRecord of elementMappingRecords) {
        const field = emRecord.get('field').ifString()?.getValue()
        const value = emRecord.get('value').ifString()?.getValue()
        const table = emRecord.get('table').ifString()?.getValue() ?? ''
        if (field && value) {
            if (table.includes('sys_pd_activity_type_prop')) {
                expPropElementMappingByField.set(field, value)
            } else {
                inputElementMappingByField.set(field, value)
            }
        }
    }
    const inputs: Record<string, Shape> = {}
    const experienceProperties: Record<string, Shape> = {}
    /** For Decision activities: maps branch GUID → Fluent branch id */
    let branchMap: Map<string, string> | undefined
    for (const varRecord of variableValueRecords) {
        const variableSysId = varRecord.get('variable').ifString()?.getValue()
        if (!variableSysId) {
            continue
        }

        // Decision branches need special JSON parsing (not a plain string value)
        // Match on the exact sys_id to avoid collisions with other automations that may have a 'branches' input
        if (variableSysId === DECISION_BRANCHES_VAR_SYS_ID) {
            const jsonStr = varRecord.get('value').ifString()?.getValue()
            const parsedBranches = jsonStr
                ? parseDecisionBranchesToShape(jsonStr, varRecord, activityPillContext)
                : undefined
            if (parsedBranches) {
                inputs['branches'] = parsedBranches.branches
                branchMap = parsedBranches.branchMap
            }
            continue
        }

        // Go Back's target fields hold a raw activity/lane GUID, not a literal string — resolve
        // it back to a scope-aware raw lane/activity reference (bare IdentifierShape or, for a
        // cross-lane activity target, a laneVar.activityVar PropertyAccessShape) via the
        // whole-playbook guidToVarPath.
        const goBackFieldName = GO_BACK_TARGET_VAR_SYS_ID_TO_FIELD[variableSysId]
        if (goBackFieldName) {
            const isStage = goBackFieldName === 'go_back_to_target_stage'
            if (allowedInputFields === undefined || allowedInputFields.has(goBackFieldName)) {
                const targetGuid = varRecord.get('value').ifString()?.getValue()
                const targetShape = resolveGoBackTargetShape(
                    varRecord,
                    isStage,
                    targetGuid,
                    ownLaneVarName(record, guidToVarPath),
                    guidToVarPath
                )
                if (targetShape) {
                    inputs[goBackFieldName] = targetShape
                }
            }
            continue
        }

        const inputEntry = INPUT_SYS_ID_TO_FLUENT[variableSysId]
        if (inputEntry) {
            const shape = resolveVarEntryToShape(
                inputEntry,
                allowedInputFields,
                inputElementMappingByField,
                varRecord,
                activityPillContext
            )
            if (shape !== undefined) {
                inputs[inputEntry.name] = shape
            }
            continue
        }

        const experiencePropertyEntry = EXPERIENCE_PROPERTY_SYS_ID_TO_FLUENT[variableSysId]
        if (experiencePropertyEntry) {
            const shape = resolveVarEntryToShape(
                experiencePropertyEntry,
                allowedExperienceFields,
                expPropElementMappingByField,
                varRecord,
                activityPillContext
            )
            if (shape !== undefined) {
                experienceProperties[experiencePropertyEntry.name] = shape
            }
        }
    }

    // Build args array for 4-param API: Activity(def, config, inputs?, experienceProperties?)
    const args: Shape[] = [activityDefShape, configShape]

    const hasInputs = Object.keys(inputs).length > 0
    const hasExperienceProps = Object.keys(experienceProperties).length > 0

    if (hasInputs || hasExperienceProps) {
        // Add inputs (empty object if only experienceProperties exist)
        args.push(new ObjectShape({ source: record, properties: hasInputs ? inputs : {} }))
    }
    if (hasExperienceProps) {
        args.push(new ObjectShape({ source: record, properties: experienceProperties }))
    }

    const value = new CallExpressionShape({
        source: record,
        callee: ACTIVITY_GENERATED_CALLEE,
        args,
    })
    const result: ActivityToShapeResult = {
        success: true,
        value,
        usesParentRecord: shapeUsesParamsParameter(value),
    }
    if (branchMap) {
        result.branchMap = branchMap
    }
    return result
}
