function isVariableStatementForCallee(statement: ts.Statement, callees: string[]): boolean {
    return (
        ts.Node.isVariableStatement(statement) &&
        statement.getDeclarations().some((declaration) => {
            const expr = declaration.getInitializerIfKind(ts.SyntaxKind.CallExpression)?.getExpression().getText()
            return expr !== undefined && callees.includes(expr)
        })
    )
}

function shouldWholeReplaceInterleavedPlaybookBody(target: ts.Node): boolean {
    if (ts.Node.isExpressionStatement(target)) {
        target = target.getExpression()
    }
    if (!ts.Node.isCallExpression(target)) {
        return false
    }
    const bodyArg = target.getArguments()[2]
    if (!bodyArg || !ts.Node.isObjectLiteralExpression(bodyArg)) {
        return false
    }
    const lanesProp = bodyArg.getProperty('lanes')
    if (!lanesProp || !ts.Node.isPropertyAssignment(lanesProp)) {
        return false
    }
    const lanesArrow = lanesProp.getInitializerIfKind(ts.SyntaxKind.ArrowFunction)
    const lanesBody = lanesArrow?.getBody()
    if (!lanesBody || !ts.Node.isBlock(lanesBody)) {
        return false
    }
    const statements = lanesBody.getStatements()
    const hasLaneSibling = statements.some((statement) =>
        isVariableStatementForCallee(statement, ['wfa.playbook.lane', 'Lane'])
    )
    const hasStageLevelActivitySibling = statements.some((statement) =>
        isVariableStatementForCallee(statement, [ACTIVITY_API_NAME, 'wfa.playbook.activity'])
    )
    return hasLaneSibling && hasStageLevelActivitySibling
}

/**
 * Build an interleaved ArrowFunctionShape containing Lane entries alongside lane-less
 * entries — stage-level Decisions and global optional activities — sorted by `order`
 * field. Decisions are processed first to accumulate branchGuidMap so that lanes'
 * startRule can resolve branch references (e.g. decision_0.branches.critical).
 */
function buildInterleavedBodyToShape(
    source: SdkRecord,
    laneRecords: SdkRecord[],
    lanelessActivityRecords: SdkRecord[],
    database: Database,
    timerRecords: SdkRecord[],
    globalActivityMap: Map<string, ActivityIdentifier>,
    activityGuidToNowId: Map<string, NowIdShape>,
    diagnostics: Diagnostics,
    // Built once by the caller (see utils/guid-to-var-path-map.ts).
    guidToVarPath: GuidToVarPath,
    // Every activity in the playbook, already queried once at the playbook level; threaded through
    // to laneRecordToShape so each lane's own activities are filtered from it instead of re-queried.
    allActivities: SdkRecord[],
    // sys_pd_activity_override descendants for the whole playbook, threaded down to each
    // activity in this lane's collection.
    overrideRecords?: SdkRecord[],
    // Variant guid -> property-name key, threaded down for reconstructing
    // `params.variants.<key>` references.
    variantGuidToKey?: Map<string, string>
): ArrowFunctionShape {
    // Ordering and lane_i / decision_i / activity_i naming come from var-naming.ts — the same
    // helpers the whole-playbook pre-pass uses, so both assign the same names.
    const { ordered: entries } = orderAndNameInterleaved(laneRecords, lanelessActivityRecords)

    // Register lane-less entries (stage-level Decisions and global optional activities) in the
    // global activity map so that pill references in lane conditions and branch conditions
    // resolve. They have no lane, so laneVarName is omitted.
    for (const entry of entries) {
        if (entry.type !== 'lane') {
            globalActivityMap.set(entry.record.getId().getValue(), { varName: entry.varName })
        }
    }

    const pillContext: PillTransformContext = { activityMap: globalActivityMap }

    // First pass: process decisions to build branchGuidMap
    const branchGuidMap = new Map<string, { activityVarName: string; fluentBranchId: string }>()

    for (const { record: rec, type, varName } of entries) {
        if (type !== 'decision') {
            continue
        }
        const result = activityRecordToShape(
            rec,
            database,
            guidToVarPath,
            branchGuidMap,
            pillContext,
            timerRecords,
            overrideRecords,
            variantGuidToKey
        )
        if (result.success && result.branchMap) {
            for (const [branchGuid, fluentBranchId] of result.branchMap) {
                branchGuidMap.set(branchGuid, { activityVarName: varName, fluentBranchId })
            }
        }
    }

    // Second pass: process all entries in order, building shapes
    const statements: Shape[] = []
    const returnEntries: Record<string, Shape> = {}
    // Whether any reconstructed lane or stage-level decision references params.parentRecord —
    // if so the lanes callback must declare a `params` parameter for those pills to resolve.
    let lanesUseParentRecord = false

    for (const { record: rec, type, varName } of entries) {
        if (type !== 'lane') {
            const result = activityRecordToShape(
                rec,
                database,
                guidToVarPath,
                branchGuidMap,
                pillContext,
                timerRecords,
                overrideRecords,
                variantGuidToKey
            )
            if (result.success) {
                lanesUseParentRecord = lanesUseParentRecord || result.usesParentRecord
                statements.push(
                    new VariableStatementShape({ source, variableName: varName, initializer: result.value })
                )
                returnEntries[varName] = new IdentifierShape({ source, name: varName })
            }
        } else {
            const result = laneRecordToShape(
                rec,
                database,
                diagnostics,
                guidToVarPath,
                timerRecords,
                globalActivityMap,
                branchGuidMap,
                activityGuidToNowId,
                allActivities,
                overrideRecords,
                variantGuidToKey
            )
            if (result.success) {
                lanesUseParentRecord = lanesUseParentRecord || result.usesParentRecord
                statements.push(
                    new VariableStatementShape({ source, variableName: varName, initializer: result.value })
                )
                returnEntries[varName] = new IdentifierShape({ source, name: varName })
            }
        }
    }

    const parameters = lanesUseParentRecord ? [PERMISSIONS_PARAM_NAME] : []

    // Empty collection: concise form `() => ({})`
    if (statements.length === 0) {
        return new ArrowFunctionShape({
            source,
            parameters,
            returnValue: new ObjectShape({ source, properties: {} }),
            implicitReturn: true,
        })
    }

    return new ArrowFunctionShape({
        source,
        parameters,
        statements,
        returnValue: new ObjectShape({ source, properties: returnEntries }),
    })
}

/**
 * Function that ties in all xml changes to one playbook xml
 * For each XML file for playbook root, gather all related descendants
 * Dedupe them by sys_id and Write each one into same XML.
 */
async function playbookToFile(
    record: SdkRecord,
    { config, descendants, transform }: RecordContext
): Promise<Result<OutputFile>> {
    const recordBuilder = unloadBuilder(record.getTable())
    const bundledRecords = new Map<string, SdkRecord>()

    for (const bundledRecord of [...record.flat(), ...descendants.query()]) {
        bundledRecords.set(bundledRecord.getId().getValue(), bundledRecord)
    }

    // Lanes/activities/variants carry no sys_scope, so a plain per-row DELETE update can't be
    // coalesced on the instance and is silently dropped. Sweep instead: on every build, declare
    // which rows currently exist under this process definition and let the platform delete the rest.
    const processDefinitionId = record.getId().getValue()
    for (const childTable of [LANE_TABLE, ACTIVITY_TABLE, VARIANT_TABLE]) {
        const survivorIds = [...bundledRecords.values()]
            .filter((bundledRecord) => bundledRecord.getTable() === childTable)
            .map((bundledRecord) => bundledRecord.getId().getValue())
        recordBuilder.recordUpdateElements.push({
            type: 'element',
            name: childTable,
            attributes: {
                action: 'delete_multiple',
                query: buildDeleteMultipleQuery(processDefinitionId, survivorIds),
            },
        })
    }

    for (const bundledRecord of bundledRecords.values()) {
        const updateName = await transform.getUpdateName(bundledRecord)
        const builder = recordBuilder.record(bundledRecord)
        builder.addSysScope(config.scope, config.scopeId)
        builder.field('sys_update_name', updateName)

        bundledRecord
            .entries()
            .filter(([prop]) => prop !== 'sys_scope' && prop !== 'sys_update_name')
            .sort(([a], [b]) => a.localeCompare(b))
            .forEach(([prop, shape]) => {
                builder.field(prop, shape)
            })
    }

    return {
        success: true,
        value: {
            source: record,
            name: `${record.getTable()}_${record.getId().getValue()}.xml`,
            category: record.getInstallCategory(),
            content: recordBuilder.end(),
        },
    }
}

export const PlaybookDefinitionPlugin = Plugin.create({
    name: 'PlaybookDefinitionPlugin',
    records: {
        [PLAYBOOK_PROCESS_TYPE_TABLE]: {
            coalesce: ['name'],
        },
        [TIMER_ATTRIBUTES_TABLE]: {
            coalesce: ['source', 'source_type'],
        },
        [PROCESS_INPUT_TABLE]: {
            coalesce: ['element', 'model'],
        },
        [PLAYBOOK_OUTPUT_TABLE]: {
            coalesce: ['element', 'model'],
        },
        [PLAYBOOK_TABLE]: {
            relationships: {
                [PLAYBOOK_PROCESS_TYPE_TABLE]: {
                    via: 'process_type',
                    inverse: true,
                },
                [PROCESS_INPUT_TABLE]: {
                    via: 'model',
                    descendant: true,
                    relationships: {
                        sys_documentation: {
                            via: { name: 'name', element: 'element' },
                            descendant: true,
                        },
                        sys_choice: {
                            via: { name: 'name', element: 'element' },
                            descendant: true,
                        },
                    },
                },
                [PLAYBOOK_OUTPUT_TABLE]: {
                    via: 'model',
                    descendant: true,
                    relationships: {
                        sys_documentation: {
                            via: { name: 'name', element: 'element' },
                            descendant: true,
                        },
                        sys_choice: {
                            via: { name: 'name', element: 'element' },
                            descendant: true,
                        },
                    },
                },
                [TRIGGER_INSTANCE_TABLE]: {
                    via: 'process_definition',
                    descendant: true,
                    relationships: {
                        [SYS_VARIABLE_VALUE_TABLE]: {
                            via: 'document_key',
                            descendant: true,
                        },
                        [SYS_ELEMENT_MAPPING_TABLE]: {
                            via: 'id',
                            descendant: true,
                        },
                    },
                },
                [LANE_TABLE]: {
                    via: 'process_definition',
                    descendant: true,
                    relationships: {
                        [ACTIVITY_TABLE]: {
                            via: 'lane',
                            descendant: true,
                            relationships: {
                                [SYS_VARIABLE_VALUE_TABLE]: {
                                    via: 'document_key',
                                    descendant: true,
                                },
                                sys_element_mapping: {
                                    via: 'id',
                                    descendant: true,
                                },
                                [ACTIVITY_ACTION_OVERRIDE_TABLE]: {
                                    via: 'activity',
                                    descendant: true,
                                },
                                [OVERRIDE_TABLE]: {
                                    via: 'override_parent',
                                    descendant: true,
                                },
                            },
                        },
                    },
                },
                [TIMER_ATTRIBUTES_TABLE]: {
                    via: 'process_definition',
                    descendant: true,
                },
                [ACTIVITY_TABLE]: {
                    via: 'process_definition',
                    descendant: true,
                    relationships: {
                        [OVERRIDE_TABLE]: {
                            via: 'override_parent',
                            descendant: true,
                        },
                    },
                },
                [VARIANT_TABLE]: {
                    via: 'process_definition',
                    descendant: true,
                },
                [SYS_VARIABLE_VALUE_TABLE]: {
                    via: 'document_key',
                    descendant: true,
                },
                [ATTACHMENT_TABLE]: {
                    via: 'table_sys_id',
                    descendant: true,
                    relationships: {
                        [ATTACHMENT_DOC_TABLE]: {
                            via: 'sys_attachment',
                            descendant: true,
                        },
                    },
                },
            },
            toFile: playbookToFile,
            async toShape(record, { descendants, database, logger, diagnostics }) {
                // Check for unsupported features (including schema_version) - fallback to RecordPlugin if found
                if (isPlaybookUnsupported(record, database, logger, descendants)) {
                    return { success: false }
                }

                const preservedAttachment = findProcessDefinitionAttachment(record)

                const configShape = buildPlaybookConfigToShape(record, database)

                // Check for parent_record process input to extract parentTable.
                // Only inject parentTable into the generated Fluent when we have a
                // real, non-empty reference value — injecting '' would trigger the
                // diagnostics plugin's empty-parentTable check on round-trip. Skip entirely
                // for on_demand playbooks: their parent_record input is the auto-generated
                // sys_playbook_execution reference (see toRecord below), not a user-declared
                // parentTable, and reconstructing it as one would violate the
                // parentTable-disallowed-for-on_demand restriction on rebuild.
                const recordExecutionType = record.get('execution_type')?.ifString()?.getValue() ?? ''
                const processInputRecords = descendants.query(PROCESS_INPUT_TABLE)
                const parentRecordInput = processInputRecords.find(
                    (r) => r.get('element')?.ifString()?.getValue() === PARENT_RECORD.ELEMENT
                )
                const parentTableRef =
                    recordExecutionType === ON_DEMAND
                        ? undefined
                        : parentRecordInput?.get('reference')?.ifString()?.getValue()
                const finalConfigShape = parentTableRef
                    ? configShape.merge({ parentTable: parentTableRef })
                    : configShape

                // Query timer attribute descendants for distribution to lanes and activities
                const timerRecords = descendants.query(TIMER_ATTRIBUTES_TABLE)

                // Query variant-override descendants for distribution to activities (variant
                // start_rule/order overrides). Filtered per-activity by override_parent downstream.
                const overrideRecords = descendants.query(OVERRIDE_TABLE)

                // Shared mutable map populated incrementally by each lane's
                // buildActivityCollectionToShape, using the canonical topo-sort
                // order so variable names are guaranteed to align.
                const globalActivityMap = new Map<string, ActivityIdentifier>()

                // Map every activity's guid → its Now.ID shape, so cross-scope
                // activityRef() pills in playbook/lane permissions can be regenerated
                // (the referenced activity is not in lexical scope from a permissions callback).
                const allActivities = descendants.query(ACTIVITY_TABLE)
                const activityGuidToNowId = new Map<string, NowIdShape>()
                for (const activity of allActivities) {
                    activityGuidToNowId.set(activity.getId().getValue(), NowIdShape.from(activity))
                }

                const configExtensions: Record<string, Shape> = {}

                // Build inputs shape from process inputs, excluding parent_record (handled by parentTable)
                const nonParentInputRecords = processInputRecords.filter(
                    (r) => r.get('element')?.ifString()?.getValue() !== PARENT_RECORD.ELEMENT
                )
                const inputs = buildPlaybookVariableShapes(nonParentInputRecords, descendants)
                if (inputs && Object.keys(inputs).length > 0) {
                    configExtensions['inputs'] = new ObjectShape({
                        source: record,
                        properties: inputs,
                    })
                }

                // Build launcherInputs from sys_variable_value records anchored to the
                // playbook itself. Descendant queries are flattened across the whole tree,
                // so filter to only this playbook's own document/document_key pair —
                // excludes activity- and trigger-level sys_variable_value rows that share
                // the same table.
                const launcherInputVariableValueRecords = descendants
                    .query(SYS_VARIABLE_VALUE_TABLE)
                    .filter(
                        (r) =>
                            r.get('document')?.ifString()?.getValue() === PLAYBOOK_TABLE &&
                            r.get('document_key')?.ifString()?.getValue() === record.getId().getValue()
                    )
                const launcherInputs = buildLauncherInputShapes(
                    launcherInputVariableValueRecords,
                    nonParentInputRecords
                )
                if (launcherInputs && Object.keys(launcherInputs).length > 0) {
                    configExtensions['launcherInputs'] = new ObjectShape({
                        source: record,
                        properties: launcherInputs,
                    })
                }

                // Build outputs shape from process output descendants
                const outputs = buildPlaybookVariableShapes(descendants.query(PLAYBOOK_OUTPUT_TABLE), descendants)
                if (outputs && Object.keys(outputs).length > 0) {
                    configExtensions['outputs'] = new ObjectShape({
                        source: record,
                        properties: outputs,
                    })
                }

                // Reconstruct evaluateVariantChildrenAfter as Now.ID['<key>'] by looking up the
                // persisted activity GUID in the same map used for cross-scope activityRef() pills.
                const evaluateVariantChildrenAfterGuid = record
                    .get('evaluate_variant_children_after')
                    ?.ifString()
                    ?.getValue()
                if (evaluateVariantChildrenAfterGuid) {
                    const nowId =
                        activityGuidToNowId.get(evaluateVariantChildrenAfterGuid) ??
                        new NowIdShape({ source: record, id: evaluateVariantChildrenAfterGuid })
                    configExtensions['evaluateVariantChildrenAfter'] = nowId
                }

                // Build triggers shape
                const triggerRecords = descendants.query(TRIGGER_INSTANCE_TABLE)
                const triggersArray = buildTriggersArrayToShape({
                    source: record,
                    triggerRecords,
                    descendants,
                })
                // Merge inputs/outputs into the config shape.
                const finalConfigWithIO = finalConfigShape.merge(configExtensions)

                // Reconstruct the playbook permissions callback from the permission JSON.
                // Omitted entirely when permissions are empty, to keep generated code clean.
                const permissionsArrow = buildPlaybookPermissionsToShape(
                    record.get('permission')?.ifString()?.getValue(),
                    record,
                    activityGuidToNowId,
                    diagnostics
                )

                // Query lane descendants
                const laneRecords = descendants.query(LANE_TABLE)

                // Query variant descendants and build the optional `variants` dependent-config
                // property (declared alongside `triggers`, per the same 2nd-argument placement
                // as the rest of PlaybookDependentConfig). Omitted entirely when there are no
                // variants, to keep generated code clean and preserve round-trip fidelity for
                // playbooks without variants.
                const variantRecords = descendants.query(VARIANT_TABLE)
                const variantDependencyGuids = (rec: SdkRecord) => {
                    const parentVariantGuid = rec.get('parent_variant')?.ifString()?.getValue() ?? ''
                    return parentVariantGuid ? [parentVariantGuid] : []
                }

                // Map every variant's guid -> its property-name key (e.g. "variant_0"), so
                // activity-level `variant`/`variantOverrides[].variant` fields can be
                // reconstructed as `params.variants.<key>` references (mirrors
                // activityGuidToNowId's role for activityRef()). Sorted identically to how
                // buildChildCollectionToShape below assigns `variant_${i}` variable names, so
                // the two stay in sync.
                const sortedVariantRecords = topologicalSort(variantRecords, variantDependencyGuids)
                const variantGuidToKey = new Map<string, string>()
                for (const [i, variant] of sortedVariantRecords.entries()) {
                    variantGuidToKey.set(variant.getId().getValue(), `variant_${i}`)
                }

                const variantsArrow =
                    variantRecords.length > 0
                        ? buildChildCollectionToShape({
                              source: record,
                              childRecords: variantRecords,
                              database,
                              varPrefix: 'variant',
                              collectionParamName: PERMISSIONS_PARAM_NAME,
                              recordToShape: (rec, db, guidMap) => variantRecordToShape(rec, db, guidMap),
                              getDependencyGuids: variantDependencyGuids,
                          })
                        : undefined

                // The 2nd PlaybookDefinition argument: the dependent config holding optional
                // `permissions`, `variants`, and the `triggers` array. Always emit `triggers`
                // (even when empty) so the signature is consistent => `{ triggers: [] }` —
                // except for on_demand playbooks, where `triggers` is unconfigurable (typed
                // `never`) and must be omitted entirely, or the reconstructed Fluent would fail
                // to rebuild.
                const dependentConfigShape: Shape = new ObjectShape({
                    source: record,
                    properties: {
                        ...(permissionsArrow ? { permissions: permissionsArrow } : {}),
                        ...(variantsArrow ? { variants: variantsArrow } : {}),
                        ...(preservedAttachment
                            ? {
                                  preservedAttachment: buildPreservedAttachmentShape(
                                      record,
                                      preservedAttachment.fileName,
                                      preservedAttachment.shape
                                  ),
                              }
                            : {}),
                        ...(recordExecutionType === ON_DEMAND
                            ? {}
                            : {
                                  triggers:
                                      triggersArray ??
                                      new ArrayShape({
                                          source: record,
                                          elements: [],
                                      }),
                              }),
                    },
                })

                // Query lane-less activities — stage-level Decisions as well as global
                // optional activities. buildInterleavedBodyToShape distinguishes between
                // the two by activity_definition when assigning variable names.
                const lanelessActivities = allActivities.filter((rec) => {
                    const laneVal = rec.get('lane')?.ifString()?.getValue() ?? ''
                    return laneVal === ''
                })

                // Whole-playbook variable info, built once here — before any of the incremental
                // per-level reconstruction below — so every reference (a sibling Run.After, a
                // cross-lane pill, a Go Back target) resolves against the same names, whichever
                // collection level is being reconstructed.
                const guidToVarPath = buildGuidToVarPathMap(laneRecords, allActivities)

                // If no lane-less activities, keep original behavior (lanes only)
                if (lanelessActivities.length === 0) {
                    const lanesArrow = buildChildCollectionToShape({
                        source: record,
                        childRecords: laneRecords,
                        database,
                        varPrefix: 'lane',
                        collectionParamName: PERMISSIONS_PARAM_NAME,
                        recordToShape: (rec, db) => {
                            const result = laneRecordToShape(
                                rec,
                                db,
                                diagnostics,
                                guidToVarPath,
                                timerRecords,
                                globalActivityMap,
                                undefined /* branchGuidMap: no stage-level branches in the lanes-only path */,
                                activityGuidToNowId,
                                allActivities,
                                overrideRecords,
                                variantGuidToKey
                            )
                            return result.success
                                ? { success: true, value: result.value, usesCollectionParam: result.usesParentRecord }
                                : result
                        },
                        getDependencyGuids: startsAfterLanes,
                    })

                    const bodyShape = new ObjectShape({
                        source: record,
                        properties: { lanes: lanesArrow },
                    })

                    return {
                        success: true,
                        value: new CallExpressionShape({
                            source: record,
                            callee: PLAYBOOK_API_NAME,
                            args: [finalConfigWithIO, dependentConfigShape, bodyShape],
                        }),
                    }
                }

                // Lane-less activities exist: build interleaved body
                const lanesArrow = buildInterleavedBodyToShape(
                    record,
                    laneRecords,
                    lanelessActivities,
                    database,
                    timerRecords,
                    globalActivityMap,
                    activityGuidToNowId,
                    diagnostics,
                    guidToVarPath,
                    allActivities,
                    overrideRecords,
                    variantGuidToKey
                )

                const bodyShape = new ObjectShape({
                    source: record,
                    properties: { lanes: lanesArrow },
                })

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: record,
                        callee: PLAYBOOK_API_NAME,
                        args: [finalConfigWithIO, dependentConfigShape, bodyShape],
                    }),
                }
            },
        },
    },
    shapes: [
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],
            // Override commit so legacy interleaved PlaybookDefinition bodies can be whole-replaced.
            // The default incremental CallExpression reconciliation is what OOMs on that mixed-body shape.
            async commit(shape, target, { commit }) {
                if (shape.getCallee() !== PLAYBOOK_API_NAME) {
                    return { success: false }
                }
                const normalizedTarget = ts.Node.isExpressionStatement(target) ? target.getExpression() : target
                if (!ts.Node.isCallExpression(normalizedTarget)) {
                    normalizedTarget.replaceWithText(shape.getCode())
                    return { success: true }
                } else if (shouldWholeReplaceInterleavedPlaybookBody(normalizedTarget)) {
                    if (normalizedTarget.getText() !== shape.getCode()) {
                        normalizedTarget.replaceWithText(shape.getCode())
                    }
                    return { success: true }
                }

                const callee = normalizedTarget.getExpression()
                if (callee.getText() !== shape.getCallee()) {
                    callee.replaceWithText(shape.getCallee())
                }

                const targetArguments = normalizedTarget.getArguments()
                const shapeArguments = shape.getArguments(false)
                for (let i = targetArguments.length - 1; i >= shapeArguments.length; i--) {
                    normalizedTarget.removeArgument(i)
                }

                for (const [i, targetElement] of normalizedTarget.getArguments().entries()) {
                    const shapeArgument = shape.getArgument(i, false)
                    if (!shapeArgument) {
                        continue
                    }
                    await commit(shapeArgument, targetElement)
                }

                const argumentsToAdd = shapeArguments
                    .slice(normalizedTarget.getArguments().length)
                    .map((arg) => arg.getCode())
                if (argumentsToAdd.length > 0) {
                    normalizedTarget.addArguments(argumentsToAdd)
                }

                return { success: true }
            },
            async toRecord(callExpression, { factory, transform, diagnostics, compiler, project, logger }) {
                if (callExpression.getCallee() !== PLAYBOOK_API_NAME) {
                    return { success: false }
                }

                const config = callExpression.getArgument(0).asObject()

                // Remind the user that deploying a playbook does not auto-activate changes at
                // runtime — surfaced in both the Fluent CLI and the Builder agent output.
                const playbookLabel = config.get('label')?.ifString()?.getValue() ?? ''
                logger.info(
                    `Playbook "${playbookLabel}" built. For any new changes to take effect at runtime, ` +
                        `open Playbook Designer and activate the playbook again.`
                )

                // Compute name value: use explicit name if provided, otherwise slugify from label
                const nameShape = config.get('name')
                const nameProvided = nameShape?.isDefined() && !nameShape?.isUndefined()
                let computedName: string | undefined
                if (!nameProvided) {
                    const labelVal = config.get('label')?.ifString()?.getValue()
                    computedName = labelVal ? slugifyString(labelVal) : ''
                }

                const processTypeShape = config.get('processType')
                const processTypeName = processTypeShape.ifString()?.getValue()?.trim()
                const mappedProcessTypeSysId =
                    processTypeName && processTypeName !== '' ? getPlaybookProcessTypeSysId(processTypeName) : undefined
                if (processTypeName && processTypeName !== '' && !mappedProcessTypeSysId) {
                    diagnostics.error(
                        processTypeShape,
                        `Unsupported processType "${processTypeName}". We do not have that process type defined in the SDK mapping.`
                    )
                    return { success: false }
                }
                const resolvedProcessType =
                    processTypeName && processTypeName !== ''
                        ? mappedProcessTypeSysId!
                        : PLAYBOOK_DEFAULT_PROCESS_TYPE_DB

                // Resolve the 2nd-arg `permissions` callback into the playbook's permission JSON.
                // Cross-scope activityRef() pills are validated against every activity id in the body;
                // the same set is threaded into lanes for their own permissions.
                const activityNowIdKeys = collectActivityNowIdKeysForPermissions(callExpression.getArgument(2))
                const dependentConfig = callExpression.getArgument(1)?.ifObject()?.asObject()
                const executionType =
                    config.get('executionType')?.ifString()?.getValue() ?? PLAYBOOK_DEFAULTS.EXECUTION_TYPE
                const permission = await buildPlaybookPermissions(dependentConfig?.get('permissions'), {
                    factory,
                    diagnostics,
                    activityIds: activityNowIdKeys,
                    executionType,
                    dependentConfig: dependentConfig ?? callExpression,
                })

                let playbookRecord = await factory.createRecord({
                    source: callExpression,
                    table: PLAYBOOK_TABLE,
                    explicitId: config.get('$id'),
                    properties: buildPlaybookRecordProperties(
                        config,
                        computedName,
                        !!nameProvided,
                        resolvedProcessType,
                        playbookLabel,
                        permission
                    ),
                })

                // Create sys_pd_process_input for parent_record if parentTable is set
                // (record_driven), or referencing sys_playbook_execution when executionType is
                // 'on_demand' — on-demand playbooks have no triggering record, so the platform
                // points parent_record at the execution record itself instead. Not exposed as
                // params.parentRecord in Fluent either way.
                const parentTableVal = config.get('parentTable')?.ifString()?.getValue()
                const parentRecordReference =
                    executionType === ON_DEMAND ? SYS_PLAYBOOK_EXECUTION_TABLE : parentTableVal
                let parentRecordInputRecord: Awaited<ReturnType<typeof factory.createRecord>> | undefined
                if (parentRecordReference) {
                    parentRecordInputRecord = await factory.createRecord({
                        source: callExpression,
                        table: PROCESS_INPUT_TABLE,
                        properties: {
                            element: PARENT_RECORD.ELEMENT,
                            label: PARENT_RECORD.LABEL,
                            internal_type: PARENT_RECORD.INTERNAL_TYPE,
                            reference: parentRecordReference,
                            order: PARENT_RECORD.ORDER,
                            mandatory: false,
                            active: true,
                            max_length: PARENT_RECORD.MAX_LENGTH,
                            model: playbookRecord,
                            model_id: playbookRecord,
                            model_table: '',
                            name: `var__m_${PROCESS_INPUT_TABLE}_${playbookRecord.getId().getValue()}`,
                            attributes: PARENT_RECORD.ATTRIBUTES,
                        },
                    })
                }

                // inputs/outputs live on the 1st-arg config (next to parentTable);
                const triggersCallback = callExpression.getArgument(1)
                const relatedRecords: SdkRecord[] = []

                // Rebuild the preserved image attachment's sys_attachment/sys_attachment_doc
                // records, if one survived the transform round trip in the dependent config's
                // preservedAttachment. ATTACHMENT_TABLE is declared as a descendant of
                // PLAYBOOK_TABLE (via table_sys_id, see the relationships map above), so bundling
                // these onto playbookRecord here is all that's needed for playbookToFile's
                // descendants.query() walk to write them into the combined XML output, exactly
                // like every other descendant table.
                const preservedAttachment = readPreservedAttachmentConfig(dependentConfig)
                if (preservedAttachment) {
                    const attachmentShape = buildNowAttachShape(callExpression, preservedAttachment)
                    const attachmentRecords = await attachmentShape.createAssociatedRecords({
                        parentRecord: playbookRecord,
                        factory,
                        field: preservedAttachment.fileName,
                    })
                    relatedRecords.push(...attachmentRecords)
                }

                // Element names of the playbook's declared outputs. Threaded into lane/activity
                // shapes so the Set Playbook Outputs activity can reject assignments to outputs
                // that were never declared (validated in ActivityPlugin.toRecord).
                const declaredOutputElementNames = config.get('outputs')?.ifObject()?.asObject()?.keys() ?? []

                // inputs/outputs read from the config object (arg 0)
                {
                    const inputsConfig = config.get('inputs')?.ifObject()?.asObject()
                    if (inputsConfig) {
                        const RESERVED_INPUT_NAMES = [PARENT_RECORD.ELEMENT, PARENT_RECORD_MAPPER_KEY]
                        const parentRecordKey = inputsConfig.keys().find((k) => RESERVED_INPUT_NAMES.includes(k))
                        if (parentRecordKey) {
                            diagnostics.error(
                                inputsConfig.get(parentRecordKey),
                                `"${parentRecordKey}" is a reserved input name. Use parentRecord in the input mapper to set the parent record instead.`
                            )
                        } else if (!parentTableVal && executionType !== ON_DEMAND) {
                            diagnostics.error(
                                inputsConfig,
                                'Defining inputs requires a parentTable in the playbook config.'
                            )
                        } else {
                            const inputRecords = await buildPlaybookVariableRecords({
                                variablesConfig: inputsConfig,
                                parentRecord: playbookRecord,
                                factory,
                                diagnostics,
                                parentTable: PLAYBOOK_TABLE,
                                varTable: PROCESS_INPUT_TABLE,
                            })
                            // column_label and virtual_type are platform-managed constants required by
                            // the PAD designer — not exposed in the Fluent API and intentionally absent
                            // from toShape. use_reference_qualifier is derived from reference_qual, which
                            // buildPlaybookVariableRecords already set from the ReferenceColumn's
                            // referenceQual, if any.
                            const patchedInputs = inputRecords.map((r) => {
                                if (r.getTable() !== PROCESS_INPUT_TABLE) {
                                    return r
                                }
                                return r.merge({
                                    column_label: r.get('label').getValue(),
                                    attributes: PLAYBOOK_INPUT_ATTRIBUTES,
                                    model_table: '',
                                    use_reference_qualifier: r.get('reference_qual')?.ifString()?.getValue()
                                        ? 'advanced'
                                        : 'simple',
                                    virtual_type: 'script',
                                })
                            })
                            relatedRecords.push(...patchedInputs)
                        }
                    }

                    const outputsConfig = config.get('outputs')?.ifObject()?.asObject()
                    if (outputsConfig) {
                        // Unlike inputs, outputs have no dependency on parentTable — they don't
                        // reference the parent record, so a standalone playbook can declare them.
                        const outputRecords = await buildPlaybookVariableRecords({
                            variablesConfig: outputsConfig,
                            parentRecord: playbookRecord,
                            factory,
                            diagnostics,
                            parentTable: PLAYBOOK_TABLE,
                            varTable: PLAYBOOK_OUTPUT_TABLE,
                        })
                        // column_label and virtual_type are platform-managed constants required by
                        // the PAD designer — not exposed in the Fluent API and intentionally absent
                        // from toShape. use_reference_qualifier is derived from reference_qual, which
                        // buildPlaybookVariableRecords already set from the ReferenceColumn's
                        // referenceQual, if any.
                        const patchedOutputs = outputRecords.map((r) => {
                            if (r.getTable() !== PLAYBOOK_OUTPUT_TABLE) {
                                return r
                            }
                            return r.merge({
                                column_label: r.get('label').getValue(),
                                model_table: '',
                                use_reference_qualifier: r.get('reference_qual')?.ifString()?.getValue()
                                    ? 'advanced'
                                    : 'simple',
                                virtual_type: 'script',
                            })
                        })
                        relatedRecords.push(...patchedOutputs)
                    }
                }

                const playbookInputOnlyRecords = relatedRecords.filter((r) => r.getTable() === PROCESS_INPUT_TABLE)

                // launcherInputs prefills the on-demand launcher form for this playbook's own
                // declared inputs. Runs whenever there are playbook input records (even if
                // launcherInputs itself is omitted), since an input's own Column({ default: ... })
                // still needs a mirrored record. Structural validation (requires inputs to be
                // declared, keys must match a declared input) lives in PlaybookDiagnosticsPlugin.
                const launcherInputsConfig = config.get('launcherInputs')?.ifObject()?.asObject()
                if (playbookInputOnlyRecords.length > 0) {
                    const launcherInputRecords = await buildLauncherInputRecords({
                        launcherInputsConfig,
                        inputsConfig: config.get('inputs')?.ifObject()?.asObject(),
                        inputRecords: playbookInputOnlyRecords,
                        parentRecord: playbookRecord,
                        factory,
                        diagnostics,
                        launcherInUse: config.get('launcherShowRecordForm')?.ifBoolean()?.getValue() === true,
                    })
                    relatedRecords.push(...launcherInputRecords)
                }

                const triggerRecords = triggersCallback
                    ? await processTriggersArrayToRecord({
                          triggersObject: triggersCallback,
                          parentRecord: playbookRecord,
                          parentTable: parentTableVal,
                          parentRecordInputRecord,
                          playbookInputRecords: playbookInputOnlyRecords,
                          compiler,
                          rootDir: project.getRootDir(),
                          diagnostics,
                          transform,
                          factory,
                      })
                    : []

                // Extract body (argument 2) and process children
                const bodyArg = callExpression.getArgument(2)
                const lanesArrow = bodyArg?.asObject().get('lanes')
                const lanesArrowFn = lanesArrow?.is(ArrowFunctionShape) ? lanesArrow.as(ArrowFunctionShape) : undefined
                const playbookGraph = lanesArrowFn ? collectPlaybookGraph(lanesArrowFn) : undefined
                const playbookBodyParamsName = lanesArrowFn?.getParameters()[0]?.getName()
                const playbookBodyParamsNames: string[] = []
                if (playbookBodyParamsName) {
                    playbookBodyParamsNames.push(playbookBodyParamsName)
                }

                // Variants are processed in a separate pass, BEFORE lanes/activities: they have
                // their own sibling-reference field (`parentVariant`) and can't reference
                // activity output, so they don't participate in the lanes GUID/branch-map
                // threading below. Processing them first means their GUIDs (tracked in
                // variantKeyToGuid) are available for activities' `variant`/
                // `variantOverrides` fields, which reference variants by `params.variants.<key>`.
                // `variants` is declared on the 2nd argument (PlaybookDependentConfig), alongside
                // `permissions`/`triggers` — not on the body (3rd argument) like lanes.
                const variantsArrow = dependentConfig?.get('variants')
                const variantsArrowFn = variantsArrow?.is(ArrowFunctionShape)
                    ? variantsArrow.as(ArrowFunctionShape)
                    : undefined
                const variantPlaybookBodyParamsName = variantsArrowFn?.getParameters()[0]?.getName()

                // Only set when evaluateVariantChildrenAfter is configured: the set of activity
                // Now.ID keys guaranteed to have completed before that point, used to widen the
                // variant condition pill context (see VariantPlugin's toRecord).
                const evaluateVariantChildrenAfterKey = getNowIdKey(config.get('evaluateVariantChildrenAfter'))
                const ancestorActivityIds = evaluateVariantChildrenAfterKey
                    ? computeAncestorIds(evaluateVariantChildrenAfterKey, playbookGraph)
                    : undefined

                // VARIANT_ACTIVITY_BEFORE_EVALUATION_POINT: every variant-only activity (one
                // whose `variant` field is set) must be a guaranteed descendant of
                // evaluateVariantChildrenAfter — i.e. that point must be a guaranteed ancestor of
                // the activity, given the playbook's lane/activity Run.After structure. Skipped
                // entirely when evaluateVariantChildrenAfter is unset (default: evaluate at
                // playbook start), since every activity trivially satisfies it in that case.
                if (evaluateVariantChildrenAfterKey) {
                    for (const { key, variantShape } of collectVariantOnlyActivityKeys(playbookGraph)) {
                        const activityAncestorIds = computeAncestorIds(key, playbookGraph)
                        if (!activityAncestorIds.has(evaluateVariantChildrenAfterKey)) {
                            diagnostics.error(
                                variantShape,
                                'This variant-only activity is not guaranteed to run after ' +
                                    '`evaluateVariantChildrenAfter`. Variant-only activities must be a ' +
                                    "guaranteed descendant of the evaluation point given the playbook's " +
                                    'lane/activity ordering.'
                            )
                        }
                    }
                }

                // Deterministic sibling/parent collision-avoiding color assignment for every
                // variant, computed once up front over the whole `variants` arrow (see
                // computeVariantColorAssignments in variant-plugin.ts) and looked up per-variant
                // below when building each VariantShape.
                const variantColorAssignments = variantsArrowFn
                    ? computeVariantColorAssignments(variantsArrowFn)
                    : new Map<string, VariantColor>()

                const variantTypeConfig: ChildCollectionTypeConfig = {
                    createShape: (source, cfg, context) =>
                        new VariantShape({
                            source,
                            config: cfg,
                            ...(context?.nowIdKeyToGuid !== undefined
                                ? { nowIdKeyToGuid: context.nowIdKeyToGuid }
                                : {}),
                            playbookBodyParamsName: variantPlaybookBodyParamsName,
                            ancestorActivityIds,
                            assignedColor: variantColorAssignments.get(getNowIdKey(cfg.get('$id')) ?? ''),
                        }),
                    childPlugin: VariantPlugin,
                }
                const variantChildTypeMap = new Map<string, ChildCollectionTypeConfig>([
                    [VARIANT_GENERATED_CALLEE, variantTypeConfig],
                ])

                // Populated by the variants pass below with every variant's property-name key
                // (e.g. "vip") -> real GUID, so activities' `variant`/`variantOverrides` fields
                // (processed after) can resolve their `params.variants.<key>` references to a
                // real sys_pd_process_variant GUID.
                const variantKeyToGuid = new Map<string, string>()

                const variantRecords = variantsArrow?.is(ArrowFunctionShape)
                    ? await processChildCollectionToRecord({
                          collectionArrow: variantsArrow.as(ArrowFunctionShape),
                          parentRecord: playbookRecord,
                          parentFkField: 'processDefinition',
                          calleeNames: [VARIANT_GENERATED_CALLEE],
                          childTypeMap: variantChildTypeMap,
                          externalKeyToGuid: variantKeyToGuid,
                          resolveReferences: resolveParentVariant,
                          resolvedRefField: 'parentVariant',
                          transform,
                          diagnostics,
                          errorMessage: 'PlaybookDefinition variants function must return an object literal',
                          errorSource: callExpression,
                      })
                    : []

                // Per-callee dispatch for stage-level activity entries
                const activityTypeConfig: ChildCollectionTypeConfig = {
                    configArgIndex: 1,
                    createShape: (
                        source: Shape,
                        cfg: ObjectShape,
                        context?: { nowIdKeyToGuid?: Map<string, string>; playbookGraph?: PlaybookGraph }
                    ) => {
                        const callExpr = source.as(CallExpressionShape)
                        const arg2 = callExpr.getArgument(2)?.ifObject()
                        const arg3 = callExpr.getArgument(3)?.ifObject()
                        const argsObj = callExpr.getArgument(1)?.ifObject()
                        return new ActivityShape({
                            source,
                            activityDefinition: callExpr.getArgument(0, false),
                            config: cfg,
                            inputs: arg2 ?? argsObj?.get('inputs')?.ifObject(),
                            experienceProperties: arg3 ?? argsObj?.get('experienceProperties')?.ifObject(),
                            ...(context?.nowIdKeyToGuid !== undefined
                                ? { nowIdKeyToGuid: context.nowIdKeyToGuid }
                                : {}),
                            variantKeyToGuid,
                            ...(context?.playbookGraph !== undefined ? { playbookGraph: context.playbookGraph } : {}),
                            playbookBodyParamsNames,
                            declaredOutputElementNames,
                        })
                    },
                    childPlugin: ActivityPlugin,
                }
                const laneTypeConfig: ChildCollectionTypeConfig = {
                    createShape: (source, cfg, context) => {
                        const laneArg = source.is(CallExpressionShape)
                            ? source.as(CallExpressionShape).getArgument(0)?.ifObject()
                            : undefined
                        const activitiesShape = laneArg?.get('activities')
                        const activities = activitiesShape?.is(ArrowFunctionShape)
                            ? activitiesShape.as(ArrowFunctionShape)
                            : undefined
                        return new LaneShape({
                            source,
                            config: cfg,
                            activities,
                            ...(context?.nowIdKeyToGuid !== undefined
                                ? { nowIdKeyToGuid: context.nowIdKeyToGuid }
                                : {}),
                            variantKeyToGuid,
                            ...(context?.activityIds !== undefined ? { activityIds: context.activityIds } : {}),
                            ...(context?.playbookGraph !== undefined ? { playbookGraph: context.playbookGraph } : {}),
                            playbookBodyParamsName,
                            declaredOutputElementNames,
                        })
                    },
                    childPlugin: LanePlugin,
                }
                const childTypeMap = new Map<string, ChildCollectionTypeConfig>([
                    ['wfa.playbook.lane', laneTypeConfig],
                    ['Lane', laneTypeConfig],
                    [ACTIVITY_API_NAME, activityTypeConfig],
                    ['wfa.playbook.activity', activityTypeConfig],
                ])

                // Populated incrementally by processChildCollectionToRecord as every lane and
                // activity in the whole playbook body is created, so it ends up mapping every
                // activity/lane Now.ID key to its real GUID by the time that call returns —
                // used below to resolve evaluateVariantChildrenAfter against a real activity.
                const globalNowIdKeyToGuid = new Map<string, string>()

                // Single pass: process lanes and stage-level activities in declaration order.
                // Sequential processing ensures each entry sees GUIDs and branch maps
                // from everything declared before it.
                const allRecords = lanesArrow?.is(ArrowFunctionShape)
                    ? await processChildCollectionToRecord({
                          collectionArrow: lanesArrow.as(ArrowFunctionShape),
                          parentRecord: playbookRecord,
                          parentFkField: 'processDefinition',
                          calleeNames: ['wfa.playbook.lane', 'Lane', ACTIVITY_API_NAME, 'wfa.playbook.activity'],
                          childTypeMap,
                          activityIds: activityNowIdKeys,
                          externalNowIdKeyToGuid: globalNowIdKeyToGuid,
                          resolveReferences: resolveStartsAfterLanes,
                          resolvedRefField: 'startsAfterLanes',
                          resolveBranchReferences: resolveStartsAfterBranches,
                          resolvedBranchRefField: 'startsAfterBranches',
                          resolvedBranchActivityField: 'startsAfterActivities',
                          extractBranchIdMap: extractDecisionBranchIdMap,
                          externalPlaybookGraph: playbookGraph,
                          computePerChildMergeProps: (allConfigs, index, allCallees) => {
                              // De-dupe against the full pool of names. Explicit names are kept;
                              // generated names (slugified labels) yield to anything already taken,
                              // so an auto-generated name never collides with an explicit one.
                              // Children here are a mix of lanes and stage-level activities: strip
                              // HTML only for activities (the platform BR strips HTML from
                              // sys_pd_activity.label), while lane labels slug as-is.
                              const activityCallees = new Set([ACTIVITY_API_NAME, 'wfa.playbook.activity'])
                              const entries = allConfigs.map((c, i) => {
                                  const explicit = c.get('name')?.ifString()?.getValue()
                                  if (explicit) {
                                      return { name: explicit, isExplicit: true }
                                  }
                                  const label = c.get('label')?.ifString()?.getValue() ?? ''
                                  const slug = slugifyString(
                                      activityCallees.has(allCallees[i] ?? '') ? stripHtmlTags(label) : label
                                  )
                                  return { name: slug, isExplicit: false }
                              })
                              const uniqueName = deduplicateNames(entries)[index] ?? ''
                              const entry = entries[index]
                              if (entry?.isExplicit && entry.name !== uniqueName) {
                                  diagnostics.warn(
                                      allConfigs[index] ?? callExpression,
                                      `The name "${entry.name}" is already in use by another activity; it has been renamed to "${uniqueName}" to keep names unique.`
                                  )
                              }
                              return { uniqueName }
                          },
                          validateChildren: (children, variables) => {
                              validateOrderUniqueness(children, diagnostics)
                              validateManualActivityTargeting(children, variables, diagnostics)
                              const redundantEdges = detectRedundantEdges(children, variables)
                              for (const {
                                  nodeId,
                                  redundantDepId,
                                  throughId,
                                  shape,
                                  nodeTypeLabel,
                              } of redundantEdges) {
                                  diagnostics.warn(
                                      shape,
                                      `${nodeTypeLabel} "${nodeId}" has a redundant start rule dependency on "${redundantDepId}" because it is already reachable through "${throughId}".`
                                  )
                              }
                          },
                          transform,
                          diagnostics,
                          errorMessage: 'PlaybookDefinition lanes function must return an object literal',
                          errorSource: callExpression,
                      })
                    : []

                // variantOverrides[].startRule's Run.After() dependency args
                // (starts_after_activities/starts_after_lanes) can't be resolved while an
                // activity is still being created (ActivityPlugin's toRecord): an override may
                // reference ANY activity/lane in the whole playbook regardless of
                // declaration/processing order — including one not yet processed at that point
                // — so ActivityPlugin only writes start_rule_name/order and leaves these two
                // fields for here. Now that every lane/activity has a real GUID in
                // globalNowIdKeyToGuid, re-resolve each override's Run.After() args (including
                // wfa.playbook.activityRef(Now.ID[...]) forward references, which
                // resolveReferenceToNowIdKey doesn't understand on its own) and update the
                // already-created override record — OVERRIDE_TABLE coalesces on
                // (override_parent, variant), so this updates rather than duplicates it (DEF0906759).
                //
                // `variantOverrides[].variant` is written as `<activitiesParamName>.variants.<key>`,
                // where `<activitiesParamName>` is each LANE's own nested `activities: (params) =>
                // ...` arrow's parameter name — not the outer `lanesArrowFn`'s (usually param-less)
                // name already in `playbookBodyParamsNames`. LanePlugin normally adds its own lane's
                // activities-param name to its own local copy of that list per-lane; this pass runs
                // outside any single lane's toRecord, so it collects every lane's activities-param
                // name upfront here instead.
                const overridePlaybookBodyParamsNames = [...playbookBodyParamsNames]
                if (lanesArrowFn) {
                    const { variables: topLevelLaneVars, returnObj: laneReturnObj } =
                        parseArrowBodyEntries(lanesArrowFn)
                    if (laneReturnObj?.isObject()) {
                        for (const [, laneValue] of laneReturnObj.asObject().entries()) {
                            const resolvedLane = laneValue.isIdentifier()
                                ? (topLevelLaneVars.get(laneValue.asIdentifier().getName()) ?? laneValue)
                                : laneValue
                            if (!resolvedLane.is(CallExpressionShape)) {
                                continue
                            }
                            const laneArg0 = resolvedLane.as(CallExpressionShape).getArgument(0)?.ifObject()
                            const activitiesShape = laneArg0?.get('activities')
                            const paramName = activitiesShape?.is(ArrowFunctionShape)
                                ? activitiesShape.as(ArrowFunctionShape).getParameters()[0]?.getName()
                                : undefined
                            if (paramName && !overridePlaybookBodyParamsNames.includes(paramName)) {
                                overridePlaybookBodyParamsNames.push(paramName)
                            }
                        }
                    }
                }

                const deferredOverrideUpdateRecords: SdkRecord[] = []
                for (const node of playbookGraph?.nodes.values() ?? []) {
                    if (node.kind !== 'activity') {
                        continue
                    }
                    const variantOverridesShape = node.config.get('variantOverrides')?.ifArray()
                    if (!variantOverridesShape) {
                        continue
                    }
                    const ownGuid = globalNowIdKeyToGuid.get(node.nowIdKey)
                    if (!ownGuid) {
                        continue
                    }
                    for (const overrideEntry of variantOverridesShape.getElements()) {
                        const overrideObj = overrideEntry.ifObject()
                        const overrideStartRuleShape = overrideObj?.get('startRule')
                        if (
                            !overrideObj ||
                            !overrideStartRuleShape?.is(CallExpressionShape) ||
                            !isRunAfterCallee(overrideStartRuleShape.as(CallExpressionShape).getCallee())
                        ) {
                            continue
                        }
                        const overrideVariantGuid = resolveVariantReferenceToGuid(
                            overrideObj.get('variant', false),
                            variantKeyToGuid,
                            overridePlaybookBodyParamsNames
                        )
                        if (!overrideVariantGuid) {
                            continue
                        }
                        // Non-resolving fetch (`false`) preserves a cross-lane
                        // `laneVar.activityVar` arg as a PropertyAccessShape instead of
                        // auto-resolving it into an UnresolvedShape.
                        const runAfterArgs = overrideStartRuleShape.as(CallExpressionShape).getArguments(false)
                        const activityGuids: string[] = []
                        const laneGuids: string[] = []
                        for (const arg of runAfterArgs) {
                            if (
                                arg.is(CallExpressionShape) &&
                                arg.as(CallExpressionShape).getCallee() === ACTIVITY_REF_CALLEE
                            ) {
                                const idArg = arg.as(CallExpressionShape).getArgument(0, false).if(NowIdShape)
                                const targetGuid = idArg
                                    ? globalNowIdKeyToGuid.get(String(idArg.getValue()))
                                    : undefined
                                if (targetGuid) {
                                    activityGuids.push(targetGuid)
                                }
                                continue
                            }
                            // Branch references (e.g. decision.branches.critical) aren't
                            // supported on variant overrides yet — dropped, same as before.
                            if (arg.is(PropertyAccessShape) && arg.as(PropertyAccessShape).getElements().length !== 2) {
                                continue
                            }
                            const targetKey = playbookGraph
                                ? resolveReferenceToNowIdKey(arg, playbookGraph, node)
                                : undefined
                            const targetNode = targetKey ? playbookGraph?.nodes.get(targetKey) : undefined
                            const targetGuid = targetKey ? globalNowIdKeyToGuid.get(targetKey) : undefined
                            if (!targetNode || !targetGuid) {
                                continue
                            }
                            if (targetNode.kind === 'lane') {
                                laneGuids.push(targetGuid)
                            } else {
                                activityGuids.push(targetGuid)
                            }
                        }
                        if (activityGuids.length === 0 && laneGuids.length === 0) {
                            continue
                        }
                        // factory.createRecord replaces (not merges) a coalesced record's
                        // properties on a second call for the same identity, so this call must
                        // restate every field ActivityPlugin's original create wrote for this
                        // override — not just the two fields being added — or they're wiped out.
                        // buildOverrideBaseProperties() is the SAME helper ActivityPlugin's own
                        // create call uses, so the two calls can't drift out of sync.
                        deferredOverrideUpdateRecords.push(
                            await factory.createRecord({
                                source: overrideEntry,
                                table: OVERRIDE_TABLE,
                                properties: {
                                    override_parent: ownGuid,
                                    variant: overrideVariantGuid,
                                    ...buildOverrideBaseProperties(overrideObj),
                                    ...(activityGuids.length > 0
                                        ? { starts_after_activities: activityGuids.join(',') }
                                        : {}),
                                    ...(laneGuids.length > 0 ? { starts_after_lanes: laneGuids.join(',') } : {}),
                                },
                            })
                        )
                    }
                }

                // Resolve evaluateVariantChildrenAfter to a real activity GUID now that every
                // lane/activity in the body has been created and globalNowIdKeyToGuid is fully
                // populated. Errors if the key doesn't correspond to any activity actually
                // declared in this playbook's lanes. Target-validity checks (must be an
                // activity, must not be optional, must not be decision-branch-gated) live in
                // VariantDiagnosticsPlugin instead, since they only need the static
                // playbookGraph and not this GUID-resolution pass.
                let resolvedEvaluateVariantChildrenAfterGuid: string | undefined
                if (evaluateVariantChildrenAfterKey) {
                    resolvedEvaluateVariantChildrenAfterGuid = globalNowIdKeyToGuid.get(evaluateVariantChildrenAfterKey)
                    if (!resolvedEvaluateVariantChildrenAfterGuid) {
                        diagnostics.error(
                            config.get('evaluateVariantChildrenAfter'),
                            `evaluateVariantChildrenAfter references '${evaluateVariantChildrenAfterKey}' which is not an activity in this playbook.`
                        )
                    }
                }

                if (resolvedEvaluateVariantChildrenAfterGuid) {
                    playbookRecord = playbookRecord.merge({
                        evaluate_variant_children_after: resolvedEvaluateVariantChildrenAfterGuid,
                    })
                }

                const allChildRecords = [
                    ...allRecords,
                    ...variantRecords,
                    ...triggerRecords,
                    ...relatedRecords,
                    ...deferredOverrideUpdateRecords,
                    ...(parentRecordInputRecord ? [parentRecordInputRecord] : []),
                ]

                return {
                    success: true,
                    value: playbookRecord.with(...allChildRecords),
                }
            },
        },
    ],
})
