import type { Record as SdkRecord } from '@servicenow/sdk-build-core'
import { DECISION_DEF_SYS_ID } from '../constants/activity-ootb-maps'

/**
 * Ordering and variable naming for the XML -> Fluent direction — the single source of truth for
 * both the incremental per-level collection builders (child-collection-toshape.ts,
 * lane-config-transform.ts, playbook-definition-plugin.ts) and the whole-playbook pre-pass
 * (guid-to-var-path-map.ts). Both must assign the same names in the same order; sharing these
 * helpers is what makes that structural rather than a convention to police.
 */

/** Comma-separated guid field (e.g. `starts_after_lanes`) as a guid list. */
export function guidList(record: SdkRecord, field: string): string[] {
    return (record.get(field)?.ifString()?.getValue() ?? '')
        .split(',')
        .map((guid) => guid.trim())
        .filter(Boolean)
}

export const startsAfterLanes = (record: SdkRecord): string[] => guidList(record, 'starts_after_lanes')
export const startsAfterActivities = (record: SdkRecord): string[] => guidList(record, 'starts_after_activities')

/**
 * Topologically sort records so that dependencies come before dependents.
 * Falls back to original order for records with no dependency relationships.
 */
export function topologicalSort(
    records: SdkRecord[],
    getDependencyGuids: (record: SdkRecord) => string[]
): SdkRecord[] {
    const guidToRecord = new Map<string, SdkRecord>()
    for (const record of records) {
        guidToRecord.set(record.getId().getValue(), record)
    }

    const sorted: SdkRecord[] = []
    const visited = new Set<string>()
    const visiting = new Set<string>()

    function visit(record: SdkRecord) {
        const guid = record.getId().getValue()
        if (visited.has(guid)) {
            return
        }
        if (visiting.has(guid)) {
            return // cycle — break it by skipping
        }
        visiting.add(guid)

        for (const depGuid of getDependencyGuids(record)) {
            const depRecord = guidToRecord.get(depGuid)
            if (depRecord) {
                visit(depRecord)
            }
        }

        visiting.delete(guid)
        visited.add(guid)
        sorted.push(record)
    }

    for (const record of records) {
        visit(record)
    }

    return sorted
}

/**
 * One collection level: records in emission order, each named `${prefix}_${index}`.
 * Without `getDependencyGuids` the input order is kept as-is.
 */
export function orderAndName(
    records: SdkRecord[],
    prefix: string,
    getDependencyGuids?: (record: SdkRecord) => string[]
): { ordered: SdkRecord[]; names: Map<string, string> } {
    const ordered = getDependencyGuids ? topologicalSort(records, getDependencyGuids) : records
    const names = new Map<string, string>()
    for (const [index, record] of ordered.entries()) {
        names.set(record.getId().getValue(), `${prefix}_${index}`)
    }
    return { ordered, names }
}

/** Filters `activities` (e.g. `allActivities`) down to the ones belonging to `laneGuid`. */
export function activitiesInLane(activities: SdkRecord[], laneGuid: string): SdkRecord[] {
    return activities.filter((rec) => (rec.get('lane')?.ifString()?.getValue() ?? '') === laneGuid)
}

/** A lane's own activities (from `activities`, e.g. `allActivities`), in emission order, named `activity_i`. */
export function orderAndNameLaneActivities(
    activities: SdkRecord[],
    laneGuid: string
): { ordered: SdkRecord[]; names: Map<string, string> } {
    return orderAndName(activitiesInLane(activities, laneGuid), 'activity', startsAfterActivities)
}

/** Top-level lanes, in emission order, named `lane_i`. Used when no stage-level activities exist. */
export function orderAndNameLanes(laneRecords: SdkRecord[]): { ordered: SdkRecord[]; names: Map<string, string> } {
    return orderAndName(laneRecords, 'lane', startsAfterLanes)
}

export interface InterleavedEntry {
    record: SdkRecord
    type: 'lane' | 'decision' | 'activity'
    varName: string
}

/**
 * Lanes interleaved with lane-less stage-level entries: sorted by `order` (NOT topologically),
 * named from independent counters — `lane_i` for lanes, `decision_i` for real Decision activities,
 * `activity_i` for everything else lane-less (e.g. global optional activities). Lanes win ties,
 * since they are collected first and the sort is stable.
 */
export function orderAndNameInterleaved(
    laneRecords: SdkRecord[],
    lanelessActivityRecords: SdkRecord[]
): { ordered: InterleavedEntry[]; names: Map<string, string> } {
    const tagged: Array<{ record: SdkRecord; type: 'lane' | 'decision' | 'activity'; order: number }> = []
    for (const record of laneRecords) {
        tagged.push({ record, type: 'lane', order: readOrder(record) })
    }
    for (const record of lanelessActivityRecords) {
        const activityDefSysId = record.get('activity_definition')?.ifString()?.getValue() ?? ''
        const type = activityDefSysId === DECISION_DEF_SYS_ID ? 'decision' : 'activity'
        tagged.push({ record, type, order: readOrder(record) })
    }
    tagged.sort((a, b) => a.order - b.order)

    const names = new Map<string, string>()
    let laneCounter = 0
    let decisionCounter = 0
    let activityCounter = 0
    const ordered = tagged.map(({ record, type }) => {
        const varName =
            type === 'lane'
                ? `lane_${laneCounter++}`
                : type === 'decision'
                  ? `decision_${decisionCounter++}`
                  : `activity_${activityCounter++}`
        names.set(record.getId().getValue(), varName)
        return { record, type, varName }
    })
    return { ordered, names }
}

function readOrder(record: SdkRecord): number {
    const order = record.get('order')?.toString()?.getValue()
    return order !== undefined ? Number(order) : 0
}
