import type { Diagnostics } from '@servicenow/sdk-build-core'
import { GO_BACK_ACTIVITY_DEF_KEY } from '../constants/activity-ootb-maps'
import {
    getBranchMembers,
    getEnclosingBranch,
    getValidPrecedingKeys,
    hasDependents,
    hasParallelForwardConflict,
    resolveReferenceToNowIdKey,
    type PlaybookGraphNode,
    type PlaybookGraph,
} from './playbook-graph'
import { computeAncestorIds } from './graph-utils'

/**
 * Messages copied verbatim from the platform's validation-constants.js so authors see the same
 * wording. `invalidStageTarget` is the exception: the platform has no equivalent (it reports a
 * missing stage as "The target activity was removed"), so it mirrors `invalidTarget`'s phrasing.
 */
export const GO_BACK_MESSAGES = {
    notInBranch: 'Place Go Back inside a decision branch',
    noTargetSelected: 'Select a Go Back target',
    invalidTarget: 'Select an earlier activity in this playbook',
    invalidStageTarget: 'Select an earlier stage in this playbook',
    targetBeyondEvaluationPoint: 'Select a target after the variant evaluation point',
    decisionNotMatchFirst: 'Set the decision activity\'s mode to "match_first"',
    multipleInBranch: 'Only one Go Back is allowed per decision branch',
    parallelForwardConflict: 'Go Back cannot be used in a branch with parallel paths',
    noForwardPath: 'Add a forward path to at least one branch in this decision',
    notTerminalInBranch: 'Move Go Back to the end of the decision branch',
    targetIsGoBack: "Select a different activity. Go Back can't target another Go Back.",
    targetNotRunAlways: 'Set the target activity\'s restart rule to "RUN_ALWAYS" so it runs on Go Back',
    playbookNotRestartable:
        'Set the restartable field in playbook config to "RESTARTABLE_TRUE" so the playbook can be restarted',
} as const

/** True when a graph node is a Go Back activity. */
function isGoBack(node: PlaybookGraphNode | undefined): boolean {
    return node?.activityDefCode === GO_BACK_ACTIVITY_DEF_KEY
}

/**
 * Runs Go Back validation rules over every Go Back activity found in `graph`. Mirrors
 * go-back-validator-utils.js on sn-process-automation-designer. `evaluateVariantChildrenAfterKey`
 * is the resolved `evaluateVariantChildrenAfter` Now.ID key, if the playbook sets one — passed
 * through to `validateGoBackTarget` for its "beyond evaluation point" check.
 */
export function validateGoBackActivities(
    graph: PlaybookGraph,
    playbookRestartable: string | undefined,
    diagnostics: Diagnostics,
    evaluateVariantChildrenAfterKey?: string
): void {
    // Every Go Back in a decision whose branches all dead-end shares the same violation — one
    // error per decision, not one per Go Back, so this is closed over across the whole loop.
    const decisionsWithNoForwardPathError = new Set<string>()
    for (const node of graph.nodes.values()) {
        if (node.kind === 'activity' && isGoBack(node)) {
            validateGoBackNode(
                node,
                graph,
                playbookRestartable,
                diagnostics,
                decisionsWithNoForwardPathError,
                evaluateVariantChildrenAfterKey
            )
        }
    }
}

function validateGoBackNode(
    node: PlaybookGraphNode,
    graph: PlaybookGraph,
    playbookRestartable: string | undefined,
    diagnostics: Diagnostics,
    decisionsWithNoForwardPathError: Set<string>,
    evaluateVariantChildrenAfterKey?: string
): void {
    const enclosing = getEnclosingBranch(node.nowIdKey, graph)

    // Must be inside a decision branch. `else` branches are allowed
    if (!enclosing) {
        diagnostics.error(node.config, GO_BACK_MESSAGES.notInBranch)
        return
    }
    const decision = graph.nodes.get(enclosing.decisionKey)
    const branchMembers = getBranchMembers(enclosing.decisionKey, graph)

    // Enclosing decision must be match_first.
    const decisionType = decision?.inputs?.get('type')?.ifString()?.getValue()
    const isMatchFirst = !decisionType || decisionType === 'match_first'
    if (!isMatchFirst) {
        diagnostics.error(node.config, GO_BACK_MESSAGES.decisionNotMatchFirst)
    }

    // At most one Go Back per direct branch.
    const siblings = (branchMembers.get(enclosing.branchId) ?? []).filter((key) => key !== node.nowIdKey)
    if (siblings.some((key) => isGoBack(graph.nodes.get(key)))) {
        diagnostics.error(node.config, GO_BACK_MESSAGES.multipleInBranch)
    }

    // No parallel/match_all ancestor within the enclosing branch.
    if (isMatchFirst && hasParallelForwardConflict(node.nowIdKey, graph)) {
        diagnostics.error(node.config, GO_BACK_MESSAGES.parallelForwardConflict)
    }

    // At least one branch of the enclosing decision must not dead-end in a Go Back.
    if (decision?.branches && decision.branches.length > 0) {
        const allBranchesHaveGoBack = decision.branches.every((b) =>
            (branchMembers.get(b.id) ?? []).some((key) => isGoBack(graph.nodes.get(key)))
        )
        if (allBranchesHaveGoBack && !decisionsWithNoForwardPathError.has(enclosing.decisionKey)) {
            decisionsWithNoForwardPathError.add(enclosing.decisionKey)
            diagnostics.error(node.config, GO_BACK_MESSAGES.noForwardPath)
        }
    }

    // Must be the last activity in its branch — no successors.
    if (hasDependents(node.nowIdKey, graph)) {
        diagnostics.error(node.config, GO_BACK_MESSAGES.notTerminalInBranch)
    }

    validateGoBackTarget(node, enclosing, graph, playbookRestartable, diagnostics, evaluateVariantChildrenAfterKey)
}

function validateGoBackTarget(
    node: PlaybookGraphNode,
    enclosing: { decisionKey: string; branchId: string },
    graph: PlaybookGraph,
    playbookRestartable: string | undefined,
    diagnostics: Diagnostics,
    evaluateVariantChildrenAfterKey?: string
): void {
    const targetType = node.inputs?.get('target_type')?.ifString()?.getValue()

    if (targetType === 'start_of_playbook') {
        // The playbook itself should be restartable.
        if (playbookRestartable !== 'RESTARTABLE_TRUE') {
            diagnostics.warn(node.config, GO_BACK_MESSAGES.playbookNotRestartable)
        }
        return
    }

    if (targetType !== 'go_back_to_target_activity' && targetType !== 'go_back_to_target_stage') {
        diagnostics.error(node.config, GO_BACK_MESSAGES.noTargetSelected)
        return
    }
    const isStage = targetType === 'go_back_to_target_stage'
    // Non-resolving fetch (`, false`) — required so a cross-lane `laneVar.activityVar` dot-walk
    // stays a PropertyAccessShape for resolveReferenceToNowIdKey to inspect, instead of
    // auto-resolving into an UnresolvedShape. See resolveReferenceToNowIdKey's caller contract.
    // `target_type`'s value is itself the sibling input field name to read.
    const targetShape = node.inputs?.get(targetType, false)

    // No target selected.
    if (!targetShape || targetShape.isUndefined()) {
        diagnostics.error(node.config, GO_BACK_MESSAGES.noTargetSelected)
        return
    }

    // Target doesn't resolve, or resolves to something not a valid preceding node.
    // Pass `node` so a bare identifier resolves against Go Back's own lane first (same-lane sibling).
    const targetKey = resolveReferenceToNowIdKey(targetShape, graph, node)
    const targetNode = targetKey ? graph.nodes.get(targetKey) : undefined
    const invalidMessage = isStage ? GO_BACK_MESSAGES.invalidStageTarget : GO_BACK_MESSAGES.invalidTarget
    if (!targetNode) {
        diagnostics.error(targetShape, invalidMessage)
        return
    }
    // Intentional divergence from the platform for stage targets: go-back-validator-utils.js's
    // isGoBackTargetValid only checks stage existence (`!structureData.lanes?.[stageTargetId]`),
    // with no ancestry check. Here we apply the same declaration-order ancestry check used for
    // activity targets to stage targets too — a deliberate strengthening, not an oversight.
    const validKeys = getValidPrecedingKeys(enclosing.decisionKey, isStage ? 'lane' : 'activity', graph)
    const isValidByDeclarationOrder = validKeys.has(targetNode.nowIdKey)

    // Mirrors go-back-validator-utils.js's isGoBackTargetBeyondEvaluationPoint: once the
    // enclosing decision itself runs after the playbook's variant evaluation point, only targets
    // that also run after it are in scope — a target that's a structural ancestor but sits before
    // the evaluation point gets the more specific message instead of the generic `invalidMessage`.
    let isTargetBeforeEvaluationPoint = false
    if (
        evaluateVariantChildrenAfterKey !== undefined &&
        computeAncestorIds(enclosing.decisionKey, graph).has(evaluateVariantChildrenAfterKey)
    ) {
        isTargetBeforeEvaluationPoint = !computeAncestorIds(targetNode.nowIdKey, graph).has(
            evaluateVariantChildrenAfterKey
        )
    }

    if (!isValidByDeclarationOrder || isTargetBeforeEvaluationPoint) {
        diagnostics.error(
            targetShape,
            isTargetBeforeEvaluationPoint ? GO_BACK_MESSAGES.targetBeyondEvaluationPoint : invalidMessage
        )
    }

    // Target activity must not itself be a Go Back (activity targets only).
    if (!isStage && isGoBack(targetNode)) {
        diagnostics.error(targetShape, GO_BACK_MESSAGES.targetIsGoBack)
    }

    // The target's own restartRule should be RUN_ALWAYS.
    const targetRestartRule = targetNode.config.get('restartRule')?.ifString()?.getValue()
    if (targetRestartRule !== 'RUN_ALWAYS') {
        diagnostics.warn(targetShape, GO_BACK_MESSAGES.targetNotRunAlways)
    }
}
