import { PlaybookDiagnosticsPlugin } from './plugins/playbook-diagnostics-plugin'
import { PlaybookDataPillDiagnosticsPlugin } from './plugins/playbook-datapill-diagnostics-plugin'
import { LaneDiagnosticsPlugin } from './plugins/lane-diagnostics-plugin'
import { ActivityDiagnosticsPlugin } from './plugins/activity-diagnostics-plugin'
import { VariantDiagnosticsPlugin } from './plugins/variant-diagnostics-plugin'
import { PlaybookDefinitionPlugin } from './plugins/playbook-definition-plugin'
import { PlaybookTriggerInstancePlugin } from './plugins/playbook-trigger-instance-plugin'
import { PlaybookTriggerInstanceDiagnosticsPlugin } from './plugins/playbook-trigger-instance-diagnostics-plugin'
import { LanePlugin } from './plugins/lane-plugin'
import { ActivityPlugin } from './plugins/activity-plugin'
import { VariantPlugin } from './plugins/variant-plugin'
import { PlaybookActivityRefPlugin } from './plugins/playbook-activity-ref-plugin'
import { PlaybookAutomationPlanPlugin } from './plugins/playbook-automation-plan-plugin'

// Note: the SDK's plugin injection (FLUENT_INJECT_PLUGINS) uses `prepend` for each
// element, which reverses array order. The plugin that should run FIRST during
// recordsToShapes must therefore be LAST in this array.
export const playbookPlugins = [
    // Parses dataPill(activityRef(...)) nodes into ActivityRefPillShape during shape building;
    // the generic CallExpression parser would otherwise reject the property-access-on-call.
    PlaybookActivityRefPlugin,
    // Same rationale as above, for dataPill(automationPlan(...)) nodes.
    PlaybookAutomationPlanPlugin,
    PlaybookDataPillDiagnosticsPlugin,
    LaneDiagnosticsPlugin,
    ActivityDiagnosticsPlugin,
    VariantDiagnosticsPlugin,
    PlaybookTriggerInstanceDiagnosticsPlugin,
    PlaybookTriggerInstancePlugin,
    LanePlugin,
    ActivityPlugin,
    VariantPlugin,
    PlaybookDefinitionPlugin,
    PlaybookDiagnosticsPlugin,
]
