/**
 * Extract the sys_id from a variable entry shape.
 * Entries are Column calls like `StringColumn({ sysId: '...', ... })` (CallExpressionShape)
 * or plain objects with a `sysId` property (ObjectShape).
 */
function extractVariableSysId(shape: Shape): string | undefined {
    const obj = shape.if(CallExpressionShape)?.getArgument(0)?.ifObject() ?? shape.ifObject()
    return obj?.get('sysId', false)?.ifString()?.getValue()
}

/**
 * Extract the column-level `defaultValue` from a variable entry shape, if present.
 * Entries are Column calls like `StringColumn({ sysId: '...', defaultValue: '4' })`
 * (CallExpressionShape) or plain objects. Returns undefined when no default is declared.
 */

// biome-ignore lint/suspicious/noExplicitAny: Default values may be any type matching the backing column type
function extractColumnDefaultValue(shape: Shape): any {
    const obj = shape.if(CallExpressionShape)?.getArgument(0)?.ifObject() ?? shape.ifObject()
    const value = obj?.get('defaultValue', false)
    return value?.getValue()
}

/**
 * Resolved activity definition config with pre-extracted input and experience property maps.
 */
interface ResolvedActivityDef {
    activityDefSysId: Now.Internal.ExplicitKey | string | number
    backingInputs: ObjectShape | undefined
    backingExperienceProperties: ObjectShape | undefined
    /** sys_id of the backing flow or action (for sys_element_mapping table name) */
    backingSysId: string | undefined
    /** Whether the backing automation is a flow or action (determines sys_element_mapping table prefix) */
    backingType: 'flow' | 'action' | undefined
    /** Display name of the backing flow/action's own `name` field (used for `{{vl.<label>...}}` pills). */
    backingLabel: string | undefined
    /** sys_id of the activity type (for sys_element_mapping table name) */
    activityTypeSysId: string | undefined
    /** Default values for inputs keyed by fluent name. Applied when Activity() does not provide a value. */
    defaultInputs: Record<string, any>
    /** Default values for experience properties keyed by fluent name. Applied when Activity() does not provide a value. */
    defaultExperienceProperties: Record<string, any>
    /** Default AI agent objective, applied when Activity() does not provide its own aiAgentObjective. */
    defaultAiAgentObjective: string | undefined
    /** Default AI agent additional detail, applied when Activity() does not provide its own aiAgentObjAdditionalDetail. */
    defaultAiAgentObjAdditionalDetail: string | undefined
    /**
     * Default AI agent execution mode, used to resolve the effective mode when Activity() does
     * not provide its own aiAgentExecutionMode (e.g. so aiAgentObjAdditionalDetail's Autonomous-mode
     * gate reflects the mode the platform will actually run under, not just an omitted instance value).
     */
    defaultAiAgentExecutionMode: string | undefined
    /** Default AI agent run-as, applied when Activity() does not provide its own aiAgentRunAs. */
    defaultAiAgentRunAs: string | undefined
    /** Default AI agent conversational agents, applied when Activity() does not provide its own conversationalAgents. */
    defaultConversationalAgents: ReturnType<typeof toReference>[] | undefined
    /** Default AI agent roles, applied when Activity() does not provide its own aiAgentRunWithRoles. */
    defaultAiAgentRunWithRoles: ReturnType<typeof toReference>[] | undefined
    /** Default AI agent supported actions, applied when Activity() does not provide its own aiAgentSupportedActions. */
    defaultAiAgentSupportedActions: string[] | undefined
    /**
     * Platform column names (keys of the definition's own aiAgentFieldDisplayPreferences), or
     * undefined if the definition declares no preferences at all (every AI field is then allowed).
     */
    aiAgentFieldDisplayPreferenceKeys: Set<string> | undefined
}

/**
 * Resolve the activity definition to extract its sys_id, input variable map, and typeVal map.
 *
 * Resolves through the shape system by following the IdentifierShape for the definition,
 * then traverses the flow/action and activityType references to extract their configs.
 * Works for both OOTB definitions (which reference .now.ts backing files) and custom
 * user-defined definitions.
 */
async function resolveActivityDef(
    activityDefShape: Shape,
    factory: Factory,
    diagnostics: Diagnostics
): Promise<ResolvedActivityDef | undefined> {
    const activityDefConfig = getFactoryCallConfig(activityDefShape)
    if (!activityDefConfig) {
        return undefined
    }

    const activityDefSysId = activityDefConfig.get('$id', false)?.ifString()?.getValue()
    if (!activityDefSysId) {
        return undefined
    }

    const flowShape = activityDefConfig.get('flow')
    const actionShape = activityDefConfig.get('action')
    const backingShape = flowShape?.ifDefined() ?? actionShape
    const backingType: 'flow' | 'action' | undefined = flowShape?.ifDefined()
        ? 'flow'
        : actionShape?.ifDefined()
          ? 'action'
          : undefined
    const backingConfig = getFactoryCallConfig(backingShape)
    const activityTypeConfig = getFactoryCallConfig(activityDefConfig.get('activityType'))

    const backingLabel = backingConfig?.get('name', false)?.ifString()?.getValue()

    const defaultExperiencePropertiesShape = activityDefConfig.get('defaultExperienceProperties', false)?.ifObject()
    const defaultExperienceProperties: Record<string, any> = {}
    if (defaultExperiencePropertiesShape) {
        const definitionPillContext: PillContext = {
            format: 'standard',
            factory,
            diagnostics,
            currentActivityId: CURRENT_ACTIVITY_INSTANCE_PLACEHOLDER,
            playbookBodyParamsNames: [],
            automationPlanBackingLabel: backingLabel,
            automationPlanBackingType: backingType,
            allowedSources: {
                currentActivityLabelDesc: true,
                automationPlan: true,
            },
        }
        for (const [key, valueShape] of defaultExperiencePropertiesShape.entries()) {
            const resolved = containsDataPill(valueShape)
                ? await resolvePlaybookPill(valueShape, definitionPillContext)
                : valueShape
            defaultExperienceProperties[key] = resolved.getValue()
        }
    }

    return {
        activityDefSysId,
        backingInputs: backingConfig?.get('inputs', false)?.ifObject(),
        backingExperienceProperties: activityTypeConfig?.get('experienceProperties', false)?.ifObject(),
        backingSysId: backingConfig?.get('$id', false)?.ifString()?.getValue(),
        backingType,
        backingLabel,
        activityTypeSysId: activityTypeConfig?.get('$id', false)?.ifString()?.getValue(),
        defaultInputs: activityDefConfig.get('defaultInputs', false)?.ifObject()?.getValue() ?? {},
        defaultExperienceProperties,
        defaultAiAgentObjective: activityDefConfig.get('aiAgentObjective', false)?.ifString()?.getValue(),
        defaultAiAgentObjAdditionalDetail: activityDefConfig
            .get('aiAgentObjAdditionalDetail', false)
            ?.ifString()
            ?.getValue(),
        defaultAiAgentExecutionMode: activityDefConfig.get('aiAgentExecutionMode', false)?.ifString()?.getValue(),
        defaultAiAgentRunAs: activityDefConfig.get('aiAgentRunAs', false)?.ifString()?.getValue(),
        defaultConversationalAgents: activityDefConfig
            .get('conversationalAgents', false)
            ?.ifArray()
            ?.getElements()
            .map(toReference),
        defaultAiAgentRunWithRoles: activityDefConfig
            .get('aiAgentRunWithRoles', false)
            ?.ifArray()
            ?.getElements()
            .map(toReference),
        defaultAiAgentSupportedActions: activityDefConfig
            .get('aiAgentSupportedActions', false)
            ?.ifArray()
            ?.getElements()
            .map((el) => el.ifString()?.getValue() ?? ''),
        aiAgentFieldDisplayPreferenceKeys: (() => {
            const prefs = activityDefConfig.get('aiAgentFieldDisplayPreferences', false)?.ifObject()?.getValue()
            return prefs ? new Set(Object.keys(prefs)) : undefined
        })(),
    }
}

export const ActivityPlugin = Plugin.create({
    name: 'ActivityPlugin',
    noTelemetry: true,
    records: {
        [ACTIVITY_TABLE]: {
            relationships: {
                [SYS_VARIABLE_VALUE_TABLE]: {
                    via: 'document_key',
                    descendant: true,
                },
                [SYS_ELEMENT_MAPPING_TABLE]: {
                    via: 'id',
                    descendant: true,
                },
                [ACTIVITY_ACTION_OVERRIDE_TABLE]: {
                    via: 'activity',
                    descendant: true,
                },
            },
            // Standalone-record handler: the framework calls this with (record, context) only, so
            // none of activityRecordToShape's cross-record context is available here. An activity
            // reached as a playbook descendant goes through laneRecordToShape /
            // buildInterleavedBodyToShape instead, which do supply it. Without it, sibling
            // references and pills stay unresolved and Go Back's target fields are omitted.
            toShape(record, { database }) {
                if (isPlaybookUnsupported(record, database)) {
                    return { success: false }
                }
                return activityRecordToShape(record, database)
            },
            toFile: suppressDeletedChildToFile,
        },
        [SYS_VARIABLE_VALUE_TABLE]: {
            coalesce: ['document_key', 'variable'],
        },
        [SYS_ELEMENT_MAPPING_TABLE]: {
            coalesce: ['field', 'table', 'id'],
        },
        [ACTIVITY_ACTION_OVERRIDE_TABLE]: {
            coalesce: ['activity', 'action_assignment'],
        },
        [OVERRIDE_TABLE]: {
            coalesce: ['override_parent', 'variant'],
        },
    },
    shapes: [
        {
            shape: ActivityShape,
            fileTypes: ['fluent'],
            async toRecord(activityShape, { factory, transform, diagnostics }) {
                const config = activityShape.getConfig()

                // Name resolution: the parent collection injects `uniqueName` — the de-duped
                // authoritative name (it equals the explicit name when there's no collision, and a
                // suffixed variant when it had to be de-duped). Prefer it; fall back to the explicit
                // name or a slugified label only when this activity is processed outside a collection.
                const injectedName = config.get('uniqueName')?.ifString()?.getValue()
                let computedName = injectedName
                if (!computedName) {
                    const explicitName = config.get('name')?.ifString()?.getValue()
                    const labelVal = config.get('label')?.ifString()?.getValue()
                    // Strip HTML before slugifying so the fallback name matches the stripped
                    // label that ActivityPlugin actually persists (see the toRecord block below).
                    computedName = explicitName ?? (labelVal ? slugifyString(stripHtmlTags(labelVal)) : '')
                }

                // Resolve the activity definition to extract the def sys_id, input map, and typeVal map.
                const resolvedActivityDef = await resolveActivityDef(
                    activityShape.getActivityDefinition(),
                    factory,
                    diagnostics
                )
                if (!resolvedActivityDef) {
                    return { success: false }
                }
                const {
                    activityDefSysId,
                    backingInputs,
                    backingExperienceProperties,
                    backingSysId,
                    backingType,
                    activityTypeSysId,
                    defaultInputs,
                    defaultExperienceProperties,
                    defaultAiAgentObjective,
                    defaultAiAgentObjAdditionalDetail,
                    defaultAiAgentExecutionMode,
                    defaultAiAgentRunAs,
                    defaultConversationalAgents,
                    defaultAiAgentRunWithRoles,
                    defaultAiAgentSupportedActions,
                    aiAgentFieldDisplayPreferenceKeys,
                } = resolvedActivityDef
                const isDecision = String(activityDefSysId) === DECISION_DEF_SYS_ID
                const isGoBack = String(activityDefSysId) === GO_BACK_DEF_SYS_ID

                // Fields absent from the definition's own aiAgentFieldDisplayPreferences aren't
                // author-facing for this definition (mirrors ACTIVITY_DEF_AI_FIELD_DISPLAY_PREFS'
                // isAiFieldAllowed on the reverse/toShape direction) — undefined preferences means
                // the definition declared none, so every AI field is allowed.
                const isAiFieldAllowed = (column: string) =>
                    aiAgentFieldDisplayPreferenceKeys === undefined || aiAgentFieldDisplayPreferenceKeys.has(column)
                // Definition-level defaults (aiAgentObjective, aiAgentRunAs, etc.) should only ever
                // substitute for an omitted instance value when the AI agent is actually enabled on
                // this instance — otherwise a definition with its own defaults (all 4 AI-capable
                // built-ins have one) would silently populate ai_agent_* columns on every activity
                // built from it, even ones that never turn the agent on.
                const isAiAgentEnabled = config.get('enableAiAgent')?.ifBoolean()?.getValue() === true

                const isSetPlaybookOutputs = String(activityDefSysId) === SET_PLAYBOOK_OUTPUTS_DEF_SYS_ID

                // Set Playbook Outputs: the backing subflow's `playbook_outputs_var_table_name`
                // input is hidden from the DSL (not in inputDisplayPreferences). Auto-derive its
                // value from the host playbook's process-def sys_id so it flows through the standard
                // default-input path below as a literal. This is the dependent "table" whose columns
                // (the playbook's declared outputs) the template_value editor offers. The paired
                // validation (undeclared output keys, and rejecting a hand-supplied var-table-name)
                // lives in ActivityDiagnosticsPlugin.
                const effectiveDefaultInputs = { ...defaultInputs }
                if (isSetPlaybookOutputs) {
                    const hostProcessDefSysId = config.get('processDefinition')?.ifString()?.getValue() ?? ''
                    if (hostProcessDefSysId) {
                        effectiveDefaultInputs[PLAYBOOK_OUTPUTS_VAR_TABLE_NAME_INPUT] =
                            `var__m_${PLAYBOOK_OUTPUT_TABLE}_${hostProcessDefSysId}`
                    } else {
                        // Every activity is a child of a playbook lane, so `processDefinition` is always
                        // injected by the parent-collection pipeline (see trigger-array-processing.ts). If
                        // it's missing here, the auto-derived var-table-name is silently skipped and the
                        // activity would persist without it — breaking the template_value editor on the
                        // platform. That should never happen; surface it instead of failing silently.
                        diagnostics.error(
                            activityShape,
                            'Set Playbook Outputs activity could not resolve its host playbook, so ' +
                                `'${PLAYBOOK_OUTPUTS_VAR_TABLE_NAME_INPUT}' was not set.`
                        )
                    }
                }

                // Run activity diagnostics (dependent field validation for all
                // activities, plus Decision-specific checks for Decision activities).
                await transform.toRecord(activityShape, ActivityDiagnosticsPlugin)

                const playbookBodyParamsNames = activityShape.getPlaybookBodyParamsNames()
                const conditionPillContext: PillContext = {
                    format: 'condition',
                    factory,
                    diagnostics,
                    playbookBodyParamsNames,
                    allowedSources: {
                        paramsInputs: true,
                        paramsParentRecord: true,
                        previousActivityOutputs: true,
                    },
                }

                // Resolve conditionToRun pills before record creation (config.transform is synchronous)
                const conditionToRunShape = config.get('conditionToRun')
                const resolvedConditionToRun =
                    conditionToRunShape && !conditionToRunShape.isUndefined()
                        ? await resolvePlaybookPill(conditionToRunShape, conditionPillContext)
                        : undefined

                // aiAgentObjAdditionalDetail only applies in Autonomous mode; read the effective
                // mode up front so the persisted value can be gated below (ActivityDiagnosticsPlugin
                // warns the author when this is set outside that mode). Falls back to the
                // definition's own aiAgentExecutionMode default when the instance omits it, so an
                // activity that relies on e.g. RecordForm's own Autonomous-mode default doesn't
                // have its additional detail incorrectly discarded as if it were Collaborative.
                const aiAgentExecutionMode =
                    config.get('aiAgentExecutionMode')?.ifString()?.getValue() ?? defaultAiAgentExecutionMode

                // Resolve `variant` (variant-only activity scoping) up front so it can be used
                // both in the base record's properties below and validated by
                // ActivityDiagnosticsPlugin (undeclared-variant checks). Unresolvable/omitted
                // resolves to '' — a normal base (shared) activity.
                const variantKeyToGuid = activityShape.getVariantKeyToGuid() ?? new Map<string, string>()
                // Read raw (resolve: false): `variant` is a bare `params.variants.<key>`
                // PropertyAccessShape, never wrapped in a call — the default `.get()` behavior
                // would otherwise try to resolve the trailing `<key>` element as an identifier
                // declaration (which it isn't) and collapse it to an UnresolvedShape.
                const variantShape = config.get('variant', false)
                const resolvedVariantGuid =
                    variantShape && !variantShape.isUndefined()
                        ? resolveVariantReferenceToGuid(variantShape, variantKeyToGuid, playbookBodyParamsNames)
                        : undefined

                const activityRecord = await factory.createRecord({
                    source: activityShape,
                    table: ACTIVITY_TABLE,
                    explicitId: config.get('$id'),
                    properties: config.transform(({ $ }) => ({
                        activity_definition: $.val(activityDefSysId),
                        // Mirrors platform BR "Strip HTML from label": HTML is not supported on
                        // sys_pd_activity.label and the BR silently strips it on insert/update.
                        // ActivityDiagnosticsPlugin emits a warning when this strip applies.
                        label: $.map((label) => {
                            const str = label.ifString()?.getValue()
                            return str !== undefined ? stripHtmlTags(str) : label
                        }),
                        name: $.val(computedName),
                        // Regular activities always set `order` explicitly (required by ActivityConfig).
                        // Optional activities omit it (ManualActivityConfig has no `order` field), so this
                        // default only ever applies to those — `.def()` is a no-op when `order` is present.
                        order: $.def(ACTIVITY_DEFAULTS.MANUAL_ORDER),
                        active: $.def(ACTIVITY_DEFAULTS.ACTIVE),
                        description: $,
                        start_rule_name: $.from('startRule').map((startRule) => resolveStartRuleToDatabase(startRule)),
                        starts_after_activities: $.from('startsAfterActivities'),
                        starts_after_branches: $.from('startsAfterBranches'),
                        starts_after_lanes: $.from('startsAfterLanes'),
                        condition_to_run: resolvedConditionToRun
                            ? $.val(resolvedConditionToRun)
                            : $.from('conditionToRun'),
                        restart_rule: $.from('restartRule').def(ACTIVITY_DEFAULTS.RESTART_RULE),
                        lane: $.def(''),
                        process_definition: $.from('processDefinition'),
                        // Scopes this activity to exist only within the given variant. Omitted/
                        // unresolvable references resolve to '' (a normal base/shared activity) —
                        // ActivityDiagnosticsPlugin is responsible for surfacing an error when the
                        // reference doesn't resolve to a declared variant.
                        variant: $.val(resolvedVariantGuid ?? ''),
                        // Preserve AI-agent fields on round-trip. aiAgentObjective, aiAgentObjAdditionalDetail,
                        // aiAgentRunAs, conversationalAgents, aiAgentRunWithRoles, and aiAgentSupportedActions
                        // each fall back to the activity definition's own default (if declared) when the
                        // activity instance doesn't provide its own value — but only when isAiAgentEnabled,
                        // so a definition's default doesn't leak onto activities that never turn the agent on.
                        // An allowed instance value always wins over the default, regardless of isAiAgentEnabled.
                        // Critically, isAiFieldAllowed only gates whether an *instance* value counts: even on
                        // a definition that excludes one of these fields from aiAgentFieldDisplayPreferences
                        // (so it isn't author-facing — setting it explicitly is a TypeScript error), the
                        // definition's own default for it still applies while the agent is enabled — a
                        // definition can bake in a fixed value without exposing the field for authors to
                        // override. enableAiAgent, aiAgentExecutionMode, aiAgentUser, and
                        // launchAgentWhenActivityStart have no per-definition default to fall back to, so they
                        // keep the simple isAiFieldAllowed(...) ? {...} : {} full-omission gate.
                        ...(isAiFieldAllowed('enable_ai_agent') ? { enable_ai_agent: $.from('enableAiAgent') } : {}),
                        ai_agent_objective:
                            isAiFieldAllowed('ai_agent_objective') &&
                            config.get('aiAgentObjective')?.isUndefined() === false
                                ? $.from('aiAgentObjective')
                                : isAiAgentEnabled
                                  ? $.val(defaultAiAgentObjective ?? '')
                                  : $.from('aiAgentObjective'),
                        ai_agent_obj_additional_detail:
                            aiAgentExecutionMode === 'on'
                                ? isAiFieldAllowed('ai_agent_obj_additional_detail') &&
                                  config.get('aiAgentObjAdditionalDetail')?.isUndefined() === false
                                    ? $.from('aiAgentObjAdditionalDetail')
                                    : isAiAgentEnabled
                                      ? $.val(defaultAiAgentObjAdditionalDetail ?? '')
                                      : $.from('aiAgentObjAdditionalDetail')
                                : $.val(''),
                        ...(isAiFieldAllowed('ai_agent_execution_mode')
                            ? { ai_agent_execution_mode: $.from('aiAgentExecutionMode') }
                            : {}),
                        ai_agent_run_with_roles:
                            isAiFieldAllowed('ai_agent_run_with_roles') &&
                            config.get('aiAgentRunWithRoles')?.isUndefined() === false
                                ? $.from('aiAgentRunWithRoles').map((v: Shape) => {
                                      const arr = v.ifArray()
                                      return arr ? arr.getElements().map(toReference) : v
                                  })
                                : isAiAgentEnabled
                                  ? $.val(defaultAiAgentRunWithRoles ?? [])
                                  : $.from('aiAgentRunWithRoles'),
                        ai_agent_supported_actions:
                            isAiFieldAllowed('ai_agent_supported_actions') &&
                            config.get('aiAgentSupportedActions')?.isUndefined() === false
                                ? $.from('aiAgentSupportedActions')
                                : isAiAgentEnabled
                                  ? $.val(defaultAiAgentSupportedActions ?? [])
                                  : $.from('aiAgentSupportedActions'),
                        ai_agent_run_as:
                            isAiFieldAllowed('ai_agent_run_as') && config.get('aiAgentRunAs')?.isUndefined() === false
                                ? $.from('aiAgentRunAs')
                                : isAiAgentEnabled
                                  ? $.val(defaultAiAgentRunAs ?? ACTIVITY_DEFAULTS.AI_AGENT_RUN_AS)
                                  : $.from('aiAgentRunAs'),
                        ...(isAiFieldAllowed('ai_agent_user') ? { ai_agent_user: $.from('aiAgentUser') } : {}),
                        conversational_agents:
                            isAiFieldAllowed('conversational_agents') &&
                            config.get('conversationalAgents')?.isUndefined() === false
                                ? $.from('conversationalAgents').map((v: Shape) => {
                                      const arr = v.ifArray()
                                      return arr ? arr.getElements().map(toReference) : v
                                  })
                                : isAiAgentEnabled
                                  ? $.val(defaultConversationalAgents ?? [])
                                  : $.from('conversationalAgents'),
                        ...(isAiFieldAllowed('launch_agent_when_activity_start')
                            ? { launch_agent_when_activity_start: $.from('launchAgentWhenActivityStart') }
                            : {}),
                    })),
                })

                const relatedRecords: SdkRecord[] = []
                const activitySysId = activityRecord.getId().getValue()

                // variantOverrides -> sys_pd_activity_override records. Each entry overrides this
                // activity's start_rule/order when the given variant is selected.
                // Diagnostics for unresolvable variant references, duplicate overrides for the
                // same variant, and no-op entries (neither startRule nor order set) are handled by
                // ActivityDiagnosticsPlugin, not here — this loop silently skips entries whose
                // variant reference doesn't resolve.
                const variantOverridesShape = config.get('variantOverrides')?.ifArray()
                if (variantOverridesShape) {
                    for (const overrideEntry of variantOverridesShape.getElements()) {
                        const overrideObj = overrideEntry.ifObject()
                        if (!overrideObj) {
                            continue
                        }
                        const overrideVariantGuid = resolveVariantReferenceToGuid(
                            overrideObj.get('variant', false),
                            variantKeyToGuid,
                            playbookBodyParamsNames
                        )
                        // Silently skip when the reference doesn't resolve (e.g. a typo'd key, or a key
                        // whose variant failed to build) — same opaque-unresolvable-reference contract as
                        // the base activity's own `variant` field above. ActivityDiagnosticsPlugin is
                        // responsible for surfacing this as a visible error via the declared-variant-keys
                        // check, so this loop doesn't need to (and can't cleanly) diagnose it itself.
                        if (!overrideVariantGuid) {
                            continue
                        }
                        // starts_after_activities/starts_after_lanes are resolved separately, in
                        // PlaybookDefinitionPlugin's variantOverrides pass — see
                        // buildOverrideBaseProperties's own doc comment for why.
                        const overrideProperties: Record<string, string | Shape> = {
                            override_parent: activitySysId,
                            variant: overrideVariantGuid,
                            ...buildOverrideBaseProperties(overrideObj),
                        }
                        relatedRecords.push(
                            await factory.createRecord({
                                source: overrideEntry,
                                table: OVERRIDE_TABLE,
                                properties: overrideProperties,
                            })
                        )
                    }
                }

                // Create timer attributes record if startWithDelay is present.
                // Activities support the same three duration types as lanes (explicit, relative, percentage)
                // and accept dataPill() references for the pill-capable fields.
                const startWithDelayShape = config.get('startWithDelay')
                if (startWithDelayShape && !startWithDelayShape.isUndefined()) {
                    const timerPillContext: PillContext = {
                        format: 'standard',
                        factory,
                        diagnostics,
                        currentActivityId: activityRecord.getId(),
                        playbookBodyParamsNames,
                        allowedSources: {
                            paramsInputs: true,
                            paramsState: true,
                            paramsParentRecord: true,
                            previousActivityOutputs: true,
                        },
                    }
                    const processDefinition = config.get('processDefinition')?.ifString()?.getValue() ?? ''
                    const timerRecord = await timerAttributesToRecord(
                        startWithDelayShape.asObject(),
                        activityRecord,
                        processDefinition,
                        'sys_pd_activity',
                        factory,
                        diagnostics,
                        timerPillContext
                    )
                    if (timerRecord) {
                        relatedRecords.push(timerRecord)
                    }
                }

                // Create one sys_pd_activity_action_override record per actionOverrides entry.
                // actionAssignment references a sys_declarative_action_assignment record — those
                // rows are app/experience-specific platform configuration, not authored via Fluent,
                // so there's no OOTB name to resolve. Authors may supply either the raw sys_id or a
                // Record<'sys_declarative_action_assignment'>, so resolve both to a sys_id string.
                const actionOverridesShape = config.get('actionOverrides')?.ifArray()
                if (actionOverridesShape) {
                    for (const overrideShape of actionOverridesShape.getElements()) {
                        const overrideObj = overrideShape.ifObject()
                        const actionAssignmentShape = overrideObj?.get('actionAssignment')
                        const actionAssignment = actionAssignmentShape ? toReference(actionAssignmentShape) : undefined
                        if (!actionAssignment) {
                            // An override with no usable actionAssignment sys_id can't map to a
                            // sys_declarative_action_assignment row, so it's dropped here.
                            // ActivityDiagnosticsPlugin surfaces the author-facing warning for this
                            // (an omitted/empty actionAssignment) rather than dropping it silently.
                            continue
                        }
                        relatedRecords.push(
                            await factory.createRecord({
                                source: overrideShape,
                                table: ACTIVITY_ACTION_OVERRIDE_TABLE,
                                properties: {
                                    activity: activitySysId,
                                    action_assignment: actionAssignment,
                                    label: overrideObj?.get('label')?.ifString()?.getValue() ?? '',
                                    display_order: overrideObj?.get('displayOrder')?.ifNumber()?.getValue() ?? 0,
                                },
                            })
                        )
                    }
                }

                const inputPillContext: PillContext = {
                    format: 'standard',
                    factory,
                    diagnostics,
                    currentActivityId: activityRecord.getId(),
                    playbookBodyParamsNames,
                    allowedSources: {
                        paramsInputs: true,
                        paramsState: true,
                        paramsParentRecord: true,
                        previousActivityOutputs: true,
                        currentActivityLabelDesc: true,
                    },
                }
                const experiencePropertyPillContext: PillContext = {
                    format: 'standard',
                    factory,
                    diagnostics,
                    currentActivityId: activityRecord.getId(),
                    playbookBodyParamsNames,
                    automationPlanBackingLabel: resolvedActivityDef?.backingLabel,
                    automationPlanBackingType: resolvedActivityDef?.backingType,
                    allowedSources: {
                        paramsInputs: true,
                        paramsState: true,
                        paramsParentRecord: true,
                        previousActivityOutputs: true,
                        currentActivityLabelDesc: true,
                        automationPlan: true,
                    },
                }

                // Generate sys_variable_value and sys_element_mapping records for inputs.
                // The platform stores pill mappings in sys_element_mapping and literal
                // values in sys_variable_value. We always create both records so that
                // switching between pill ↔ literal across builds never leaves stale data:
                //   pill:    sys_variable_value.value = ''   , sys_element_mapping.value = pill
                //   literal: sys_variable_value.value = value, sys_element_mapping.value = ''
                const inputs = activityShape.getInputs()
                if (backingInputs && inputs) {
                    for (const fluentName of inputs.keys()) {
                        // Decision branches are handled separately below
                        if (isDecision && fluentName === 'branches') {
                            continue
                        }
                        // Go Back's target-reference inputs are handled separately below
                        if (
                            isGoBack &&
                            (fluentName === 'go_back_to_target_stage' || fluentName === 'go_back_to_target_activity')
                        ) {
                            continue
                        }
                        const varEntryShape = backingInputs.get(fluentName, false)
                        if (!varEntryShape) {
                            continue
                        }
                        const sysId = extractVariableSysId(varEntryShape)
                        if (!sysId) {
                            continue
                        }
                        const rawInputShape = inputs.get(fluentName)!
                        const inputShape =
                            rawInputShape instanceof TemplateValueShape
                                ? normalizeTemplateValue(rawInputShape)
                                : rawInputShape
                        const isPill = containsDataPill(inputShape)
                        const resolvedValue = await resolvePlaybookPill(inputShape, inputPillContext)
                        relatedRecords.push(
                            await factory.createRecord({
                                source: inputShape,
                                table: SYS_VARIABLE_VALUE_TABLE,
                                properties: {
                                    document: ACTIVITY_TABLE,
                                    document_key: activitySysId,
                                    variable: sysId,
                                    value: isPill ? '' : resolvedValue,
                                },
                            })
                        )
                        if (backingSysId) {
                            const inputTablePrefix =
                                backingType === 'action' ? 'sys_hub_action_input' : 'sys_hub_flow_input'
                            relatedRecords.push(
                                await factory.createRecord({
                                    source: inputShape,
                                    table: SYS_ELEMENT_MAPPING_TABLE,
                                    properties: {
                                        field: fluentName,
                                        id: activitySysId,
                                        table: `var__m_${inputTablePrefix}_${backingSysId}`,
                                        value: isPill ? resolvedValue : '',
                                    },
                                })
                            )
                        }
                    }
                }

                // Apply default input values for inputs the user did not provide in Activity().
                // Same dual-record pattern: pills go in sys_element_mapping, literals in sys_variable_value.
                // An empty counterpart record is always created to avoid stale data across builds.
                if (backingInputs) {
                    const userProvidedInputs = inputs ? new Set(inputs.keys()) : new Set<string>()
                    for (const [fluentName, defaultValue] of Object.entries(effectiveDefaultInputs)) {
                        if (userProvidedInputs.has(fluentName)) {
                            continue
                        }
                        const varEntryShape = backingInputs.get(fluentName, false)
                        if (!varEntryShape) {
                            continue
                        }
                        const sysId = extractVariableSysId(varEntryShape)
                        if (!sysId) {
                            continue
                        }
                        const rawValue = String(defaultValue)
                        const isPill = [...rawValue.matchAll(STANDARD_PILL_REGEX)].length > 0
                        // Resolve {{act.act_instance. to the current activity's sys_id
                        const stringValue = isPill
                            ? rawValue.replace(/\{\{act\.act_instance\./g, `{{act.${activitySysId}.`)
                            : rawValue
                        relatedRecords.push(
                            await factory.createRecord({
                                source: activityShape,
                                table: SYS_VARIABLE_VALUE_TABLE,
                                properties: {
                                    document: ACTIVITY_TABLE,
                                    document_key: activitySysId,
                                    variable: sysId,
                                    value: isPill ? '' : stringValue,
                                },
                            })
                        )
                        if (backingSysId) {
                            const inputTablePrefix =
                                backingType === 'action' ? 'sys_hub_action_input' : 'sys_hub_flow_input'
                            relatedRecords.push(
                                await factory.createRecord({
                                    source: activityShape,
                                    table: SYS_ELEMENT_MAPPING_TABLE,
                                    properties: {
                                        field: fluentName,
                                        id: activitySysId,
                                        table: `var__m_${inputTablePrefix}_${backingSysId}`,
                                        value: isPill ? stringValue : '',
                                    },
                                })
                            )
                        }
                    }
                }

                // Handle Decision activity's branches input specially.
                // Branches need JSON serialization rather than direct value mapping.
                if (isDecision && backingInputs) {
                    const branchesShape = inputs?.get('branches')?.ifArray()
                    const branchesEntryShape = backingInputs.get('branches', false)
                    const branchesSysId = branchesEntryShape ? extractVariableSysId(branchesEntryShape) : undefined
                    if (branchesShape && branchesSysId) {
                        const branchesJson: Array<{
                            id: string
                            label: string
                            condition: string
                            order: number
                            activitiesCount: number
                            isIdealPath: boolean
                        }> = []
                        for (const [index, elem] of branchesShape.getElements().entries()) {
                            const branch = elem.ifObject()
                            const rawId = branch?.get('id')?.ifString()?.getValue() ?? ''
                            const rawLabel = branch?.get('label')?.ifString()?.getValue() ?? ''
                            const label = rawId === 'else' ? 'Else' : rawLabel
                            const id =
                                rawId === 'else'
                                    ? 'ELSE'
                                    : generateId(activitySysId, 'branch', slugifyString(label) || rawId)
                            const conditionShape = branch?.get('condition')
                            let condition = ''
                            if (conditionShape) {
                                const resolved = await resolvePlaybookPill(conditionShape, conditionPillContext)
                                const rawCondition =
                                    resolved.ifString()?.getValue() ?? resolved.getValue()?.toString() ?? ''
                                // Replace `keywords` only in field position (start of segment),
                                // not when it appears as a value (e.g., field=keywords)
                                condition = encodeKeywordsToken(rawCondition)
                            }
                            // Always emit the flag as a real boolean, defaulting to false.
                            const isIdealPath = branch?.get('isIdealPath')?.ifBoolean()?.getValue() ?? false
                            branchesJson.push({
                                id,
                                label,
                                condition,
                                order: index + 1,
                                activitiesCount: 0,
                                isIdealPath,
                            })
                        }
                        relatedRecords.push(
                            await factory.createRecord({
                                source: branchesShape,
                                table: SYS_VARIABLE_VALUE_TABLE,
                                properties: {
                                    document: ACTIVITY_TABLE,
                                    document_key: activitySysId,
                                    variable: branchesSysId,
                                    value: JSON.stringify(branchesJson),
                                },
                            })
                        )
                    }

                    // Default type to 'match_first' when not explicitly provided
                    const hasType = inputs && [...inputs.keys()].includes('type')
                    if (!hasType) {
                        const typeEntryShape = backingInputs.get('type', false)
                        const typeSysId = typeEntryShape ? extractVariableSysId(typeEntryShape) : undefined
                        if (typeSysId) {
                            relatedRecords.push(
                                await factory.createRecord({
                                    source: activityShape,
                                    table: SYS_VARIABLE_VALUE_TABLE,
                                    properties: {
                                        document: ACTIVITY_TABLE,
                                        document_key: activitySysId,
                                        variable: typeSysId,
                                        value: 'match_first',
                                    },
                                })
                            )
                        }
                    }
                }

                // Handle Go Back's target-reference inputs specially: they hold a raw lane/activity
                // variable reference (not a data pill or literal), resolved to that record's real
                // sys_id via the whole-playbook graph built in PlaybookDefinitionPlugin.
                if (isGoBack && backingInputs) {
                    const playbookGraph = activityShape.getPlaybookGraph()
                    const nowIdKeyToGuidMap = activityShape.getNowIdKeyToGuid()
                    // This activity's own graph node — passed to resolveReferenceToNowIdKey so a
                    // bare-identifier target (a sibling activity in the SAME lane) resolves correctly.
                    const ownIdShape = activityShape.getConfig().get('$id')?.if(NowIdShape)
                    const ownNode =
                        playbookGraph && ownIdShape ? playbookGraph.nodes.get(String(ownIdShape.getValue())) : undefined
                    for (const fieldName of ['go_back_to_target_stage', 'go_back_to_target_activity'] as const) {
                        // Non-resolving fetch (`, false`) — required so a cross-lane
                        // `laneVar.activityVar` dot-walk stays a PropertyAccessShape instead of
                        // auto-resolving into an UnresolvedShape.
                        const targetShape = inputs?.get(fieldName, false)
                        if (!targetShape || targetShape.isUndefined()) {
                            continue
                        }
                        const varEntryShape = backingInputs.get(fieldName, false)
                        const sysId = varEntryShape ? extractVariableSysId(varEntryShape) : undefined
                        if (!sysId) {
                            continue
                        }
                        const targetKey = playbookGraph
                            ? resolveReferenceToNowIdKey(targetShape, playbookGraph, ownNode)
                            : undefined
                        const targetGuid = targetKey ? nowIdKeyToGuidMap?.get(targetKey) : undefined
                        relatedRecords.push(
                            await factory.createRecord({
                                source: targetShape,
                                table: SYS_VARIABLE_VALUE_TABLE,
                                properties: {
                                    document: ACTIVITY_TABLE,
                                    document_key: activitySysId,
                                    variable: sysId,
                                    value: targetGuid ?? '',
                                },
                            })
                        )
                        if (backingSysId) {
                            const inputTablePrefix =
                                backingType === 'action' ? 'sys_hub_action_input' : 'sys_hub_flow_input'
                            relatedRecords.push(
                                await factory.createRecord({
                                    source: targetShape,
                                    table: SYS_ELEMENT_MAPPING_TABLE,
                                    properties: {
                                        field: fieldName,
                                        id: activitySysId,
                                        table: `var__m_${inputTablePrefix}_${backingSysId}`,
                                        value: '',
                                    },
                                })
                            )
                        }
                    }
                }

                // Generate sys_variable_value and sys_element_mapping records for experience properties
                const experienceProperties = activityShape.getExperienceProperties()
                if (backingExperienceProperties && experienceProperties) {
                    for (const fluentName of experienceProperties.keys()) {
                        const varEntryShape = backingExperienceProperties.get(fluentName, false)
                        if (!varEntryShape) {
                            continue
                        }
                        const sysId = extractVariableSysId(varEntryShape)
                        if (!sysId) {
                            continue
                        }
                        const rawExpPropShape = experienceProperties.get(fluentName)!
                        const expPropShape =
                            rawExpPropShape instanceof TemplateValueShape
                                ? normalizeTemplateValue(rawExpPropShape)
                                : rawExpPropShape
                        const isPill = containsDataPill(expPropShape)
                        const resolvedValue = await resolvePlaybookPill(expPropShape, experiencePropertyPillContext)
                        relatedRecords.push(
                            await factory.createRecord({
                                source: expPropShape,
                                table: SYS_VARIABLE_VALUE_TABLE,
                                properties: {
                                    document: ACTIVITY_TABLE,
                                    document_key: activitySysId,
                                    variable: sysId,
                                    value: isPill ? '' : resolvedValue,
                                },
                            })
                        )
                        if (activityTypeSysId) {
                            relatedRecords.push(
                                await factory.createRecord({
                                    source: expPropShape,
                                    table: SYS_ELEMENT_MAPPING_TABLE,
                                    properties: {
                                        field: fluentName,
                                        id: activitySysId,
                                        table: `var__m_sys_pd_activity_type_prop_${activityTypeSysId}`,
                                        value: isPill ? resolvedValue : '',
                                    },
                                })
                            )
                        }
                    }
                }

                // Apply default experience property values for properties the user did not provide.
                // Precedence: the activity definition's defaultExperienceProperties wins; otherwise
                // fall back to a column-level defaultValue declared on the activity type.
                if (backingExperienceProperties) {
                    const userProvidedExpProps = experienceProperties
                        ? new Set(experienceProperties.keys())
                        : new Set<string>()
                    for (const fluentName of backingExperienceProperties.keys()) {
                        if (userProvidedExpProps.has(fluentName)) {
                            continue
                        }
                        const varEntryShape = backingExperienceProperties.get(fluentName, false)
                        if (!varEntryShape) {
                            continue
                        }
                        const defaultValue =
                            fluentName in defaultExperienceProperties
                                ? defaultExperienceProperties[fluentName]
                                : extractColumnDefaultValue(varEntryShape)
                        if (defaultValue === undefined) {
                            continue
                        }
                        const sysId = extractVariableSysId(varEntryShape)
                        if (!sysId) {
                            continue
                        }
                        const rawValue = String(defaultValue)
                        const isPill = [...rawValue.matchAll(STANDARD_PILL_REGEX)].length > 0
                        // Resolve {{act.act_instance. to the current activity's sys_id
                        const stringValue = isPill
                            ? rawValue.replace(/\{\{act\.act_instance\./g, `{{act.${activitySysId}.`)
                            : rawValue
                        relatedRecords.push(
                            await factory.createRecord({
                                source: activityShape,
                                table: SYS_VARIABLE_VALUE_TABLE,
                                properties: {
                                    document: ACTIVITY_TABLE,
                                    document_key: activitySysId,
                                    variable: sysId,
                                    value: isPill ? '' : stringValue,
                                },
                            })
                        )
                        if (activityTypeSysId) {
                            relatedRecords.push(
                                await factory.createRecord({
                                    source: activityShape,
                                    table: SYS_ELEMENT_MAPPING_TABLE,
                                    properties: {
                                        field: fluentName,
                                        id: activitySysId,
                                        table: `var__m_sys_pd_activity_type_prop_${activityTypeSysId}`,
                                        value: isPill ? stringValue : '',
                                    },
                                })
                            )
                        }
                    }
                }

                return {
                    success: true,
                    value: activityRecord.with(...relatedRecords),
                }
            },
        },
    ],
})
