import {
    type CallExpressionShape,
    IdentifierShape,
    ObjectShape,
    type Shape,
    VariableStatementShape,
} from '@servicenow/sdk-build-core'
import { ArrowFunctionShape } from '@servicenow/sdk-build-plugins'
import type { Database, Record as SdkRecord } from '@servicenow/sdk-build-core'
import { orderAndName } from '../utils/var-naming'

export interface ChildCollectionToShapeConfig {
    /** Parent record (used as AST source node) */
    source: SdkRecord
    /** Ordered child records to transform */
    childRecords: SdkRecord[]
    /** Database handle for child record lookups */
    database: Database
    /** Variable name prefix (e.g. 'lane' produces lane_0, lane_1, ...) */
    varPrefix: string
    /**
     * Callback that converts a single child record into a CallExpressionShape.
     * `usesCollectionParam` signals that the child references the collection callback's
     * parameter (e.g. a lane permission pill referencing `params.parentRecord`), so the
     * arrow must declare `collectionParamName`.
     */
    recordToShape: (
        record: SdkRecord,
        database: Database,
        guidToVarName: Map<string, string>
    ) => { success: true; value: CallExpressionShape; usesCollectionParam?: boolean } | { success: false }
    /**
     * Optional callback that extracts dependency GUIDs from a child record.
     * When provided, records are topologically sorted so that dependencies
     * are declared before the records that reference them (e.g. Run.After).
     */
    getDependencyGuids?: (record: SdkRecord) => string[]
    /**
     * Parameter name to declare on the generated arrow when any child reports
     * `usesCollectionParam`. Omitted → the arrow takes no parameters.
     */
    collectionParamName?: string
}

/**
 * Topologically sort records so that dependencies come before dependents.
 * Falls back to original order for records with no dependency relationships.
 *
 * Exported so callers that need to know the exact `${varPrefix}_${i}` variable name
 * `buildChildCollectionToShape` will assign to a given record (e.g. to build a
 * guid -> varName/key map ahead of calling it) can reproduce the identical order.
 */
export function topologicalSort(
    records: SdkRecord[],
    getDependencyGuids: (record: SdkRecord) => string[]
): SdkRecord[] {
    const guidToRecord = new Map<string, SdkRecord>()
    for (const record of records) {
        guidToRecord.set(record.getId().getValue(), record)
    }

    const sorted: SdkRecord[] = []
    const visited = new Set<string>()
    const visiting = new Set<string>()

    function visit(record: SdkRecord) {
        const guid = record.getId().getValue()
        if (visited.has(guid)) {
            return
        }
        if (visiting.has(guid)) {
            return // cycle — break it by skipping
        }
        visiting.add(guid)

        for (const depGuid of getDependencyGuids(record)) {
            const depRecord = guidToRecord.get(depGuid)
            if (depRecord) {
                visit(depRecord)
            }
        }

        visiting.delete(guid)
        visited.add(guid)
        sorted.push(record)
    }

    for (const record of records) {
        visit(record)
    }

    return sorted
}

/**
 * Build an ArrowFunctionShape representing a collection of child records.
 *
 * Records are ordered and named by var-naming.ts (dependencies first when `getDependencyGuids` is
 * given), then converted one by one through `recordToShape`.
 *
 * Returns a concise `() => ({})` for empty collections, or a block body with
 * variable declarations + return object for non-empty collections.
 */
export function buildChildCollectionToShape(config: ChildCollectionToShapeConfig): ArrowFunctionShape {
    const { source, childRecords, database, varPrefix, recordToShape, getDependencyGuids, collectionParamName } = config

    const { ordered: sortedRecords, names } = orderAndName(childRecords, varPrefix, getDependencyGuids)

    // Build shapes, tracking original indices so variable names stay stable even when some
    // records fail to convert.
    const childShapesWithIndex: { shape: CallExpressionShape; originalIndex: number }[] = []
    let needsParam = false
    for (const [i, record] of sortedRecords.entries()) {
        const result = recordToShape(record, database, names)
        if (result.success) {
            childShapesWithIndex.push({ shape: result.value, originalIndex: i })
            needsParam = needsParam || (result.usesCollectionParam ?? false)
        }
    }

    const parameters = collectionParamName && needsParam ? [collectionParamName] : []

    // Empty collection: concise form `() => ({})`
    if (childShapesWithIndex.length === 0) {
        return new ArrowFunctionShape({
            source,
            parameters,
            returnValue: new ObjectShape({ source, properties: {} }),
            implicitReturn: true,
        })
    }

    // Non-empty: variable declarations + return object
    const statements: Shape[] = []
    const returnEntries: Record<string, Shape> = {}
    for (const { shape, originalIndex } of childShapesWithIndex) {
        const varName = `${varPrefix}_${originalIndex}`
        statements.push(new VariableStatementShape({ source, variableName: varName, initializer: shape }))
        returnEntries[varName] = new IdentifierShape({ source, name: varName })
    }

    const returnValue = new ObjectShape({ source, properties: returnEntries })

    return new ArrowFunctionShape({
        source,
        parameters,
        statements,
        returnValue,
    })
}
