// ============================================================================
// Shared permission maps & per-reference-kind configuration
//
// Both directions consume these: permissions-torecord.ts (Fluent → XML) inverts
// each permission set into the platform's grouped {PERMISSION_KEY: [entry]} JSON,
// and permissions-toshape.ts (XML → Fluent) inverts that JSON back into the
// Fluent `permissions` shape. Keeping the maps in one place guarantees the two
// directions stay exact inverses of each other.
// ============================================================================

/** Execution type for which user/userGroup must be data pills (a sysId is rejected). */
export const RECORD_DRIVEN = 'record_driven'

/** Execution type requiring at least one permission set granting `launch`. */
export const ON_DEMAND = 'on_demand'

/**
 * Platform permission key for a reference that is listed but grants no permission.
 * It has no corresponding Fluent permission key: a permission set with a reference and
 * no granted keys serializes under NOOP, and a reference found only under NOOP
 * reconstructs to a set with no granted permissions. Not part of the fluent↔platform
 * key maps below.
 */
export const NOOP_PERMISSION_KEY = 'NOOP'

/** Playbook permissions: Fluent permission key → platform permission key (sys_pd_process_definition.permission JSON). */
export const PLAYBOOK_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP: Record<string, string> = {
    view: 'VIEW',
    laneAddOptionalActivity: 'LANE_ADD_OPTIONAL_ACTIVITY',
    cancel: 'CANCEL',
    restart: 'RESTART',
    laneRestart: 'LANE_RESTART',
    activityRestart: 'ACTIVITY_RESTART',
    launch: 'LAUNCH',
}

/** Lane permissions: Fluent permission key → platform permission key (sys_pd_lane.permission JSON). */
export const LANE_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP: Record<string, string> = {
    view: 'VIEW',
    addOptionalActivity: 'ADD_OPTIONAL_ACTIVITY',
    restart: 'RESTART',
    activityRestart: 'ACTIVITY_RESTART',
}

/**
 * Fluent permission keys that are required (non-optional) in the Fluent type and so must
 * always be emitted on reconstruction — `true` when granted, `false` otherwise. Playbook
 * `view` is required (it gates the other keys), so a NOOP playbook reference reconstructs
 * to `view: false`. Lane permission keys are all optional, so a NOOP lane reference emits
 * no permission keys.
 */
export const PLAYBOOK_REQUIRED_FLUENT_PERMISSION_KEYS: ReadonlySet<string> = new Set(['view'])
export const LANE_REQUIRED_FLUENT_PERMISSION_KEYS: ReadonlySet<string> = new Set()

// ============================================================================
// Per-reference-kind configuration
// ============================================================================

/**
 * Whether a sysId string is accepted for a reference kind.
 * nonRecordDriven means sysId is only supported if the playbook does not have 'Record driven' execution type.
 * SysIdPolicy is used to mirror restrictions in Playbook Designer, and diagnostics errors are emitted if sysId string
 * is used for a permission that doesn't allow it.
 */
export type SysIdPolicy = 'always' | 'never' | 'nonRecordDriven'

export interface PermissionConfig {
    /** Array field on the permissions object (e.g. 'users'). */
    arrayField: string
    /** Reference field on each entry (e.g. 'user'). */
    refField: string
    /** Platform source token (e.g. 'USER'). */
    source: string
    /** Whether a data pill reference is accepted. */
    allowPill: boolean
    /** Whether/when a sysId string reference is accepted. */
    allowSysId: SysIdPolicy
}

export const PLAYBOOK_PERMISSION_CONFIGS: PermissionConfig[] = [
    { arrayField: 'users', refField: 'user', source: 'USER', allowPill: true, allowSysId: 'nonRecordDriven' },
    {
        arrayField: 'userGroups',
        refField: 'userGroup',
        source: 'USER_GROUP',
        allowPill: true,
        allowSysId: 'nonRecordDriven',
    },
    { arrayField: 'roles', refField: 'role', source: 'USER_ROLE', allowPill: true, allowSysId: 'always' },
    {
        arrayField: 'userCriterias',
        refField: 'userCriteria',
        source: 'USER_CRITERIA',
        allowPill: false,
        allowSysId: 'always',
    },
]

export const LANE_PERMISSION_CONFIGS: PermissionConfig[] = [
    { arrayField: 'users', refField: 'user', source: 'USER', allowPill: true, allowSysId: 'never' },
    { arrayField: 'userGroups', refField: 'userGroup', source: 'USER_GROUP', allowPill: true, allowSysId: 'never' },
    { arrayField: 'roles', refField: 'role', source: 'USER_ROLE', allowPill: true, allowSysId: 'always' },
    {
        arrayField: 'userCriterias',
        refField: 'userCriteria',
        source: 'USER_CRITERIA',
        allowPill: false,
        allowSysId: 'always',
    },
]
