import { CallExpressionShape, type Diagnostics, type ObjectShape } from '@servicenow/sdk-build-core'
import { getActivityConfig } from './activity-utils'
import { isOptionalActivity, isRunAfterCallee } from './start-rule-resolver'

/**
 * Detects Run.After() calls that target an optional activity and emits a diagnostic for
 * each. An optional activity may never run, so nothing may depend on it — the type system
 * already rejects this (ManualActivityReference is excluded from the Dependency union),
 * this is the runtime backstop for JS/`any`/spread-from-untyped callers.
 */
export function validateManualActivityTargeting(
    children: Array<{ callExpr: CallExpressionShape; childConfig: ObjectShape }>,
    variables: Map<string, CallExpressionShape>,
    diagnostics: Diagnostics
): void {
    for (const { childConfig } of children) {
        const startRuleShape = childConfig.get('startRule')
        if (!startRuleShape.is(CallExpressionShape)) {
            continue
        }

        const startRuleCall = startRuleShape.as(CallExpressionShape)
        if (!isRunAfterCallee(startRuleCall.getCallee())) {
            continue
        }

        for (const arg of startRuleCall.getArguments()) {
            let targetCallExpr: CallExpressionShape | undefined
            if (arg.is(CallExpressionShape)) {
                targetCallExpr = arg.as(CallExpressionShape)
            } else if (arg.isIdentifier()) {
                targetCallExpr = variables.get(arg.asIdentifier().getName())
            }
            if (!targetCallExpr) {
                continue
            }

            const targetConfig = getActivityConfig(targetCallExpr)
            if (!targetConfig || !isOptionalActivity(targetConfig.get('startRule'))) {
                continue
            }

            const label = targetConfig.get('label')?.ifString()?.getValue() ?? '(unknown)'
            diagnostics.error(arg, `Run.After() cannot target '${label}' because it is an optional activity.`)
        }
    }
}
