import type { CallExpressionShape, ObjectShape } from '@servicenow/sdk-build-core'
import { ACTIVITY_CALLEE_NAMES } from '../constants/playbook-plugin-constants'

/** Extracts an Activity() call's config object (handling the `{ config: {...} }` nesting). */
export function getActivityConfig(callExpr: CallExpressionShape): ObjectShape | undefined {
    if (!ACTIVITY_CALLEE_NAMES.has(callExpr.getCallee())) {
        return undefined
    }
    const argObj = callExpr.getArgument(1)?.ifObject()
    if (!argObj) {
        return undefined
    }
    return argObj.get('config')?.isUndefined() === false ? argObj.get('config').ifObject() : argObj
}
