import { ts } from '@servicenow/sdk-build-core'

/**
 * Get the callee text of a CallExpression node (e.g. 'Activity', 'wfa.playbook.dataPill').
 * Returns undefined when the callee is not a plain identifier or property-access chain.
 */
export function getCalleeName(node: ts.CallExpression): string | undefined {
    const expr = node.getExpression()
    if (ts.Node.isIdentifier(expr) || ts.Node.isPropertyAccessExpression(expr)) {
        return expr.getText()
    }
    return undefined
}
