import type { OutputFile, Record as SdkRecord, Result } from '@servicenow/sdk-build-core'

/**
 * Builds the `delete_multiple` sweep query for a process-definition child table (lanes,
 * activities), matching the platform's own generation: rows scoped to `processDefinitionId`
 * whose sys_id isn't in `survivorIds` are deleted. Emitting this on every build (rather than
 * only when something was actually removed) avoids depending on delete tombstones, which the
 * SDK only ever populates with a sys_id for these tables.
 */
export function buildDeleteMultipleQuery(processDefinitionId: string, survivorIds: string[]): string {
    return survivorIds.length > 0
        ? `process_definition=${processDefinitionId}^sys_idNOT IN${survivorIds.join(',')}`
        : `process_definition=${processDefinitionId}`
}

/**
 * toFile for a process-definition child table (lanes, activities): claims deleted records and
 * emits nothing for them, since the `delete_multiple` sweep in playbookToFile already deletes
 * them. Without this, the generic catch-all still writes each one as its own inert per-row
 * DELETE update (the platform can't coalesce it — these tables have no sys_scope — so it's a
 * no-op, just noise). Non-deleted records are left unhandled so they still get bundled there.
 */
export function suppressDeletedChildToFile(record: SdkRecord): Result<OutputFile[]> {
    if (record.getAction() !== 'DELETE') {
        return { success: false }
    }
    return { success: true, value: [] }
}
