import type { Logger, Record as SdkRecord } from '@servicenow/sdk-build-core'
import {
    ArrayShape,
    BooleanShape,
    CallExpressionShape,
    type Database,
    Shape,
    TemplateValueShape,
} from '@servicenow/sdk-build-core'
import { ACTIVITY_DEF_SYS_ID_TO_KEY, type ResolvedVariableType } from '../constants/activity-ootb-maps'
import { TRIGGER_TYPE_SYS_ID_TO_IDENTIFIER } from '../constants/playbook-trigger-types'
import { type PillTransformContext, transformStandardPills } from './playbook-pill-transformer'
import { parseTemplateValueEntries } from './template-value-normalizer'
import {
    ACTIVITY_TABLE,
    PLAYBOOK_DEFAULT_PROCESS_TYPE_DB,
    TRIGGER_INSTANCE_TABLE,
} from '../constants/playbook-plugin-constants'

/**
 * Resolve a value that may be a raw string or a `Record<T>` reference
 * (e.g. `Record({ table: 'sys_user_role', data: { name: '...' } })`) to a
 * reference usable in a glide_list/reference column: the record's id when
 * it's a `Record<T>`, or its own string value otherwise.
 */
export function toReference(shape: Shape) {
    return shape.ifRecord()?.getId() ?? shape.ifString()?.getValue() ?? ''
}

// boolean can be '0' or '1' in the database, so we need to convert it to a boolean manually.
// 'true' or 'false' are handled by value.toBoolean()
function convertToBoolean(value: Shape) {
    const valueAsString = value.toString().getValue()
    if (valueAsString === '0' || valueAsString === '1') {
        return new BooleanShape({ source: value, value: valueAsString === '1' })
    }
    return value.toBoolean()
}

// field_list values are stored as CSV in the database. In fluent we want to use FieldList(['str1', 'str2']).
function convertToFieldList(value: Shape) {
    const valueAsString = value.toString().getValue()
    const elements = valueAsString
        ? valueAsString
              .split(',')
              .map((s) => s.trim())
              .filter(Boolean)
        : []
    return new CallExpressionShape({
        source: value,
        callee: 'FieldList',
        args: [new ArrayShape({ source: value, elements })],
    })
}

function convertToListColumnArray(value: Shape) {
    const valueAsString = value.toString().getValue()
    const elements = valueAsString
        ? valueAsString
              .split(',')
              .map((s) => s.trim())
              .filter(Boolean)
        : []
    return new ArrayShape({
        source: value,
        elements,
    })
}
/**
 * `TemplateValueShape.equals()` (and the `toString()` it's built on, in
 * `@servicenow/sdk-build-core`) compares fields via `String(value.getValue())`.
 * For a field whose value is a non-primitive Shape — e.g. a `wfa.playbook.dataPill(...)`
 * `CallExpressionShape` — `getValue()` falls back to the generic `Shape` default,
 * which returns a fresh `Symbol(this.getKind())`. That stringifies to the constant
 * `"Symbol(CallExpressionShape)"` regardless of what the pill actually points at, so
 * two `TemplateValue({...})` shapes that differ ONLY in a pill's target compare as
 * equal. XML → Fluent reconciliation uses that equality to decide whether to keep the
 * existing Fluent expression as-is, so a retargeted (or renamed-sibling) pill inside a
 * `TemplateValue` never gets regenerated — the stale reference is preserved forever.
 *
 * We always rebuild this shape fresh from the current record data here, so there's
 * nothing to gain from letting the framework "preserve unchanged" it — bypass the
 * broken comparison entirely and force reconciliation to always take our freshly
 * computed value.
 */
class FreshTemplateValueShape extends TemplateValueShape {
    override equals(): boolean {
        return false
    }
}

export function convertToTemplateValue(value: Shape, valueAsString?: string, pillContext?: PillTransformContext) {
    const source = value.getSource()
    const templateString = valueAsString === undefined ? value.toString() : Shape.from(source, valueAsString).asString()
    const rawString = templateString.getValue()

    // Shared parser — handles ^^ escaping consistently with reconstructTemplateValue.
    const entries = parseTemplateValueEntries(rawString, source)

    // If the value is not actually in template_value encoded form, preserve
    // the previous pill/string reconstruction behavior instead of forcing an
    // empty TemplateValue({}) wrapper.
    if (entries.length === 0 && rawString !== '') {
        return pillContext ? (transformStandardPills(rawString, source, pillContext) ?? templateString) : templateString
    }

    if (entries.length === 0) {
        // Empty string — return an empty TemplateValueShape (preserves original behavior).
        return TemplateValueShape.from(source, templateString)
    }

    const templateValue = new TemplateValueShape({ source, value: Object.fromEntries(entries) })

    if (!pillContext) {
        return templateValue
    }

    const reconstructedValue: globalThis.Record<string, unknown> = {}
    let hasPill = false
    for (const [field, fieldShape] of entries) {
        const transformed =
            fieldShape.ifString() !== undefined
                ? transformStandardPills(fieldShape.toString().getValue(), fieldShape, pillContext)
                : undefined
        if (transformed !== undefined) {
            hasPill = true
        }
        reconstructedValue[field] = transformed ?? fieldShape
    }

    // Only bypass equals()/toString() for shapes that actually contain a pill — a
    // literal-only TemplateValue's fields are plain strings/numbers, whose real
    // getValue() already makes the base class's change-detection accurate, so let
    // it behave normally (and preserve formatting) rather than force a needless
    // regeneration on every transform run.
    const ShapeClass = hasPill ? FreshTemplateValueShape : TemplateValueShape
    return new ShapeClass({
        source,
        value: reconstructedValue,
    })
}
export function convertValueToType(value: Shape, type: ResolvedVariableType) {
    switch (type) {
        case 'boolean':
            return convertToBoolean(value)
        case 'field_list':
            return convertToFieldList(value)
        case 'glide_list':
            return convertToListColumnArray(value)
        case 'template_value':
            return convertToTemplateValue(value)
        default:
            return value
    }
}

/**
 * Returns true if the playbook contains any feature Fluent cannot yet represent,
 * signalling that toShape should fall back to RecordPlugin.
 *
 * Checks (in order):
 *  1. schema_version < 3
 *  2. Custom process type (non-default)
 *  3. Unrecognized trigger type
 *  4. Unrecognized activity definition
 *  5. Variant-only lanes (sys_pd_lane.variant is set) — activities support this via the
 *     `variant` field, but LaneConfig has no equivalent, so a lane scoped to a variant on
 *     the platform can't be represented in Fluent.
 *
 * All detected issues are logged before returning so the caller learns all reasons
 * in a single pass rather than one at a time.
 */
export function hasUnsupportedFeatures(descendants: Database, record: SdkRecord, logger: Logger): boolean {
    const playbookId = record.getId().getValue()
    const playbookLabel =
        record.get('label')?.ifString()?.getValue() || record.get('name')?.ifString()?.getValue() || ''
    const playbookRef = playbookLabel ? `"${playbookLabel}" (${playbookId})` : playbookId
    const reasons: string[] = []

    // Schema version — only version 3 and above is supported
    const schemaVersionField = record.get('schema_version')
    if (schemaVersionField.isUndefined()) {
        reasons.push(`Playbook has no schema_version, falling back to Record() api. Playbook = ${playbookRef}`)
    } else {
        const schemaVersion = schemaVersionField.toNumber().getValue()
        if (schemaVersion < 3) {
            reasons.push(
                `Playbook has schema_version ${schemaVersion} (minimum supported is 3), ` +
                    `falling back to Record() api. Playbook = ${playbookRef}`
            )
        }
    }

    // Process type — only the default (Standard playbook) is supported
    const processTypeField = record.get('process_type')?.ifString()?.getValue() ?? ''
    if (processTypeField !== '' && processTypeField !== PLAYBOOK_DEFAULT_PROCESS_TYPE_DB) {
        reasons.push(
            `Playbook has custom process type (not yet supported by Fluent), ` +
                `falling back to Record() api. Playbook = ${playbookRef}`
        )
    }

    for (const trigger of descendants.query(TRIGGER_INSTANCE_TABLE)) {
        const typeGuid = trigger.get('trigger_type')?.ifString()?.getValue() ?? ''
        if (typeGuid && !TRIGGER_TYPE_SYS_ID_TO_IDENTIFIER[typeGuid]) {
            reasons.push(
                `Playbook has unsupported trigger type (sys_id: ${typeGuid}), ` +
                    `falling back to Record() api. Playbook = ${playbookRef}`
            )
        }
    }

    for (const activity of descendants.query(ACTIVITY_TABLE)) {
        const defSysId = activity.get('activity_definition')?.ifString()?.getValue() ?? ''
        if (defSysId && !ACTIVITY_DEF_SYS_ID_TO_KEY[defSysId]) {
            reasons.push(
                `Playbook has unrecognized activity definition (sys_id: ${defSysId}), ` +
                    `falling back to Record() api. Playbook = ${playbookRef}`
            )
        }
    }

    for (const reason of reasons) {
        logger.warn(reason)
    }
    return reasons.length > 0
}

// Caches the unsupported-features result per (database instance, parentSysId) pair.
// WeakMap keying on the Database object means cache entries are automatically freed
// when the Database is garbage collected (i.e. after each transform run completes),
// so results never leak between runs or test cases.
const unsupportedFeaturesCache = new WeakMap<object, Map<string, boolean>>()

/**
 * Returns true if the playbook identified by playbookSysId has any unsupported feature,
 * signalling that toShape should fall back to RecordPlugin.
 *
 * Called by all plugins in the playbook tree:
 *   - PlaybookDefinitionPlugin passes record.getId().getValue() and its pre-filtered descendants
 *     (the SDK-provided view that excludes deleted records, ensuring a deletion of an unsupported
 *     child — e.g. an unrecognized activity — is correctly reflected as the playbook becoming supported)
 *   - LanePlugin, ActivityPlugin, PlaybookTriggerInstancePlugin pass their process_definition field
 *     (the foreign key that holds the sys_id of the parent sys_pd_process_definition record)
 *     and no descendants, relying on the cache being warm from PlaybookDefinitionPlugin running first
 *
 * The result is cached per (database instance, playbookSysId) so the descendant scan runs at
 * most once per playbook regardless of which plugin calls it first or how many children exist.
 */
export function isPlaybookUnsupported(
    record: SdkRecord,
    database: Database,
    logger?: Logger,
    descendants?: Database
): boolean {
    let playbookSysId = record.get('process_definition')?.ifString()?.getValue()

    let cacheForDb = unsupportedFeaturesCache.get(database)
    if (!cacheForDb) {
        cacheForDb = new Map()
        unsupportedFeaturesCache.set(database, cacheForDb)
    }

    if (playbookSysId) {
        if (!cacheForDb.has(playbookSysId)) {
            return true
        }
        return cacheForDb.get(playbookSysId)!
    }

    if (descendants && record && logger) {
        const result = hasUnsupportedFeatures(descendants, record, logger)
        playbookSysId = record.getId().getValue()
        cacheForDb.set(playbookSysId, result)
        return result
    }
    return true
}
