import { CallExpressionShape } from '@servicenow/sdk-build-core'
import type { Diagnostics, ObjectShape, Shape } from '@servicenow/sdk-build-core'
import { DATAPILL_CALLEE } from '../constants/playbook-plugin-constants'

/**
 * Validates that every column marked `mandatory: true` in a backing schema
 * (ActivityType experienceProperties, or backing Action/Subflow inputs) has a
 * non-empty effective value on the user's Activity() call.
 *
 * ## Effective value resolution
 *
 * A mandatory column's effective value is checked against either:
 * - The user's own explicit value (`userValues`), even if that value turns
 *   out to be empty — an explicit value always wins over the definition
 *   default, matching `ActivityPlugin`'s own precedence.
 * - Otherwise, the activity definition's default (`defaultValues`, e.g.
 *   `defaultExperienceProperties`/`defaultInputs`), when the user omits the
 *   property entirely, or omits `userValues` altogether (e.g. no `inputs`
 *   argument was passed to `wfa.playbook.activity(...)` at all).
 *
 * ## When validation is skipped
 *
 * - The column definition isn't a recognized factory call, or has no
 *   `mandatory: true` flag.
 * - The effective value is a `wfa.playbook.dataPill(...)` call — its
 *   concrete value is only known at runtime and must not be treated as
 *   empty just because it can't be inspected statically.
 *
 * @param columnDefinitions - Column schema from the ActivityType or backing
 *     Action/Subflow (e.g. `{ table: TableNameColumn({ mandatory: true, ... }) }`)
 * @param userValues - Actual values from the user's Activity() call, or undefined
 *     if the corresponding `inputs`/`experienceProperties` argument was omitted entirely
 * @param defaultValues - The activity definition's `defaultExperienceProperties`/
 *     `defaultInputs`, or undefined if the definition declares none
 * @param diagnosticAnchor - Fallback shape to anchor an error on when both
 *     `userValues` and its relevant property are undefined (e.g. the activity's
 *     own config shape)
 * @param diagnostics - Diagnostics reporter for emitting errors
 */
export function validateMandatoryFields(
    columnDefinitions: ObjectShape,
    userValues: ObjectShape | undefined,
    defaultValues: ObjectShape | undefined,
    diagnosticAnchor: Shape,
    diagnostics: Diagnostics
): void {
    for (const propName of columnDefinitions.keys()) {
        const columnShape = columnDefinitions.get(propName, false)
        if (!columnShape) {
            continue
        }

        // Column definitions are factory calls like:
        //   TableNameColumn({ mandatory: true, label: 'Table', ... })
        const callExpr = columnShape.if(CallExpressionShape)
        if (!callExpr) {
            continue
        }

        const columnConfig = callExpr.getArgument(0)?.ifObject()
        if (!columnConfig) {
            continue
        }

        const isMandatory = columnConfig.get('mandatory', false)?.ifBoolean()?.getValue()
        if (!isMandatory) {
            continue
        }

        // An explicit user value always wins over the definition default —
        // even if that explicit value is itself empty.
        const explicitShape = userValues?.get(propName, false)
        const explicitDefined = explicitShape !== undefined && explicitShape.isUndefined() === false
        const effectiveShape = explicitDefined ? explicitShape : defaultValues?.get(propName, false)

        // Skip validation when the effective value is a dataPill — it's
        // determined at runtime and cannot be checked statically.
        if (effectiveShape && isDataPill(effectiveShape)) {
            continue
        }

        if (!isEffectivelyEmpty(effectiveShape)) {
            continue
        }

        const label = columnConfig.get('label', false)?.ifString()?.getValue() ?? propName
        diagnostics.error(
            explicitShape ?? userValues ?? diagnosticAnchor,
            `'${propName}' (${label}) is required and cannot be empty.`
        )
    }
}

/**
 * True when the shape is missing, undefined, or a blank/whitespace-only string.
 */
function isEffectivelyEmpty(shape: Shape | undefined): boolean {
    if (!shape || shape.isUndefined()) {
        return true
    }
    const strValue = shape.ifString()?.getValue()
    if (strValue !== undefined) {
        return strValue.trim() === ''
    }
    return false
}

/**
 * Returns true when the shape is a `wfa.playbook.dataPill(...)` call whose
 * value is determined at runtime and cannot be validated statically.
 */
function isDataPill(shape: Shape): boolean {
    const call = shape.if(CallExpressionShape)
    return call !== undefined && call.getCallee() === DATAPILL_CALLEE
}
