import type { Record as SdkRecord } from '@servicenow/sdk-build-core'
import { orderAndNameInterleaved, orderAndNameLaneActivities, orderAndNameLanes } from './var-naming'

/**
 * Where a lane/activity guid lives in the reconstructed Fluent source: the variable it is bound to,
 * the lane variable enclosing it (absent for a lane or a stage-level activity), and which kind of
 * record it is — so callers can reject a kind mismatch, e.g. a `go_back_to_target_stage` field whose
 * stored guid actually belongs to an activity.
 */
export interface VarPathEntry {
    varName: string
    laneVarName?: string
    kind: 'lane' | 'activity'
}

/** Whole-playbook guid -> variable info, for the XML -> Fluent (toShape) direction. */
export type GuidToVarPath = Map<string, VarPathEntry>

/** How a guid can be written from a given scope: a bare identifier, or a `lane.activity` dot-walk. */
export type VarAddress = { form: 'bare'; name: string } | { form: 'dotted'; laneVarName: string; name: string }

/**
 * Resolves how `guid` is addressed from inside `fromLaneVarName` (undefined = the lanes body).
 *
 * A lane, a stage-level activity, or an activity in the same lane is a bare identifier — lane and
 * stage-level consts are visible by closure from any nested `activities` body, and same-lane
 * siblings are visible directly. An activity in a different lane is only reachable as
 * `laneVar.activityVar`, so callers that have no dot-walk form (`Run.After`) must fall back rather
 * than emit an out-of-scope identifier.
 */
export function addressFrom(
    guidToVarPath: GuidToVarPath | undefined,
    guid: string,
    fromLaneVarName: string | undefined
): VarAddress | undefined {
    const entry = guidToVarPath?.get(guid)
    if (!entry) {
        return undefined
    }
    if (entry.laneVarName && entry.laneVarName !== fromLaneVarName) {
        return { form: 'dotted', laneVarName: entry.laneVarName, name: entry.varName }
    }
    return { form: 'bare', name: entry.varName }
}

/** The lane variable enclosing `record`, or undefined when it sits at the lanes body level. */
export function ownLaneVarName(record: SdkRecord, guidToVarPath: GuidToVarPath | undefined): string | undefined {
    const laneGuid = record.get('lane')?.ifString()?.getValue() ?? ''
    if (!laneGuid) {
        return undefined
    }
    const entry = guidToVarPath?.get(laneGuid)
    return entry?.kind === 'lane' ? entry.varName : undefined
}

/**
 * Builds the whole-playbook map in one pre-pass, before any incremental per-level reconstruction
 * runs, so it can answer "what variable is this guid?" for ANY lane or activity — not just the ones
 * already reconstructed at the current collection level. That cross-level reach is what a
 * cross-lane Go Back target (`laneVar.activityVar`) needs, and what per-level naming cannot give.
 * Pill reconstruction deliberately does NOT use this map — see buildLaneToShapeResult.
 *
 * Ordering and naming come from var-naming.ts, the same helpers the incremental builders use, so
 * the names here are the names those builders actually emit.
 */
export function buildGuidToVarPathMap(laneRecords: SdkRecord[], allActivities: SdkRecord[]): GuidToVarPath {
    const guidToVarPath: GuidToVarPath = new Map()
    const stageLevelActivities = allActivities.filter((rec) => (rec.get('lane')?.ifString()?.getValue() ?? '') === '')

    function addLane(record: SdkRecord, varName: string): void {
        const laneGuid = record.getId().getValue()
        guidToVarPath.set(laneGuid, { varName, kind: 'lane' })
        for (const [activityGuid, activityVarName] of orderAndNameLaneActivities(allActivities, laneGuid).names) {
            guidToVarPath.set(activityGuid, { varName: activityVarName, laneVarName: varName, kind: 'activity' })
        }
    }

    if (stageLevelActivities.length === 0) {
        const { ordered, names } = orderAndNameLanes(laneRecords)
        for (const record of ordered) {
            addLane(record, names.get(record.getId().getValue())!)
        }
        return guidToVarPath
    }

    for (const { record, type, varName } of orderAndNameInterleaved(laneRecords, stageLevelActivities).ordered) {
        if (type === 'lane') {
            addLane(record, varName)
        } else {
            guidToVarPath.set(record.getId().getValue(), { varName, kind: 'activity' })
        }
    }
    return guidToVarPath
}
