import {
    type CallExpressionShape,
    type Diagnostics,
    IdentifierShape,
    ObjectShape,
    VariableStatementShape,
} from '@servicenow/sdk-build-core'
import { ArrowFunctionShape, NowIdShape } from '@servicenow/sdk-build-plugins'
import { LaneShape } from '../utils/playbook-shapes'
import { ACTIVITY_TABLE, LANE_DEFAULTS } from '../constants/playbook-plugin-constants'
import { activityRecordToShape } from './activity-config-transform'
import { resolveStartRuleToShape } from '../utils/start-rule-resolver'
import type { Database, Record as SdkRecord, Shape } from '@servicenow/sdk-build-core'
import { findTimerRecord, timerAttributesToShape } from './timer-attributes-transform'
import {
    type ActivityIdentifier,
    type PillTransformContext,
    transformConditionPills,
} from '../utils/playbook-pill-transformer'
import { buildLanePermissionsToShape } from './permissions-toshape'
import type { GuidToVarPath } from '../utils/guid-to-var-path-map'
import { activitiesInLane, orderAndName, startsAfterActivities } from '../utils/var-naming'
import { buildActivityPositionMap } from '../utils/variant-override-ordering'

export { resolveStartRuleToDatabase as resolveStartRule } from '../utils/start-rule-resolver'

export function buildLaneToShapeResult(
    record: SdkRecord,
    database: Database,
    diagnostics: Diagnostics,
    guidToVarPath?: GuidToVarPath,
    timerRecords?: SdkRecord[],
    globalActivityMap?: Map<string, ActivityIdentifier>,
    branchGuidMap?: Map<string, { activityVarName: string; fluentBranchId: string }>,
    // guid → Now.ID key for every activity in the playbook, built once at the playbook
    // level and threaded in, to regenerate cross-scope activityRef() pills in permissions.
    // (Distinct from globalActivityMap, which carries lexical variable names filled in
    // incrementally as lanes are processed.)
    activityGuidToNowId?: Map<string, NowIdShape>,
    // Every activity in the playbook, already queried once at the playbook level. When present,
    // this lane's own activities are filtered from it instead of re-querying the database. Absent
    // only for the standalone-record path (LanePlugin's toShape), which has no such pre-fetch.
    allActivities?: SdkRecord[],
    // sys_pd_activity_override descendants for the whole playbook, threaded down to each
    // activity in this lane's collection.
    overrideRecords?: SdkRecord[],
    // Variant guid -> property-name key, threaded down for reconstructing
    // `params.variants.<key>` references.
    variantGuidToKey?: Map<string, string>
): { success: true; value: CallExpressionShape; usesParentRecord: boolean } | { success: false } {
    const { startRuleShape } = resolveStartRuleToShape(record, guidToVarPath, branchGuidMap)

    // The pill context only contains activities from previously-processed lanes at this point — the
    // current lane's activities are added later in buildActivityCollectionToShape. That
    // incompleteness is depended upon, not tolerated: a lane's conditionToRun and timer attributes
    // sit in the lanes body, where its own activities are not in scope, so resolving one would emit
    // an identifier that doesn't exist. Don't swap globalActivityMap for the whole-playbook map here.
    const currentLaneVarName = guidToVarPath?.get(record.getId().getValue())?.varName
    const pillContext: PillTransformContext | undefined = globalActivityMap
        ? {
              activityMap: globalActivityMap,
              ...(currentLaneVarName ? { currentLaneVarName } : {}),
          }
        : undefined

    // Find matching timer record for this lane
    const timerRecord = timerRecords
        ? findTimerRecord(timerRecords, record.getId().getValue(), 'sys_pd_lane')
        : undefined

    const configShape = record.transform(({ $ }) => ({
        $id: $.val(NowIdShape.from(record)),
        label: $.from('label'),
        name: $.from('name'),
        order: $.from('order').toNumber(),
        description: $.from('description').def(''),
        startRule: $.val(startRuleShape),
        conditionToRun: $.from('condition_to_run')
            .def(LANE_DEFAULTS.CONDITION_TO_RUN)
            .map((v: Shape) => {
                if (!pillContext) {
                    return v
                }
                const str = v.ifString()?.getValue()
                if (!str) {
                    return v
                }
                return transformConditionPills(str, record, pillContext) ?? v
            }),
        restartRule: $.from('restart_rule'),
        ...(timerRecord
            ? {
                  startWithDelay: $.val(timerAttributesToShape(timerRecord, pillContext)),
              }
            : {}),
    }))

    // Reconstruct the lane permissions object onto the config (last property), if any.
    // parentRecord pills inside reference the enclosing lanes callback's `params`, so
    // report usesParentRecord up so that callback can declare its parameter.
    const lanePermissions = buildLanePermissionsToShape(
        record.get('permission')?.ifString()?.getValue(),
        record,
        activityGuidToNowId ?? new Map(),
        diagnostics
    )
    const finalConfigShape = lanePermissions ? configShape.merge({ permissions: lanePermissions.object }) : configShape

    const activityRecords = allActivities
        ? activitiesInLane(allActivities, record.getId().getValue())
        : database.query(ACTIVITY_TABLE, { lane: record.getId().getValue() })
    const { activitiesArrow, usesParentRecord: activitiesUseParentRecord } = buildActivityCollectionToShape(
        record,
        activityRecords,
        database,
        globalActivityMap,
        currentLaneVarName,
        timerRecords,
        guidToVarPath,
        overrideRecords,
        variantGuidToKey
    )

    return {
        success: true,
        value: new LaneShape({
            source: record,
            config: finalConfigShape,
            activities: activitiesArrow,
        }),
        usesParentRecord: (lanePermissions?.usesParentRecord ?? false) || activitiesUseParentRecord,
    }
}

/**
 * Build activity collection with branch-aware resolution.
 *
 * This is a specialized version of buildChildCollectionToShape that:
 * 1. Topologically sorts activities so dependencies come first
 * 2. Populates the shared globalActivityMap with this lane's activities
 * 3. Processes activities in order, accumulating branch GUID maps from Decision activities
 * 4. Passes the accumulated branch map to each activity's toShape so that
 *    starts_after_branches GUIDs resolve to PropertyAccessShape references
 */
function buildActivityCollectionToShape(
    source: SdkRecord,
    activityRecords: SdkRecord[],
    database: Database,
    globalActivityMap?: Map<string, ActivityIdentifier>,
    currentLaneVarName?: string,
    timerRecords?: SdkRecord[],
    // Threaded straight through to activityRecordToShape; not otherwise used by this function.
    guidToVarPath?: GuidToVarPath,
    overrideRecords?: SdkRecord[],
    variantGuidToKey?: Map<string, string>
): { activitiesArrow: ArrowFunctionShape; usesParentRecord: boolean } {
    // Ordering and `activity_i` naming come from var-naming.ts — the same helpers the
    // whole-playbook pre-pass uses, so both assign the same names.
    const { ordered: sortedRecords, names: activityGuidToVarName } = orderAndName(
        activityRecords,
        'activity',
        startsAfterActivities
    )

    // Same base topological order as above, keyed by guid -> position, for detecting
    // variantOverrides dependencies that would require a forward reference to a not-yet-declared
    // const (DEF0906759) — see activityRecordToShape's activityPositionInLane param.
    const activityPositionInLane = buildActivityPositionMap(sortedRecords)

    // Populate the shared global activity map so same-lane and cross-lane pill references resolve.
    for (const [guid, varName] of activityGuidToVarName) {
        globalActivityMap?.set(guid, {
            varName,
            ...(currentLaneVarName ? { laneVarName: currentLaneVarName } : {}),
        })
    }

    // Build pill context for activities in this lane
    const pillContext: PillTransformContext | undefined = globalActivityMap
        ? {
              activityMap: globalActivityMap,
              ...(currentLaneVarName ? { currentLaneVarName } : {}),
          }
        : undefined

    // Process each activity, accumulating branch maps
    // branchGuidMap: branch GUID → { activityVarName, fluentBranchId }
    const branchGuidMap = new Map<string, { activityVarName: string; fluentBranchId: string }>()

    const childShapesWithIndex: { shape: CallExpressionShape; originalIndex: number }[] = []
    let usesParentRecord = false
    for (const [i, rec] of sortedRecords.entries()) {
        const result = activityRecordToShape(
            rec,
            database,
            guidToVarPath,
            branchGuidMap,
            pillContext,
            timerRecords,
            overrideRecords,
            variantGuidToKey,
            activityPositionInLane
        )
        if (result.success) {
            childShapesWithIndex.push({ shape: result.value, originalIndex: i })
            usesParentRecord = usesParentRecord || result.usesParentRecord

            // If this is a Decision activity with a branch map, register all branches
            if (result.branchMap) {
                const activityGuid = rec.getId().getValue()
                // activityGuidToVarName was built from this same sortedRecords array (via
                // orderAndName above), so every rec here already has an entry.
                const activityVarName = activityGuidToVarName.get(activityGuid)!
                for (const [branchGuid, fluentBranchId] of result.branchMap) {
                    branchGuidMap.set(branchGuid, { activityVarName, fluentBranchId })
                }
            }
        }
    }

    // Empty collection: concise form `() => ({})`
    if (childShapesWithIndex.length === 0) {
        return {
            activitiesArrow: new ArrowFunctionShape({
                source,
                parameters: [],
                returnValue: new ObjectShape({ source, properties: {} }),
                implicitReturn: true,
            }),
            usesParentRecord,
        }
    }

    // Non-empty: variable declarations + return object
    const statements: Shape[] = []
    const returnEntries: Record<string, Shape> = {}
    for (const { shape, originalIndex } of childShapesWithIndex) {
        const varName = `activity_${originalIndex}`
        statements.push(new VariableStatementShape({ source, variableName: varName, initializer: shape }))
        returnEntries[varName] = new IdentifierShape({ source, name: varName })
    }

    const returnValue = new ObjectShape({ source, properties: returnEntries })

    return {
        activitiesArrow: new ArrowFunctionShape({
            source,
            parameters: [],
            statements,
            returnValue,
        }),
        usesParentRecord,
    }
}
