import type { Record as SdkRecord } from '@servicenow/sdk-build-core'
import { isRunAfterCallee, START_RULE_TO_RUN_CALLEE } from './start-rule-resolver'
import { guidList } from './var-naming'

/**
 * Maps each activity's guid to its position (index) in `orderedLaneActivities` — the base
 * topological order (see `orderAndNameLaneActivities` in var-naming.ts) that fixes
 * `const activity_i` declaration order in generated code. Build once per lane and reuse across
 * every activity/override in that lane rather than recomputing per override.
 */
export function buildActivityPositionMap(orderedLaneActivities: SdkRecord[]): Map<string, number> {
    const activityPosition = new Map<string, number>()
    orderedLaneActivities.forEach((activity, index) => {
        activityPosition.set(activity.getId().getValue(), index)
    })
    return activityPosition
}

/**
 * Returns the subset of `overrideRecord`'s own Run.After() dependencies
 * (`starts_after_activities`) that target an activity positioned at or after its own
 * `override_parent` in the base activity order (`activityPosition`, from
 * `buildActivityPositionMap`). Variant overrides never influence base `const activity_i`
 * declaration order (only base `starts_after_activities` edges do — see
 * orderAndNameLaneActivities in var-naming.ts), so such a dependency can't be expressed as a bare
 * same-scope `const` reference: it would be a forward reference to a not-yet-initialized
 * `const` — and, when the override direction reverses an existing base edge between the same
 * two activities, resolving that reference can trigger the SDK's own (uncached, re-entrant)
 * forward-reference resolution and crash with an OOM (DEF0906759).
 *
 * Callers emit `wfa.playbook.activityRef(Now.ID['<guid>'])` — a literal lookup that never
 * requires the target's lexical declaration to exist yet — instead of a bare identifier for
 * every guid in the returned set. See `resolveRunAfterShape` in start-rule-resolver.ts.
 */
export function forwardReferencingOverrideDependencies(
    overrideRecord: SdkRecord,
    activityPosition: Map<string, number>
): Set<string> {
    const startRuleName = overrideRecord.get('start_rule_name')?.ifString()?.getValue() ?? ''
    const runCallee = START_RULE_TO_RUN_CALLEE[startRuleName]
    if (!runCallee || !isRunAfterCallee(runCallee)) {
        return new Set()
    }

    const overrideParentGuid = overrideRecord.get('override_parent')?.ifString()?.getValue() ?? ''
    const parentPosition = activityPosition.get(overrideParentGuid)
    if (parentPosition === undefined) {
        return new Set()
    }

    return new Set(
        guidList(overrideRecord, 'starts_after_activities').filter((depGuid) => {
            const depPosition = activityPosition.get(depGuid)
            return depPosition !== undefined && depPosition >= parentPosition
        })
    )
}
