import {
    CallExpressionShape,
    Shape,
    type Database,
    type Diagnostics,
    type Factory,
    type ObjectShape,
    type Record as SdkRecord,
} from '@servicenow/sdk-build-core'
import {
    addFieldsToColumn,
    COLUMN_API_TO_TYPE,
    COLUMN_TYPE_TO_API,
    getDefaultMaxLength,
    getDocumentationRecords,
} from '@servicenow/sdk-build-plugins/column'
import { PLAYBOOK_TABLE, SYS_VARIABLE_VALUE_TABLE } from '../constants/playbook-plugin-constants'
import { toReference } from './transform-utils'
const GenericColumn = { name: 'GenericColumn' as const }

/**
 * Build sys_pd_process_input or sys_pd_process_output records from a playbook
 * declarations config. Column type is resolved generically via COLUMN_API_TO_TYPE,
 * so any Column helper the SDK supports (String, Boolean, Integer, Choice, Date,
 * Reference, etc.) is handled, not just String/Reference.
 */
export async function buildPlaybookVariableRecords(options: {
    variablesConfig: ObjectShape
    parentRecord: SdkRecord
    factory: Factory
    diagnostics: Diagnostics
    parentTable: string
    varTable: string
}): Promise<SdkRecord[]> {
    const { variablesConfig, parentRecord, factory, diagnostics, parentTable, varTable } = options

    const records: SdkRecord[] = []
    const tableName = `var__m_${varTable}_${parentRecord.getId().getValue()}`
    const entries = variablesConfig.entries()

    for (const [i, [k, v]] of entries.entries()) {
        const callExpr = v.as(CallExpressionShape)
        const config = callExpr.getArgument(0).asObject()

        const orderFromShape = config.get('order')?.ifNumber()?.getValue()
        const internalType =
            callExpr.getCallee() === GenericColumn.name
                ? (config.get('columnType')?.ifString()?.getValue() ?? 'string')
                : (COLUMN_API_TO_TYPE[callExpr.getCallee() as keyof typeof COLUMN_API_TO_TYPE] ?? 'string')

        const maxLength = config.get('maxLength')?.ifNumber()?.getValue() ?? getDefaultMaxLength(internalType)

        const props = config.transform(({ $ }) => ({
            element: $.val(k),
            label: $.def(k),
            mandatory: $.toBoolean().def(false),
            active: $.val(true),
            order: $.val(orderFromShape ?? (i + 1) * 100),
            hint: $.def(''),
            model: $.val(parentRecord),
            model_id: $.val(parentRecord),
            model_table: $.val(parentTable),
            name: $.val(tableName),
            default_value: $.from('default').def(''),
            internal_type: $.val(internalType),
            max_length: $.val(maxLength),
            attributes: $.val(''),
            reference: $.from('referenceTable').def(''),
            reference_qual: $.from('referenceQual').def(''),
        }))

        const varRecord = await factory.createRecord({
            source: callExpr,
            table: varTable,
            properties: props,
        })

        const updatedCallExpr = addFieldsToColumn({ name: k, table: tableName, display: false }, callExpr)
        const docRecords = await getDocumentationRecords(updatedCallExpr, {}, factory, diagnostics, true)
        records.push(...docRecords)

        records.push(varRecord)
    }

    return records
}

/**
 * Build CallExpressionShapes from sys_pd_process_input or sys_pd_process_output
 * records for the toShape (XML → Fluent) direction.
 */
export function buildPlaybookVariableShapes(
    variableRecords: SdkRecord[],
    descendants: Database
): Record<string, CallExpressionShape> {
    const shapes: Record<string, CallExpressionShape> = {}

    const sorted = [...variableRecords].sort((a, b) => {
        const aOrder = Number(a.get('order')?.toString()?.getValue() ?? 0)
        const bOrder = Number(b.get('order')?.toString()?.getValue() ?? 0)
        return aOrder - bOrder
    })

    for (const variable of sorted) {
        const name = variable.get('element').asString().getValue()
        const internalType = variable.get('internal_type').asString().getValue()
        const callExpressionName =
            COLUMN_TYPE_TO_API[internalType as keyof typeof COLUMN_TYPE_TO_API] ?? GenericColumn.name

        const variableName = variable.get('name').ifString()?.getValue()
        const documentation = variableName
            ? descendants.query('sys_documentation', { name: variableName, element: name })
            : []
        const hint = documentation[0]?.get('hint')?.ifString()?.getValue() ?? ''

        const defaultMaxLength = getDefaultMaxLength(internalType)
        const maxLength = Number(variable.get('max_length').asString().getValue())

        const orderValue = Number(variable.get('order')?.toString()?.getValue() ?? 0)

        shapes[name] = new CallExpressionShape({
            source: variable,
            callee: callExpressionName,
            args: [
                variable.transform(({ $ }) => ({
                    label: $,
                    mandatory: $.toBoolean().def(false),
                    maxLength: $.val(maxLength).def(defaultMaxLength),
                    default: $.from('default_value').def(''),
                    ...(hint ? { hint: $.val(hint) } : {}),
                    ...(orderValue > 0 ? { order: $.val(orderValue) } : {}),
                    referenceTable: $.from('reference').def(''),
                    referenceQual: $.from('reference_qual').def(''),
                })),
            ],
        })
    }

    return shapes
}

/**
 * Build `sys_variable_value` records that prefill declared playbook `inputs` in the
 * on-demand launcher form. Iterates every declared input (not just keys explicitly
 * listed in `launcherInputsConfig`), so an input's own `Column({ default: ... })` still
 * produces a mirrored record when no explicit override is given.
 *
 * Resolution order per input: explicit `launcherInputsConfig[element]` override → else
 * the input's own non-empty `default_value` → else no record is created for that input.
 *
 * `launcherInputsConfig` key validation (requires `inputs` to be declared, keys must match
 * a declared input) lives in `PlaybookDiagnosticsPlugin`, not here.
 *
 * `launcherInUse` should be `launcherShowRecordForm === true` — when true, a `mandatory: true`
 * input that resolves to no value at all (no override, no default) is a build-time error, since
 * the on-demand launcher's record form requires every mandatory input to have a value before it
 * can be saved. This check is independent of trigger input mapping (see
 * `playbook-inputs-mapper-transform.ts`), since the launcher is a distinct entry point where no
 * trigger mapper ever runs.
 *
 * `inputsConfig` (the raw, un-built `inputs: {...}` object from the playbook config, if available)
 * is used purely to anchor the missing-mandatory-value diagnostic to the user-authored
 * `Column({...})` call for that input, rather than the internal `sys_pd_process_input` SdkRecord —
 * mirroring how other diagnostics in this plugin anchor to a Fluent-authored shape. Falls back to
 * the record itself when unavailable.
 */
export async function buildLauncherInputRecords(options: {
    launcherInputsConfig: ObjectShape | undefined
    inputsConfig?: ObjectShape
    inputRecords: SdkRecord[]
    parentRecord: SdkRecord
    factory: Factory
    diagnostics: Diagnostics
    launcherInUse: boolean
}): Promise<SdkRecord[]> {
    const { launcherInputsConfig, inputsConfig, inputRecords, parentRecord, factory, diagnostics, launcherInUse } =
        options
    const records: SdkRecord[] = []
    const seenOrders = new Map<number, string>()

    for (const [i, inputRecord] of inputRecords.entries()) {
        const element = inputRecord.get('element')?.ifString()?.getValue()
        if (!element) {
            continue
        }

        const explicitShape = launcherInputsConfig?.get(element)
        const hasExplicit = explicitShape?.isDefined() && !explicitShape.isUndefined()
        const internalType = inputRecord.get('internal_type')?.ifString()?.getValue() ?? 'string'
        const defaultVal = inputRecord.get('default_value')?.ifString()?.getValue() ?? ''

        let resolvedValue: string | undefined
        if (hasExplicit) {
            if (internalType === 'reference') {
                const ref = toReference(explicitShape!)
                resolvedValue = typeof ref === 'string' ? ref : ref.getValue()
            } else {
                // launcherInputs for a non-reference input is typed as a plain string
                // (see PlaybookDefinition.ts), so a boolean/number literal like `foo: true`
                // can't actually reach here through normal authoring — TypeScript rejects it
                // at compile time. Anything that isn't a string (e.g. an array/object literal,
                // or a boolean/number forced past the type via @ts-expect-error) is a genuine
                // authoring mistake and gets a diagnostic instead of a silent empty value.
                const strVal = explicitShape!.ifString()?.getValue()
                if (strVal !== undefined) {
                    resolvedValue = strVal
                } else {
                    diagnostics.error(explicitShape!, `launcherInputs.${element} must be a string value.`)
                    resolvedValue = ''
                }
            }
        } else if (defaultVal !== '') {
            resolvedValue = defaultVal
        }

        if (resolvedValue === undefined) {
            if (launcherInUse && inputRecord.get('mandatory')?.ifBoolean()?.getValue() === true) {
                diagnostics.error(
                    inputsConfig?.get(element) ?? inputRecord,
                    `Required playbook input "${element}" has no value for the on-demand launcher. ` +
                        `Set launcherInputs.${element} or give the input a default value.`
                )
            }
            continue
        }

        const ownOrder = Number(inputRecord.get('order')?.toString()?.getValue() ?? 0)
        const resolvedOrder = ownOrder > 0 ? ownOrder : (i + 1) * 100

        const priorElement = seenOrders.get(resolvedOrder)
        if (priorElement) {
            diagnostics.error(
                inputRecord.get('order') ?? inputRecord,
                `Duplicate order ${resolvedOrder}: launcher inputs '${element}' and '${priorElement}' share order ${resolvedOrder}`
            )
        } else {
            seenOrders.set(resolvedOrder, element)
        }

        records.push(
            await factory.createRecord({
                source: hasExplicit ? explicitShape! : inputRecord,
                table: SYS_VARIABLE_VALUE_TABLE,
                properties: {
                    document: PLAYBOOK_TABLE,
                    document_key: parentRecord.getId().getValue(),
                    variable: inputRecord.getId().getValue(),
                    value: resolvedValue,
                    order: resolvedOrder,
                },
            })
        )
    }

    return records
}

/**
 * Build the `launcherInputs` object shape from `sys_variable_value` records anchored to
 * the playbook itself (toShape/XML → Fluent direction). Omits entries whose persisted
 * value equals the matching input's own `default_value` — those are the default-mirroring
 * case created automatically by `buildLauncherInputRecords`, and only explicit overrides
 * should be re-emitted.
 */
export function buildLauncherInputShapes(
    variableValueRecords: SdkRecord[],
    inputRecords: SdkRecord[]
): Record<string, Shape> {
    const result: Record<string, Shape> = {}

    const sorted = [...variableValueRecords].sort((a, b) => {
        const aOrder = Number(a.get('order')?.toString()?.getValue() ?? 0)
        const bOrder = Number(b.get('order')?.toString()?.getValue() ?? 0)
        return aOrder - bOrder
    })

    for (const varValueRecord of sorted) {
        const variableSysId = varValueRecord.get('variable')?.ifString()?.getValue()
        if (!variableSysId) {
            continue
        }

        const inputRecord = inputRecords.find((r) => r.getId().getValue() === variableSysId)
        if (!inputRecord) {
            continue
        }

        const element = inputRecord.get('element')?.ifString()?.getValue()
        if (!element) {
            continue
        }

        const defaultVal = inputRecord.get('default_value')?.ifString()?.getValue() ?? ''
        const value = varValueRecord.get('value')?.ifString()?.getValue() ?? ''

        if (value === defaultVal) {
            continue
        }

        result[element] = Shape.from(varValueRecord, value)
    }

    return result
}
