import {
    type Diagnostics,
    type Factory,
    type Shape,
    type Source,
    type ObjectShape,
    StringShape,
} from '@servicenow/sdk-build-core'
import { ArrowFunctionShape } from '@servicenow/sdk-build-plugins'
import { type PillContext, resolvePlaybookPill } from '../utils/playbook-pill-resolver'
import { containsDataPill } from '../utils/playbook-shapes'
import { parseArrowBodyEntries } from '../utils/arrow-body-parser'
import {
    LANE_PERMISSION_CONFIGS,
    LANE_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
    NOOP_PERMISSION_KEY,
    ON_DEMAND,
    type PermissionConfig,
    PLAYBOOK_PERMISSION_CONFIGS,
    PLAYBOOK_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
    RECORD_DRIVEN,
} from '../constants/permissions-constants'

// ============================================================================
// DeferredPermissionShape — lazy JSON assembly at serialization time
// ============================================================================

/** A resolved reference: either a pill `mapping` (lazy) or a sysId `id`. */
interface ResolvedRef {
    source: string
    /** Resolved pill shape (StringLiteralShape or DeferredPillShape); getValue() at serialization. */
    mapping?: StringShape
    /** Raw sysId string. */
    id?: string
}

/**
 * The permission field value, assembled lazily so activity-output pills (DeferredPillShape)
 * resolve their GUIDs at XML serialization time rather than during toRecord. Holds the
 * grouped {PERMISSION_KEY: [entries]} structure and stringifies it in getValue().
 */
export class DeferredPermissionShape extends StringShape {
    private readonly grouped: Map<string, ResolvedRef[]>

    constructor({ source, grouped }: { source: Source; grouped: Map<string, ResolvedRef[]> }) {
        super({ source })
        this.grouped = grouped
    }

    override getValue(): string {
        const out: Record<string, Array<Record<string, string>>> = {}
        for (const [key, refs] of this.grouped) {
            out[key] = refs.map(
                (r): Record<string, string> =>
                    r.mapping !== undefined
                        ? { source: r.source, mapping: r.mapping.getValue() }
                        : { source: r.source, id: r.id ?? '' }
            )
        }
        return JSON.stringify(out)
    }
}

// ============================================================================
// Helpers
// ============================================================================

function boolFlag(entry: ObjectShape, flag: string): boolean {
    return entry.get(flag)?.ifBoolean()?.getValue() ?? false
}

/** Human-readable list of the reference forms a kind accepts — for diagnostics. */
function acceptedForms(cfg: PermissionConfig): string {
    const forms: string[] = []
    if (cfg.allowPill) {
        forms.push('data pill')
    }
    if (cfg.allowSysId !== 'never') {
        forms.push('sysId string or record')
    }
    return forms.join(' or ')
}

/** Each element of a permissions array, narrowed to an ObjectShape (with a diagnostic otherwise). */
function permissionEntries(permsObject: ObjectShape, arrayField: string, diagnostics: Diagnostics): ObjectShape[] {
    const elements = permsObject.get(arrayField)?.ifArray()?.getElements() ?? []
    const result: ObjectShape[] = []
    for (const element of elements) {
        const entry = element.ifObject()?.asObject()
        if (entry) {
            result.push(entry)
        } else {
            diagnostics.error(element, `Each "${arrayField}" permission must be an object`)
        }
    }
    return result
}

/**
 * Parse every reference-kind array on the permissions object into its entry objects, keyed by
 * array field (e.g. 'users' → [entry, ...]). The view-gate check and serialization both need
 * these entries; parsing here once means each entry is validated (and any diagnostic emitted)
 * a single time.
 */
function parsePermissionEntries(
    permsObject: ObjectShape,
    permissionConfigs: PermissionConfig[],
    diagnostics: Diagnostics
): Map<string, ObjectShape[]> {
    const byField = new Map<string, ObjectShape[]>()
    for (const cfg of permissionConfigs) {
        byField.set(cfg.arrayField, permissionEntries(permsObject, cfg.arrayField, diagnostics))
    }
    return byField
}

/**
 * Resolve a single entry's reference into a `mapping` (pill) or `id` (sysId), enforcing
 * the kind's pill/sysId policy. Returns undefined (after emitting a diagnostic) on error.
 *
 * @param entry - One permission-set object (e.g. a single `users[]` element, with its
 *   reference field and boolean flags).
 * @param cfg - Reference-kind config: which field to read, the platform source token, and
 *   the pill/sysId policy for this kind.
 * @param pillContext - Context used to resolve a data-pill reference to its `{{...}}` mapping.
 * @param executionType - The playbook's executionType; gates whether a sysId is allowed for
 *   `nonRecordDriven` kinds (user/userGroup).
 * @param diagnostics - Sink for validation errors.
 * @returns The resolved reference plus a per-reference-kind uniqueness `identity`, or undefined on error.
 */
async function resolveReference(
    entry: ObjectShape,
    cfg: PermissionConfig,
    pillContext: PillContext,
    executionType: string | undefined,
    diagnostics: Diagnostics
): Promise<{ ref: ResolvedRef; identity: string } | undefined> {
    const refShape = entry.get(cfg.refField)
    if (!refShape || refShape.isUndefined()) {
        diagnostics.error(entry, `Permission set is missing required "${cfg.refField}"`)
        return undefined
    }

    if (containsDataPill(refShape)) {
        if (!cfg.allowPill) {
            diagnostics.error(
                refShape,
                `"${cfg.refField}" must be a sysId string, not a data pill "${refShape.getCode()}"`
            )
            return undefined
        }
        const resolved = await resolvePlaybookPill(refShape, pillContext)
        if (!(resolved instanceof StringShape)) {
            // resolvePlaybookPill already emitted a diagnostic for the unresolved pill
            return undefined
        }
        return { ref: { source: cfg.source, mapping: resolved }, identity: `pill:${refShape.getCode()}` }
    }

    const sysId = refShape.ifRecord()?.getId().getValue() ?? refShape.ifString()?.getValue()
    if (sysId === undefined) {
        diagnostics.error(refShape, `"${cfg.refField}" must be a ${acceptedForms(cfg)}`)
        return undefined
    }
    if (cfg.allowSysId === 'never') {
        diagnostics.error(refShape, `"${cfg.refField}" must be a data pill, not a sysId "${sysId}"`)
        return undefined
    }
    if (cfg.allowSysId === 'nonRecordDriven' && executionType === RECORD_DRIVEN) {
        diagnostics.error(
            refShape,
            `"${cfg.refField}" cannot be a sysId "${sysId}" when the playbook's executionType is "record_driven"; use a data pill instead`
        )
        return undefined
    }
    return { ref: { source: cfg.source, id: sysId }, identity: `id:${sysId}` }
}

/**
 * Playbook-only: `view` gates every other flag. Emits an error for any non-view flag set
 * on a permission set that does not also grant `view`.
 */
function validatePlaybookViewGate(entriesByField: Map<string, ObjectShape[]>, diagnostics: Diagnostics): void {
    const nonViewFlags = Object.keys(PLAYBOOK_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP).filter((flag) => flag !== 'view')
    for (const cfg of PLAYBOOK_PERMISSION_CONFIGS) {
        for (const entry of entriesByField.get(cfg.arrayField) ?? []) {
            if (boolFlag(entry, 'view')) {
                continue
            }
            for (const flag of nonViewFlags) {
                if (boolFlag(entry, flag)) {
                    diagnostics.error(
                        entry.get(flag) ?? entry,
                        `"${flag}" requires "view: true" in the same permission set`
                    )
                }
            }
        }
    }
}

// ============================================================================
// Core serialization
// ============================================================================

interface SerializeOptions {
    /** Permission entries parsed once per array field (e.g. 'users' → [entry, ...]). */
    entriesByField: Map<string, ObjectShape[]>
    permissionConfigs: PermissionConfig[]
    /** Fluent permission key → platform permission key for this scope (playbook or lane). */
    fluentToPlatformKeyMap: Record<string, string>
    pillContext: PillContext
    executionType?: string
    diagnostics: Diagnostics
}

/**
 * Invert each permission set into the grouped {PLATFORM_PERMISSION_KEY: [entries]} structure:
 * for every permission key the set grants, append its resolved reference to that key's list.
 * A reference that grants no permission is appended under NOOP so it is still preserved.
 * Enforces per-reference-kind uniqueness of the reference.
 */
async function serializePermissions(opts: SerializeOptions): Promise<Map<string, ResolvedRef[]>> {
    const { entriesByField, permissionConfigs, fluentToPlatformKeyMap, pillContext, executionType, diagnostics } = opts
    const grouped = new Map<string, ResolvedRef[]>()
    const pushTo = (key: string, ref: ResolvedRef) => {
        const list = grouped.get(key)
        if (list) {
            list.push(ref)
        } else {
            grouped.set(key, [ref])
        }
    }

    for (const cfg of permissionConfigs) {
        const seen = new Set<string>()
        for (const entry of entriesByField.get(cfg.arrayField) ?? []) {
            const resolved = await resolveReference(entry, cfg, pillContext, executionType, diagnostics)
            if (!resolved) {
                continue
            }
            // Strip the identity prefix to surface the offending value (sysId or pill code).
            const duplicateValue = resolved.identity.replace(/^(?:pill|id):/, '')
            if (seen.has(resolved.identity)) {
                diagnostics.error(
                    entry.get(cfg.refField) ?? entry,
                    `Duplicate "${cfg.refField}" "${duplicateValue}" in "${cfg.arrayField}"`
                )
                continue
            }
            seen.add(resolved.identity)

            let grantedAny = false
            for (const [fluentKey, platformKey] of Object.entries(fluentToPlatformKeyMap)) {
                if (boolFlag(entry, fluentKey)) {
                    pushTo(platformKey, resolved.ref)
                    grantedAny = true
                }
            }
            // A reference that grants nothing is still preserved under NOOP so it
            // round-trips (e.g. a playbook set with only `view: false`).
            if (!grantedAny) {
                pushTo(NOOP_PERMISSION_KEY, resolved.ref)
            }
        }
    }

    return grouped
}

// ============================================================================
// Public entry points
// ============================================================================

export const LAUNCH_REQUIRED_MESSAGE = 'At least one permission set must grant "launch" so the playbook can be launched'

/**
 * Build the playbook `permission` field value from the `permissions` callback (2nd-arg
 * dependentConfig). Returns undefined when no permissions are granted (so the `'{}'`
 * default applies).
 */
export async function buildPlaybookPermissions(
    permissionsShape: Shape | undefined,
    opts: {
        factory: Factory
        diagnostics: Diagnostics
        activityIds: Set<string>
        executionType: string
        /** The dependentConfig object `permissions` lives on — anchors the
         * launch-required diagnostic when `permissions` is omitted entirely. */
        dependentConfig: Shape
    }
): Promise<DeferredPermissionShape | undefined> {
    const isOnDemand = opts.executionType === ON_DEMAND
    if (!permissionsShape || permissionsShape.isUndefined()) {
        if (isOnDemand) {
            opts.diagnostics.error(opts.dependentConfig, LAUNCH_REQUIRED_MESSAGE)
        }
        return undefined
    }
    if (!(permissionsShape instanceof ArrowFunctionShape)) {
        opts.diagnostics.error(permissionsShape, 'permissions must be a callback, e.g. (params) => ({ users: [...] })')
        return undefined
    }
    const permsObject = parseArrowBodyEntries(permissionsShape).returnObj?.ifObject()?.asObject()
    if (!permsObject) {
        return undefined
    }
    const paramName = permissionsShape.getParameters()[0]?.getName()
    const pillContext: PillContext = {
        format: 'standard',
        factory: opts.factory,
        diagnostics: opts.diagnostics,
        playbookBodyParamsNames: paramName ? [paramName] : [],
        allowedSources: { paramsParentRecord: !isOnDemand, activityReference: true },
        activityIds: opts.activityIds,
    }

    const entriesByField = parsePermissionEntries(permsObject, PLAYBOOK_PERMISSION_CONFIGS, opts.diagnostics)
    validatePlaybookViewGate(entriesByField, opts.diagnostics)

    const grouped = await serializePermissions({
        entriesByField,
        permissionConfigs: PLAYBOOK_PERMISSION_CONFIGS,
        fluentToPlatformKeyMap: PLAYBOOK_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
        pillContext,
        executionType: opts.executionType,
        diagnostics: opts.diagnostics,
    })

    if (isOnDemand) {
        const launchKey = PLAYBOOK_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP.launch
        if (!grouped.has(launchKey)) {
            opts.diagnostics.error(permsObject, LAUNCH_REQUIRED_MESSAGE)
        }
    }

    return grouped.size > 0 ? new DeferredPermissionShape({ source: permissionsShape.getSource(), grouped }) : undefined
}

/**
 * Build the lane `permission` field value from a lane config's `permissions` object.
 * The pill context is supplied by the lane plugin (its lanes-callback param provides the
 * `params.parentRecord` binding and carries the activity-id registry). Lane flags are
 * independent — there is no view gate.
 */
export async function buildLanePermissions(
    permissionsShape: Shape | undefined,
    pillContext: PillContext
): Promise<DeferredPermissionShape | undefined> {
    if (!permissionsShape || permissionsShape.isUndefined()) {
        return undefined
    }
    const permsObject = permissionsShape.ifObject()?.asObject()
    if (!permsObject) {
        pillContext.diagnostics.error(permissionsShape, 'lane permissions must be an object, e.g. { users: [...] }')
        return undefined
    }
    const entriesByField = parsePermissionEntries(permsObject, LANE_PERMISSION_CONFIGS, pillContext.diagnostics)
    const grouped = await serializePermissions({
        entriesByField,
        permissionConfigs: LANE_PERMISSION_CONFIGS,
        fluentToPlatformKeyMap: LANE_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
        pillContext,
        diagnostics: pillContext.diagnostics,
    })
    return grouped.size > 0 ? new DeferredPermissionShape({ source: permsObject.getSource(), grouped }) : undefined
}
