import {
    ArrayShape,
    BooleanShape,
    CallExpressionShape,
    type Diagnostics,
    ObjectShape,
    type Product,
    Shape,
    type Source,
    StringLiteralShape,
} from '@servicenow/sdk-build-core'
import { ArrowFunctionShape, NowIdShape } from '@servicenow/sdk-build-plugins'
import {
    LANE_PERMISSION_CONFIGS,
    LANE_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
    LANE_REQUIRED_FLUENT_PERMISSION_KEYS,
    type PermissionConfig,
    PLAYBOOK_PERMISSION_CONFIGS,
    PLAYBOOK_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
    PLAYBOOK_REQUIRED_FLUENT_PERMISSION_KEYS,
} from '../constants/permissions-constants'
import { ACTIVITY_REF_CALLEE, DATAPILL_CALLEE } from '../constants/playbook-plugin-constants'
import { buildDataPillCall } from '../utils/playbook-pill-transformer'

// ============================================================================
// Reverse permission transform (XML → Fluent)
//
// The exact inverse of permissions-torecord.ts. The platform stores permissions
// as a grouped {PLATFORM_PERMISSION_KEY: [reference]} JSON; this module collects
// those entries into unique references (one per source + mapping/id), recording
// which permission keys each reference grants, and emits one Fluent permission-set
// object per reference into users/userGroups/roles/userCriteria(s).
// ============================================================================

/** Param name used for the reconstructed permissions/lanes callback (matches the pill resolver). */
export const PERMISSIONS_PARAM_NAME = 'params'

// ============================================================================
// RawExpressionShape — renders a verbatim expression for activityRef pills
// ============================================================================

/**
 * A Shape that renders a verbatim expression string. Codegen is `getCode()`-driven
 * (the committer calls `replaceWithText(shape.getCode())`), so this lets us emit a
 * `wfa.playbook.activityRef(Now.ID['x']).outputs.<field>` chain — whose base is a
 * function call — which neither PropertyAccessShape (identifier-only elements) nor
 * CallExpressionShape (string callee) can represent on its own.
 */
class RawExpressionShape extends Shape {
    private readonly code: string

    constructor({ source, code }: { source: Source; code: string }) {
        super({ source })
        this.code = code
    }

    override getCode(): string {
        return this.code
    }
}

// ============================================================================
// Types
// ============================================================================

/** One platform permission entry: a pill `mapping` or a sysId `id`, tagged by source. */
interface PermissionEntry {
    source: string
    mapping?: string
    id?: string
}

/** A single reference (user/group/role/criteria) and every platform permission key it grants. */
interface Reference {
    mapping?: string
    id?: string
    /** Platform permission keys (VIEW, LAUNCH, NOOP, ...) this reference is listed under. */
    platformKeys: Set<string>
}

/** Result of reconstructing a permissions object, with whether a parentRecord pill was used. */
export interface PermissionsToShapeResult {
    object: ObjectShape
    /** True when any reconstructed pill references `params.parentRecord` (callback needs `params`). */
    usesParentRecord: boolean
}

// ============================================================================
// Parsing
// ============================================================================

/**
 * Parse the platform `permission` field JSON into a {PLATFORM_PERMISSION_KEY: [entry]} map.
 * Returns undefined for the empty/default `'{}'` value or malformed JSON, warning via
 * `diagnostics` for every reason short of the empty/default case (so a genuinely malformed
 * field is surfaced rather than silently dropped).
 */
function parsePermissionJson(
    json: string | undefined,
    source: Product,
    diagnostics: Diagnostics
): Record<string, PermissionEntry[]> | undefined {
    if (!json || json === '{}') {
        return undefined
    }
    let parsed: unknown
    try {
        parsed = JSON.parse(json)
    } catch {
        diagnostics.warn(source, 'Permission field contains invalid JSON; permissions were not reconstructed')
        return undefined
    }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        diagnostics.warn(source, 'Permission field must be a JSON object; permissions were not reconstructed')
        return undefined
    }
    const out: Record<string, PermissionEntry[]> = {}
    for (const [platformKey, value] of Object.entries(parsed as Record<string, unknown>)) {
        if (!Array.isArray(value)) {
            diagnostics.warn(source, `Permission entries for "${platformKey}" must be an array; skipping`)
            continue
        }
        const entries = value.filter(
            (raw): raw is PermissionEntry =>
                !!raw && typeof raw === 'object' && typeof (raw as PermissionEntry).source === 'string'
        )
        if (entries.length < value.length) {
            diagnostics.warn(
                source,
                `Some permission entries for "${platformKey}" were missing a "source" field and were skipped`
            )
        }
        if (entries.length > 0) {
            out[platformKey] = entries
        }
    }
    return Object.keys(out).length > 0 ? out : undefined
}

// ============================================================================
// Pill reconstruction
// ============================================================================

/**
 * Reconstruct the Fluent reference shape from a permission `mapping` pill string.
 * A permission mapping is always a single full pill (`{{...}}`), and is only ever:
 * - `{{pd.inputRecord.<path>}}`      → `wfa.playbook.dataPill(params.parentRecord.<path>)`
 * - `{{act.<guid>.outputs.<field>}}` → `wfa.playbook.dataPill(wfa.playbook.activityRef(Now.ID['x']).outputs.<field>)`
 *
 * Any other / malformed mapping returns undefined so the caller skips the entry.
 */
function buildMappingShape(
    mapping: string,
    source: Product,
    activityGuidToNowId: Map<string, NowIdShape>,
    diagnostics: Diagnostics
): { shape: Shape; usesParentRecord: boolean } | undefined {
    const pill = mapping.match(/^\{\{(.+)\}\}$/)
    if (!pill?.[1]) {
        diagnostics.warn(
            source,
            `Permission mapping "${mapping}" is not a recognized data pill; skipping this reference`
        )
        return undefined
    }
    const content = pill[1]

    // parentRecord pill → params.parentRecord(.path)
    if (content.startsWith('pd.inputRecord')) {
        const path = content.slice('pd.inputRecord'.length)
        return {
            shape: buildDataPillCall(source, `${PERMISSIONS_PARAM_NAME}.parentRecord${path}`),
            usesParentRecord: true,
        }
    }

    // Activity pill → wfa.playbook.activityRef(Now.ID['x']).<path>
    if (content.startsWith('act.')) {
        const rest = content.slice('act.'.length)
        const dotIndex = rest.indexOf('.')
        if (dotIndex !== -1) {
            const guid = rest.slice(0, dotIndex)
            const path = rest.slice(dotIndex + 1)
            const nowId = activityGuidToNowId.get(guid) ?? new NowIdShape({ source, id: guid })
            const refCode = `${ACTIVITY_REF_CALLEE}(${nowId.getCode()}).${path}`
            return {
                shape: new CallExpressionShape({
                    source,
                    callee: DATAPILL_CALLEE,
                    args: [new RawExpressionShape({ source, code: refCode })],
                }),
                usesParentRecord: false,
            }
        }
        diagnostics.warn(source, `Permission mapping "${mapping}" is missing an output path; skipping this reference`)
        return undefined
    }

    diagnostics.warn(source, `Permission mapping "${mapping}" has an unrecognized source; skipping this reference`)
    return undefined
}

// ============================================================================
// Core reconstruction
// ============================================================================

/**
 * Collect the platform's {PLATFORM_PERMISSION_KEY: [entry]} JSON into unique references,
 * keyed by platform source token (USER, USER_ROLE, ...): entries with the same source +
 * mapping/id are merged into one Reference that records all the platform permission keys it
 * appears under. Preserves each reference's first-seen (declared) order.
 */
function collectReferencesBySource(
    grouped: Record<string, PermissionEntry[]>,
    permissionConfigs: PermissionConfig[],
    source: Product,
    diagnostics: Diagnostics
): Map<string, Reference[]> {
    // A reference is unique by its mapping pill or its sysId, within its source token.
    const uniqueBySource = new Map<string, Map<string, Reference>>()
    for (const cfg of permissionConfigs) {
        uniqueBySource.set(cfg.source, new Map())
    }

    // Warn once per unrecognized source token rather than once per entry.
    const unknownSourceTokensWarned = new Set<string>()

    for (const [platformKey, entries] of Object.entries(grouped)) {
        for (const entry of entries) {
            const references = uniqueBySource.get(entry.source)
            if (!references) {
                // source token isn't a known reference kind — skip rather than guess
                if (!unknownSourceTokensWarned.has(entry.source)) {
                    unknownSourceTokensWarned.add(entry.source)
                    diagnostics.warn(
                        source,
                        `Permission source "${entry.source}" is not a recognized reference kind; skipping its entries`
                    )
                }
                continue
            }
            const identity = entry.mapping !== undefined ? `mapping:${entry.mapping}` : `id:${entry.id ?? ''}`
            let reference = references.get(identity)
            if (!reference) {
                reference = { mapping: entry.mapping, id: entry.id, platformKeys: new Set() }
                references.set(identity, reference)
            }
            reference.platformKeys.add(platformKey)
        }
    }

    // Map iteration preserves insertion order, i.e. the references' declared order.
    const result = new Map<string, Reference[]>()
    for (const [sourceToken, references] of uniqueBySource) {
        result.set(sourceToken, [...references.values()])
    }
    return result
}

/**
 * Build one Fluent permission-set object for a single reference: its reference field
 * (a data-pill mapping or a sysId string) plus the permission keys it grants. Each Fluent
 * permission key the reference's platform keys cover is emitted as `true`, in canonical
 * (view-first) order; a required key that is not granted is emitted as `false` (so a
 * NOOP playbook reference becomes `view: false`). Returns undefined when the reference's
 * mapping pill is unrecognized, so the caller drops the set.
 */
function buildPermissionSet(
    reference: Reference,
    cfg: PermissionConfig,
    fluentToPlatformKeyMap: Record<string, string>,
    requiredFluentKeys: ReadonlySet<string>,
    source: Product,
    activityGuidToNowId: Map<string, NowIdShape>,
    diagnostics: Diagnostics
): { object: ObjectShape; usesParentRecord: boolean } | undefined {
    const properties: Record<string, Shape> = {}
    let usesParentRecord = false

    if (reference.mapping !== undefined) {
        const built = buildMappingShape(reference.mapping, source, activityGuidToNowId, diagnostics)
        if (!built) {
            return undefined
        }
        usesParentRecord = built.usesParentRecord
        properties[cfg.refField] = built.shape
    } else {
        properties[cfg.refField] = new StringLiteralShape({ source, literalText: reference.id ?? '' })
    }

    for (const [fluentKey, platformKey] of Object.entries(fluentToPlatformKeyMap)) {
        if (reference.platformKeys.has(platformKey)) {
            properties[fluentKey] = new BooleanShape({ source, value: true })
        } else if (requiredFluentKeys.has(fluentKey)) {
            properties[fluentKey] = new BooleanShape({ source, value: false })
        }
    }

    return { object: new ObjectShape({ source, properties }), usesParentRecord }
}

/**
 * Invert the grouped permission JSON into a Fluent permissions object, e.g.
 * `{ users: [{ user: ..., view: true }], roles: [{ role: 'sys-id', view: true }] }`.
 */
function buildPermissionsObject(
    json: string | undefined,
    permissionConfigs: PermissionConfig[],
    fluentToPlatformKeyMap: Record<string, string>,
    requiredFluentKeys: ReadonlySet<string>,
    source: Product,
    activityGuidToNowId: Map<string, NowIdShape>,
    diagnostics: Diagnostics
): PermissionsToShapeResult | undefined {
    const grouped = parsePermissionJson(json, source, diagnostics)
    if (!grouped) {
        return undefined
    }

    const referencesBySource = collectReferencesBySource(grouped, permissionConfigs, source, diagnostics)
    const properties: Record<string, Shape> = {}
    let usesParentRecord = false

    for (const cfg of permissionConfigs) {
        const permissionSets: Shape[] = []
        for (const reference of referencesBySource.get(cfg.source) ?? []) {
            const set = buildPermissionSet(
                reference,
                cfg,
                fluentToPlatformKeyMap,
                requiredFluentKeys,
                source,
                activityGuidToNowId,
                diagnostics
            )
            if (!set) {
                continue
            }
            usesParentRecord = usesParentRecord || set.usesParentRecord
            permissionSets.push(set.object)
        }
        if (permissionSets.length > 0) {
            properties[cfg.arrayField] = new ArrayShape({ source, elements: permissionSets })
        }
    }

    if (Object.keys(properties).length === 0) {
        return undefined
    }

    return { object: new ObjectShape({ source, properties }), usesParentRecord }
}

// ============================================================================
// Public entry points
// ============================================================================

/**
 * Reconstruct the playbook `permissions` callback (2nd-arg dependentConfig) from the
 * sys_pd_process_definition `permission` JSON. The permission sets are wrapped in a
 * `(params) => ({...})` arrow; the `params` parameter is declared only when a
 * `params.parentRecord` pill is present (an unused parameter is a lint/build error).
 * Returns undefined for the empty/default permission so no `permissions` key is emitted.
 */
export function buildPlaybookPermissionsToShape(
    json: string | undefined,
    source: Product,
    activityGuidToNowId: Map<string, NowIdShape>,
    diagnostics: Diagnostics
): ArrowFunctionShape | undefined {
    const result = buildPermissionsObject(
        json,
        PLAYBOOK_PERMISSION_CONFIGS,
        PLAYBOOK_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
        PLAYBOOK_REQUIRED_FLUENT_PERMISSION_KEYS,
        source,
        activityGuidToNowId,
        diagnostics
    )
    if (!result) {
        return undefined
    }
    return new ArrowFunctionShape({
        source,
        parameters: result.usesParentRecord ? [PERMISSIONS_PARAM_NAME] : [],
        returnValue: result.object,
        implicitReturn: true,
    })
}

/**
 * Reconstruct a lane's `permissions` object from the sys_pd_lane `permission` JSON.
 * Returns the plain object plus whether a `params.parentRecord` pill was used (so the
 * enclosing lanes callback can declare its `params` parameter). Returns undefined for
 * the empty/default permission.
 */
export function buildLanePermissionsToShape(
    json: string | undefined,
    source: Product,
    activityGuidToNowId: Map<string, NowIdShape>,
    diagnostics: Diagnostics
): PermissionsToShapeResult | undefined {
    return buildPermissionsObject(
        json,
        LANE_PERMISSION_CONFIGS,
        LANE_PERMISSION_KEY_FLUENT_TO_PLATFORM_MAP,
        LANE_REQUIRED_FLUENT_PERMISSION_KEYS,
        source,
        activityGuidToNowId,
        diagnostics
    )
}
