import { CallExpressionShape, ObjectShape, Plugin } from '@servicenow/sdk-build-core'
import { ArrowFunctionShape } from '@servicenow/sdk-build-plugins'
import { PLAYBOOK_API_NAME, VARIANT_COLORS } from '../constants/playbook-plugin-constants'
import { getNowIdKey } from '../utils/graph-utils'
import { collectPlaybookGraph } from '../utils/playbook-graph'
import { VariantShape } from '../utils/playbook-shapes'
import { isOptionalActivity } from '../utils/start-rule-resolver'

/**
 * Validates Variant calls and PlaybookDefinition-level variant constraints, and emits
 * diagnostics for invalid configurations.
 *
 * Per-variant checks (on `VariantShape`):
 * - Mirrors the platform's `PROCESS_VARIANT_MISSING_CONDITION` rule: both `label` and
 *   `condition` are mandatory on every variant, unconditionally (this rule isn't tied to
 *   the deferred-evaluation-point validations the platform also has — those are out of
 *   scope here, see the unsupported-features guide).
 * - `color`, if explicitly set, must be one of the 8 platform-supported values.
 *
 * Playbook-level checks (on the `PlaybookDefinition` call, since they need visibility into
 * the whole variants collection alongside sibling fields like `parentTable`/`lanes`):
 * - evaluateVariantChildrenAfter set without at least one variant declared
 * - Variants declared without a parentTable (error) or without a lane (warning) — the
 *   "Playbook variants" panel in Workflow Studio won't open without both.
 * - evaluateVariantChildrenAfter target-validity: must reference an activity (not a lane),
 *   must not be an optional (Run.Manually()) activity, and must not itself be gated behind
 *   a decision branch (Run.After(decision.branches.<id>)) — all three may never run and
 *   could leave the variant condition's evaluation point permanently unresolved.
 *
 * Note: This plugin returns { success: false } to indicate it is for diagnostics only
 * and does not create records.
 */
export const VariantDiagnosticsPlugin = Plugin.create({
    name: 'VariantDiagnosticsPlugin',
    noTelemetry: true,
    shapes: [
        {
            shape: VariantShape,
            fileTypes: ['fluent'],

            toRecord(variantShape, { diagnostics }) {
                const config = variantShape.getConfig()

                const labelShape = config.get('label')?.ifString()
                const labelValue = labelShape?.getValue()
                if (!labelValue || labelValue.trim() === '') {
                    diagnostics.error(labelShape ?? config.get('label') ?? config, 'Variant `label` is required.')
                }

                const conditionShape = config.get('condition')?.ifString()
                const conditionValue = conditionShape?.getValue()
                if (!conditionValue || conditionValue.trim() === '') {
                    diagnostics.error(
                        conditionShape ?? config.get('condition') ?? config,
                        'Variant `condition` is required.'
                    )
                }

                const colorShape = config.get('color')
                if (colorShape?.isDefined() && !colorShape.isUndefined()) {
                    const colorValue = colorShape.ifString()?.getValue()
                    if (colorValue === undefined || !(VARIANT_COLORS as readonly string[]).includes(colorValue)) {
                        const examples = VARIANT_COLORS.map((value) => `"${value}"`).join(', ')
                        diagnostics.error(colorShape, `Variant \`color\` must be one of: ${examples}.`)
                    }
                }

                // Diagnostics-only plugin — never creates records.
                return { success: false }
            },
        },
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],

            toRecord(callExpression, { diagnostics }) {
                if (callExpression.getCallee() !== PLAYBOOK_API_NAME) {
                    return { success: false }
                }

                const config = callExpression.getArgument(0)?.asObject()
                if (!config) {
                    return { success: false }
                }

                const parentTableVal = config.get('parentTable')?.ifString()?.getValue()

                const bodyArg = callExpression.getArgument(2)
                // `variants` is declared on the 2nd argument (PlaybookDependentConfig), alongside
                // `permissions`/`triggers` — not on the body (3rd argument) like `lanes`.
                const dependentConfigArg = callExpression.getArgument(1)
                const variantsArrow = dependentConfigArg?.asObject().get('variants')
                const variantsReturnValue = variantsArrow?.is(ArrowFunctionShape)
                    ? variantsArrow.as(ArrowFunctionShape).getReturnValue()
                    : undefined
                const variantCount = variantsReturnValue?.is(ObjectShape)
                    ? variantsReturnValue.as(ObjectShape).keys().length
                    : 0

                const lanesArrow = bodyArg?.asObject().get('lanes')
                const lanesArrowFn = lanesArrow?.is(ArrowFunctionShape) ? lanesArrow.as(ArrowFunctionShape) : undefined

                // --- Validate evaluateVariantChildrenAfter requires at least one variant ---
                // A deferred evaluation point only makes sense when there's actually a variant
                // hierarchy whose evaluation is being deferred.
                const evaluateVariantChildrenAfterShape = config.get('evaluateVariantChildrenAfter')
                if (
                    evaluateVariantChildrenAfterShape?.isDefined() &&
                    !evaluateVariantChildrenAfterShape.isUndefined()
                ) {
                    if (variantCount === 0) {
                        diagnostics.error(
                            evaluateVariantChildrenAfterShape,
                            'evaluateVariantChildrenAfter requires at least one variant to be defined.'
                        )
                    }

                    // --- Validate the evaluateVariantChildrenAfter target is a valid activity ---
                    const evaluateVariantChildrenAfterKey = getNowIdKey(evaluateVariantChildrenAfterShape)
                    const playbookGraph = lanesArrowFn ? collectPlaybookGraph(lanesArrowFn) : undefined
                    const targetNode = evaluateVariantChildrenAfterKey
                        ? playbookGraph?.nodes.get(evaluateVariantChildrenAfterKey)
                        : undefined

                    if (targetNode && targetNode.kind !== 'activity') {
                        const label =
                            targetNode.config.get('label')?.ifString()?.getValue() ?? evaluateVariantChildrenAfterKey
                        diagnostics.error(
                            evaluateVariantChildrenAfterShape,
                            `evaluateVariantChildrenAfter cannot target '${label}' because it is not an activity.`
                        )
                    } else if (
                        targetNode?.kind === 'activity' &&
                        isOptionalActivity(targetNode.config.get('startRule'))
                    ) {
                        const label =
                            targetNode.config.get('label')?.ifString()?.getValue() ?? evaluateVariantChildrenAfterKey
                        diagnostics.error(
                            evaluateVariantChildrenAfterShape,
                            `evaluateVariantChildrenAfter cannot target '${label}' because it is an optional activity — it may never run.`
                        )
                    }
                }

                // --- Require parentTable and at least one lane when variants are declared ---
                // The "Playbook variants" panel in Workflow Studio does not open unless the
                // playbook has both a parentTable and at least one lane. A missing parentTable
                // makes the variant records permanently unreachable in the UI, so it's an error;
                // a missing lane is recoverable (lanes can be added later), so it's a warning.
                if (variantCount > 0) {
                    if (!parentTableVal) {
                        diagnostics.error(
                            config,
                            'Playbook has variants but no parentTable set. The "Playbook variants" panel will not open in Workflow Studio without a parentTable.'
                        )
                    }

                    const lanesReturnValue = lanesArrowFn?.getReturnValue()
                    const laneCount = lanesReturnValue?.is(ObjectShape)
                        ? lanesReturnValue.as(ObjectShape).keys().length
                        : 0

                    if (laneCount === 0) {
                        diagnostics.warn(
                            config,
                            'Playbook has variants but no lanes declared. The "Playbook variants" panel will not open in Workflow Studio without at least one lane.'
                        )
                    }
                }

                // Don't create a record - this is diagnostics only.
                return { success: false }
            },
        },
    ],
})
