import { CallExpressionShape, type ObjectShape, PropertyAccessShape, type Shape } from '@servicenow/sdk-build-core'
import { ArrowFunctionShape, NowIdShape } from '@servicenow/sdk-build-plugins'
import {
    ACTIVITY_CALLEE_NAMES as ACTIVITY_CALLEES,
    LANE_CALLEE_NAMES as LANE_CALLEES,
} from '../constants/playbook-plugin-constants'
import { getConfigWithId, getNowIdKey } from './graph-utils'
import { parseArrowBodyEntries } from './arrow-body-parser'
import { isRunAfterCallee } from './start-rule-resolver'

/**
 * One node in the whole-playbook static graph: a lane or an activity (in-lane or stage-level),
 * as declared in the Fluent source — independent of the incremental record-building passes.
 * Built once per playbook by `collectPlaybookGraph`. Current consumers are the Go Back validator
 * (go-back-validator.ts) and Go Back's target-reference resolution (from activity-plugin.ts), plus
 * `computeAncestorIds` (graph-utils.ts), used by playbook-definition-plugin.ts's
 * `evaluateVariantChildrenAfter` target-validity checks. Nothing here is specific to any one of
 * those — this is a general-purpose static view of the playbook's lanes/activities, safe to extend
 * for other whole-playbook graph analyses as they come up.
 */
export interface PlaybookGraphNode {
    /** The Now.ID key from this node's own `$id` (e.g. 'lane_a', 'act_router'). */
    nowIdKey: string
    /** The Fluent variable/property name this node is bound to at its declaration site. */
    varName: string
    kind: 'lane' | 'activity'
    /** This node's config object — also used as the diagnostic anchor for validation messages. */
    config: ObjectShape
    /** Activities only: the 3rd call argument (the `inputs` object), if any. */
    inputs: ObjectShape | undefined
    /** Activities only: the Now.ID key of the containing lane, or undefined for stage-level activities. */
    laneNowIdKey: string | undefined
    /** Activities only: the activity definition's callee code, e.g. 'ActivityDefinitions.Core.Decision'. */
    activityDefCode: string | undefined
    /** Decision activities only: their `branches` input, parsed to `{ id, isElse }`. */
    branches: Array<{ id: string; isElse: boolean }> | undefined
    /** Now.ID keys this node's own `startRule` Run.After()'s directly (excluding branch-tagged args). */
    plainDeps: string[]
    /** Branch-tagged direct dependencies, e.g. from `Run.After(decision.branches.critical)`. */
    branchDeps: Array<{ decisionKey: string; branchId: string }>
    /** Global declaration order (lanes interleaved with their own nested activities, in source order). */
    declarationIndex: number
}

export interface PlaybookGraph {
    /** All nodes keyed by their own Now.ID key. */
    nodes: Map<string, PlaybookGraphNode>
    /**
     * All nodes keyed by their authoring-time reference path: `'varName'` for a top-level
     * lane/activity, `'laneVarName.activityVarName'` for an activity nested in a lane. Used to
     * resolve a raw Fluent value (an Identifier or a `laneVar.activityVar` PropertyAccessShape)
     * back to the node it refers to.
     */
    byPath: Map<string, PlaybookGraphNode>
}

function extractLaneParts(
    callExpr: CallExpressionShape
): { config: ObjectShape; activitiesArrow: ArrowFunctionShape | undefined } | undefined {
    const config = getConfigWithId(callExpr)
    if (!config) {
        return undefined
    }
    const arg0 = callExpr.getArgument(0)?.ifObject()
    const activitiesShape = arg0?.get('activities')
    const activitiesArrow = activitiesShape?.is(ArrowFunctionShape) ? activitiesShape.as(ArrowFunctionShape) : undefined
    return { config, activitiesArrow }
}

function extractActivityParts(
    callExpr: CallExpressionShape
): { config: ObjectShape; inputs: ObjectShape | undefined; activityDefCode: string } | undefined {
    const config = callExpr.getArgument(1)?.ifObject()
    if (!config) {
        return undefined
    }
    const inputs = callExpr.getArgument(2)?.ifObject()
    const activityDefCode = callExpr.getArgument(0, false).getCode()
    return { config, inputs, activityDefCode }
}

/** Resolve a call expression (a Lane()/Activity() call, however it was reached) to its own Now.ID key. */
function getNowIdKeyOfCallExpr(callExpr: CallExpressionShape): string | undefined {
    const callee = callExpr.getCallee()
    if (LANE_CALLEES.has(callee)) {
        const parts = extractLaneParts(callExpr)
        return parts ? getNowIdKey(parts.config.get('$id')) : undefined
    }
    if (ACTIVITY_CALLEES.has(callee)) {
        const parts = extractActivityParts(callExpr)
        return parts ? getNowIdKey(parts.config.get('$id')) : undefined
    }
    return undefined
}

function extractBranches(inputs: ObjectShape | undefined): Array<{ id: string; isElse: boolean }> | undefined {
    const branchesArr = inputs?.get('branches')?.ifArray()
    if (!branchesArr) {
        return undefined
    }
    return branchesArr.getElements().flatMap((el) => {
        const id = el.ifObject()?.get('id')?.ifString()?.getValue()
        return id ? [{ id, isElse: id === 'else' }] : []
    })
}

/**
 * Extracts this node's own direct `startRule` dependencies (a Run.After() call), split into
 * plain (activity/lane) deps and branch-tagged deps (Run.After(decision.branches.id)).
 * Mirrors resolveStartsAfterBranches's PropertyAccessShape handling (reference-resolver.ts) but
 * stays in Now.ID-key space — no GUIDs are needed for graph analysis.
 */
function extractStartRuleEdges(
    config: ObjectShape,
    variables: Map<string, CallExpressionShape>
): { plainDeps: string[]; branchDeps: Array<{ decisionKey: string; branchId: string }> } {
    const plainDeps: string[] = []
    const branchDeps: Array<{ decisionKey: string; branchId: string }> = []
    const startRuleShape = config.get('startRule')
    if (!startRuleShape.is(CallExpressionShape)) {
        return { plainDeps, branchDeps }
    }
    const runAfterCall = startRuleShape.as(CallExpressionShape)
    if (!isRunAfterCallee(runAfterCall.getCallee())) {
        return { plainDeps, branchDeps }
    }

    for (const arg of runAfterCall.getArguments(false)) {
        if (arg.is(PropertyAccessShape)) {
            const elements = arg.as(PropertyAccessShape).getElements()
            if (elements.length === 3 && elements[1]?.getName() === 'branches') {
                const decisionCallExpr = variables.get(elements[0]?.getName())
                const decisionKey = decisionCallExpr ? getNowIdKeyOfCallExpr(decisionCallExpr) : undefined
                if (decisionKey) {
                    branchDeps.push({ decisionKey, branchId: elements[2]?.getName() })
                }
            }
            continue
        }
        let callExpr: CallExpressionShape | undefined
        if (arg.is(CallExpressionShape)) {
            callExpr = arg.as(CallExpressionShape)
        } else if (arg.isIdentifier()) {
            callExpr = variables.get(arg.asIdentifier().getName())
        }
        const key = callExpr ? getNowIdKeyOfCallExpr(callExpr) : undefined
        if (key) {
            plainDeps.push(key)
        }
    }
    return { plainDeps, branchDeps }
}

/**
 * Builds the whole-playbook static graph from the raw `lanes` arrow function — independent of the
 * incremental record-building passes, so every lane/activity is visible regardless of declaration
 * order. Used by the Go Back validator/target-reference resolver and by `computeAncestorIds`.
 */
export function collectPlaybookGraph(lanesArrow: ArrowFunctionShape): PlaybookGraph {
    const nodes = new Map<string, PlaybookGraphNode>()
    const byPath = new Map<string, PlaybookGraphNode>()
    let declarationIndex = 0

    const { variables: topVariables, returnObj } = parseArrowBodyEntries(lanesArrow)
    if (!returnObj?.isObject()) {
        return { nodes, byPath }
    }

    for (const [varPath, value] of returnObj.asObject().entries()) {
        const resolved = value.isIdentifier() ? (topVariables.get(value.asIdentifier().getName()) ?? value) : value
        if (!resolved.is(CallExpressionShape)) {
            continue
        }
        const callExpr = resolved.as(CallExpressionShape)
        const callee = callExpr.getCallee()

        if (LANE_CALLEES.has(callee)) {
            const parts = extractLaneParts(callExpr)
            const nowIdKey = parts ? getNowIdKey(parts.config.get('$id')) : undefined
            if (!parts || !nowIdKey) {
                continue
            }
            const { plainDeps, branchDeps } = extractStartRuleEdges(parts.config, topVariables)
            const laneNode: PlaybookGraphNode = {
                nowIdKey,
                varName: varPath,
                kind: 'lane',
                config: parts.config,
                inputs: undefined,
                laneNowIdKey: undefined,
                activityDefCode: undefined,
                branches: undefined,
                plainDeps,
                branchDeps,
                declarationIndex: declarationIndex++,
            }
            nodes.set(nowIdKey, laneNode)
            byPath.set(varPath, laneNode)

            if (parts.activitiesArrow) {
                const { variables: laneVariables, returnObj: laneReturnObj } = parseArrowBodyEntries(
                    parts.activitiesArrow
                )
                if (laneReturnObj?.isObject()) {
                    for (const [actVarPath, actValue] of laneReturnObj.asObject().entries()) {
                        const actResolved = actValue.isIdentifier()
                            ? (laneVariables.get(actValue.asIdentifier().getName()) ?? actValue)
                            : actValue
                        if (!actResolved.is(CallExpressionShape)) {
                            continue
                        }
                        const actCallExpr = actResolved.as(CallExpressionShape)
                        if (!ACTIVITY_CALLEES.has(actCallExpr.getCallee())) {
                            continue
                        }
                        const actParts = extractActivityParts(actCallExpr)
                        const actKey = actParts ? getNowIdKey(actParts.config.get('$id')) : undefined
                        if (!actParts || !actKey) {
                            continue
                        }
                        const { plainDeps: actPlain, branchDeps: actBranch } = extractStartRuleEdges(
                            actParts.config,
                            laneVariables
                        )
                        const actNode: PlaybookGraphNode = {
                            nowIdKey: actKey,
                            varName: actVarPath,
                            kind: 'activity',
                            config: actParts.config,
                            inputs: actParts.inputs,
                            laneNowIdKey: nowIdKey,
                            activityDefCode: actParts.activityDefCode,
                            branches: extractBranches(actParts.inputs),
                            plainDeps: actPlain,
                            branchDeps: actBranch,
                            declarationIndex: declarationIndex++,
                        }
                        nodes.set(actKey, actNode)
                        byPath.set(`${varPath}.${actVarPath}`, actNode)
                    }
                }
            }
            continue
        }

        if (ACTIVITY_CALLEES.has(callee)) {
            const parts = extractActivityParts(callExpr)
            const nowIdKey = parts ? getNowIdKey(parts.config.get('$id')) : undefined
            if (!parts || !nowIdKey) {
                continue
            }
            const { plainDeps, branchDeps } = extractStartRuleEdges(parts.config, topVariables)
            const actNode: PlaybookGraphNode = {
                nowIdKey,
                varName: varPath,
                kind: 'activity',
                config: parts.config,
                inputs: parts.inputs,
                laneNowIdKey: undefined,
                activityDefCode: parts.activityDefCode,
                branches: extractBranches(parts.inputs),
                plainDeps,
                branchDeps,
                declarationIndex: declarationIndex++,
            }
            nodes.set(nowIdKey, actNode)
            byPath.set(varPath, actNode)
        }
    }

    return { nodes, byPath }
}

type EnclosingBranch = { decisionKey: string; branchId: string }

/**
 * Per-graph reverse indexes so the Go Back validator's per-node checks (`hasDependents`,
 * `getBranchMembers`, `hasParallelForwardConflict`) don't each re-scan every node in the graph.
 * Built once per graph (keyed by object identity — a `PlaybookGraph` is never mutated after
 * `collectPlaybookGraph` returns it, and each build produces its own graph instance) and reused
 * across every Go Back node validated against it.
 */
interface GraphAnalysis {
    /** nowIdKey -> nowIdKeys of nodes whose plainDeps directly reference it (its direct successors). */
    dependents: Map<string, string[]>
    /**
     * One entry per (decisionKey, branchId) pair, keyed by that pair joined as `${decisionKey}
     * ${branchId}` — e.g. the branch `retry` of decision `decision_a` becomes key `"decision_a
     * retry"`. Value: the nowIdKeys of the node(s) whose own `branchDeps` names that exact pair,
     * i.e. whose `startRule` is `Run.After(decision_a.branches.retry)` — the node(s) that are the
     * direct entry point into that branch.
     */
    branchEntries: Map<string, string[]>
    /**
     * Cache of `getEnclosingBranch`'s own return value, keyed by the same `nowIdKey` argument:
     * `enclosingBranchCache.get(k)` is exactly what `getEnclosingBranch(k, graph)` returns — the
     * (decisionKey, branchId) of the branch that directly encloses node `k`, or `null` if `k` isn't
     * inside a branch at all. Filled in lazily by `getEnclosingBranch` as nodes are visited, since
     * not every node's enclosing branch ends up being asked for. This is the memoization that
     * matters most: `getBranchMembers` below calls `getEnclosingBranch` on every node in the graph,
     * and `validateGoBackNode` calls `getBranchMembers` once per Go Back activity — so without this
     * cache, the same node's enclosing branch gets walked from scratch again on every one of those
     * per-Go-Back-activity passes.
     */
    enclosingBranchCache: Map<string, EnclosingBranch | null>
}

const graphAnalysisCache = new WeakMap<PlaybookGraph, GraphAnalysis>()

function getGraphAnalysis(graph: PlaybookGraph): GraphAnalysis {
    const cached = graphAnalysisCache.get(graph)
    if (cached) {
        return cached
    }
    const dependents = new Map<string, string[]>()
    const branchEntries = new Map<string, string[]>()
    for (const node of graph.nodes.values()) {
        for (const dep of node.plainDeps) {
            const list = dependents.get(dep)
            if (list) {
                list.push(node.nowIdKey)
            } else {
                dependents.set(dep, [node.nowIdKey])
            }
        }
        for (const { decisionKey, branchId } of node.branchDeps) {
            const branchKey = `${decisionKey} ${branchId}`
            const list = branchEntries.get(branchKey)
            if (list) {
                list.push(node.nowIdKey)
            } else {
                branchEntries.set(branchKey, [node.nowIdKey])
            }
        }
    }
    const analysis: GraphAnalysis = { dependents, branchEntries, enclosingBranchCache: new Map() }
    graphAnalysisCache.set(graph, analysis)
    return analysis
}

/**
 * Walks backward from `nowIdKey` through its own `startRule` chain until it crosses a branch-tagged
 * edge. Mirrors the platform's own `getEnclosingDecisionAndBranch` (go-back-picker-utils.js),
 * including its single-predecessor simplification: when a node has more than one direct dependency,
 * only the first is followed.
 *
 * Containment is deliberately NOT an edge: being inside a lane that itself starts after a branch
 * does not put an activity in that branch, so a stage whose first activity is a Go Back has no
 * enclosing branch (matching `buildPredecessorMap`, which only walks activity dependencies).
 *
 * Memoized per graph: every node visited along a given walk shares the same result (the walk only
 * stops at a branch tag or a dead end), so each is cached once it's resolved. See
 * `GraphAnalysis.enclosingBranchCache` for why this matters — this same node gets asked for
 * repeatedly across the validator's run, not just once.
 */
export function getEnclosingBranch(nowIdKey: string, graph: PlaybookGraph): EnclosingBranch | null {
    const { enclosingBranchCache: cache } = getGraphAnalysis(graph)
    const path: string[] = []
    let current: PlaybookGraphNode | undefined = graph.nodes.get(nowIdKey)
    const visited = new Set<string>()
    let result: EnclosingBranch | null = null
    while (current && !visited.has(current.nowIdKey)) {
        if (cache.has(current.nowIdKey)) {
            result = cache.get(current.nowIdKey)!
            break
        }
        visited.add(current.nowIdKey)
        path.push(current.nowIdKey)
        if (current.branchDeps.length > 0) {
            const { decisionKey, branchId } = current.branchDeps[0]!
            result = { decisionKey, branchId }
            break
        }
        if (current.plainDeps.length === 0) {
            break
        }
        // multiple plainDeps: only plainDeps[0] is followed, same as the platform
        current = graph.nodes.get(current.plainDeps[0]!)
    }
    for (const key of path) {
        cache.set(key, result)
    }
    return result
}

/**
 * Declaration-order approximation of "activities/lanes that must have already run by the time
 * `decisionKey` is reached" — the same approximation `validateDecision`'s own "conditions must
 * reference prior activities" check already relies on (nowIdKeyToGuid built incrementally in
 * declaration order), not full graph-reachability.
 */
export function getValidPrecedingKeys(
    decisionKey: string,
    wantKind: 'activity' | 'lane',
    graph: PlaybookGraph
): Set<string> {
    const decision = graph.nodes.get(decisionKey)
    const result = new Set<string>()
    if (!decision) {
        return result
    }
    for (const node of graph.nodes.values()) {
        if (node.kind === wantKind && node.declarationIndex < decision.declarationIndex) {
            result.add(node.nowIdKey)
        }
    }
    return result
}

/** True when any node's `plainDeps` directly references `nowIdKey` (i.e. it has a successor). */
export function hasDependents(nowIdKey: string, graph: PlaybookGraph): boolean {
    return (getGraphAnalysis(graph).dependents.get(nowIdKey)?.length ?? 0) > 0
}

/** Groups every node by the (decisionKey, branchId) that directly encloses it. */
export function getBranchMembers(decisionKey: string, graph: PlaybookGraph): Map<string, string[]> {
    const members = new Map<string, string[]>()
    for (const node of graph.nodes.values()) {
        const enclosing = getEnclosingBranch(node.nowIdKey, graph)
        if (enclosing && enclosing.decisionKey === decisionKey) {
            const list = members.get(enclosing.branchId) ?? []
            list.push(node.nowIdKey)
            members.set(enclosing.branchId, list)
        }
    }
    return members
}

/**
 * True when, within the direct enclosing branch of `nowIdKey`, there is a parallel/forked path:
 * either the enclosing decision sends more than one real node directly into that branch, or some
 * node between the branch start and `nowIdKey` forks into more than one dependent. Mirrors
 * `hasParallelInEnclosingChain` (go-back-picker-utils.js). Callers should only call this when the
 * direct enclosing decision is match_first.
 */
export function hasParallelForwardConflict(nowIdKey: string, graph: PlaybookGraph): boolean {
    const enclosing = getEnclosingBranch(nowIdKey, graph)
    if (!enclosing) {
        return false
    }

    const analysis = getGraphAnalysis(graph)
    const directEntries = analysis.branchEntries.get(`${enclosing.decisionKey} ${enclosing.branchId}`) ?? []
    if (directEntries.length > 1) {
        return true
    }

    let current = graph.nodes.get(nowIdKey)
    const visited = new Set<string>()
    while (current && !visited.has(current.nowIdKey)) {
        visited.add(current.nowIdKey)
        // Check this node's own fan-out BEFORE deciding whether to stop at it. The branch-entry
        // node (the one whose own startRule references decision.branches.id, i.e. it carries
        // branchDeps) is a node like any other — it can itself fork into more than one dependent —
        // so its fan-out must be checked here too, not skipped by breaking first.
        const dependents = analysis.dependents.get(current.nowIdKey) ?? []
        if (dependents.length > 1) {
            return true
        }
        if (current.branchDeps.length > 0 || current.plainDeps.length === 0) {
            break
        }
        current = graph.nodes.get(current.plainDeps[0]!)
    }
    return false
}

/**
 * Resolves a raw Fluent input value — an Identifier (`someLane`, or a same-lane sibling
 * activity when `fromNode` is provided), a cross-lane dot-walk (`someLane.someActivity`), a
 * Now.ID key (NowIdShape, e.g. `Now.ID['target']`), or a bare unassigned Lane()/Activity()
 * call — to the graph node's Now ID key. Returns undefined for anything else (including
 * `wfa.playbook.activityRef(...)`, data pills, or literal strings — not supported as targets).
 *
 * **Caller contract — non-resolving fetch required:** `shape` must be obtained via a
 * *non-resolving* fetch (e.g. `inputs.get(fieldName, false)`), never the default resolving
 * `ObjectShape.get(key)`. The default fetch auto-resolves a `laneVar.activityVar`
 * `PropertyAccessShape` into an `UnresolvedShape` before this function ever sees it, silently
 * breaking cross-lane dot-walk resolution. This mirrors the same non-resolving-fetch pattern
 * `reference-resolver.ts` already uses for `Run.After()` args — this is a precondition on the
 * caller, not something this function can enforce or work around internally.
 *
 * @param fromNode The `PlaybookGraphNode` that owns `shape` (e.g. the Go Back activity itself, for
 *   resolving its `activity` target input). When provided and `fromNode` is nested in a lane, a
 *   bare Identifier is first tried as a same-lane sibling (`laneVar.identifierName` in `byPath`) —
 *   the pattern used to reference another activity declared in the SAME lane's `activities` arrow
 *   (e.g. `go_back_to_target_activity: setup`) — before falling back to the top-level
 *   `byPath.get(identifierName)` lookup. Without `fromNode` (or when it has no `laneNowIdKey`),
 *   only the top-level lookup is tried, so same-lane siblings cannot resolve.
 */
export function resolveReferenceToNowIdKey(
    shape: Shape,
    graph: PlaybookGraph,
    fromNode?: PlaybookGraphNode
): string | undefined {
    if (shape.is(NowIdShape)) {
        // A Now.ID key already IS the graph's canonical node key
        return String(shape.as(NowIdShape).getValue())
    }
    if (shape.is(PropertyAccessShape)) {
        const elements = shape.as(PropertyAccessShape).getElements()
        if (elements.length === 2) {
            return graph.byPath.get(`${elements[0]?.getName()}.${elements[1]?.getName()}`)?.nowIdKey
        }
        return undefined
    }
    if (shape.isIdentifier()) {
        const identifierName = shape.asIdentifier().getName()
        if (fromNode?.laneNowIdKey) {
            const laneVarName = graph.nodes.get(fromNode.laneNowIdKey)?.varName
            const sameLaneMatch = laneVarName ? graph.byPath.get(`${laneVarName}.${identifierName}`) : undefined
            if (sameLaneMatch) {
                return sameLaneMatch.nowIdKey
            }
        }
        return graph.byPath.get(identifierName)?.nowIdKey
    }
    if (shape.is(CallExpressionShape)) {
        return getNowIdKeyOfCallExpr(shape.as(CallExpressionShape))
    }
    return undefined
}
