import { ArrayShape, BooleanShape, ObjectShape, Shape, type Record as SdkRecord } from '@servicenow/sdk-build-core'
import { NowAttachShape } from '@servicenow/sdk-build-plugins'

export const ATTACHMENT_TABLE = 'sys_attachment'
export const ATTACHMENT_DOC_TABLE = 'sys_attachment_doc'

export type PreservedAttachmentData = {
    fileName: string
    contentType: string
    imageWidth: string
    imageHeight: string
    hash: string
    chunkSizeBytes: string
    compressed: boolean
    sizeBytes: string
    sizeCompressed: string
    data: string[]
}

/**
 * Finds the (at most one, per the Playbook Designer's single-file-upload constraint) existing
 * attachment on a process definition record. Project.getAttachmentsForFields (core SDK) already
 * merges a NowAttachShape onto any incoming record that has a matching sys_attachment (via
 * table_sys_id) before any plugin runs, keyed by the attachment's real file_name - so we read it
 * back here instead of re-deriving it from the raw sys_attachment/sys_attachment_doc descendants
 * ourselves.
 */
export function findProcessDefinitionAttachment(
    record: SdkRecord
): { fileName: string; shape: NowAttachShape } | undefined {
    for (const [fileName, shape] of record.entries()) {
        if (shape.is(NowAttachShape)) {
            return { fileName, shape }
        }
    }

    return undefined
}

/**
 * ObjectShape's default equals() isn't a deep enough comparison to notice when a *nested*
 * property (here, the chunked `data` array) changes between transforms - the same failure mode
 * transform-utils.ts's FreshTemplateValueShape works around for TemplateValueShape. We always
 * rebuild this shape fresh from the current NowAttachShape, so there's nothing to gain from
 * letting the framework "preserve unchanged" it: bypass equals() entirely so a replaced or
 * removed attachment is never left showing stale bytes.
 */
class FreshObjectShape extends ObjectShape {
    override equals(): boolean {
        return false
    }
}

/**
 * Builds the literal `preservedAttachment` object embedded in the generated `PlaybookDefinition()`
 * call's dependent config, from the merged NowAttachShape's own base attachment properties.
 */
export function buildPreservedAttachmentShape(source: Shape, fileName: string, shape: NowAttachShape): ObjectShape {
    const props = shape.getBaseAttachmentProperties()

    return new FreshObjectShape({
        source,
        properties: {
            fileName: Shape.from(source, fileName),
            contentType: Shape.from(source, props.content_type ?? ''),
            imageWidth: Shape.from(source, props.image_width != null ? String(props.image_width) : ''),
            imageHeight: Shape.from(source, props.image_height != null ? String(props.image_height) : ''),
            hash: Shape.from(source, props.hash),
            chunkSizeBytes: Shape.from(source, String(props.chunk_size_bytes)),
            compressed: new BooleanShape({ source, value: props.compressed }),
            sizeBytes: Shape.from(source, String(props.size_bytes)),
            sizeCompressed: Shape.from(source, String(props.size_compressed)),
            data: new ArrayShape({ source, elements: props.data }),
        },
    })
}

/**
 * Reads the `preservedAttachment` config back off a parsed `PlaybookDefinition()` call's
 * dependent config (2nd argument), if present.
 */
export function readPreservedAttachmentConfig(
    dependentConfig: ObjectShape | undefined
): PreservedAttachmentData | undefined {
    const shape = dependentConfig?.get('preservedAttachment')?.ifObject()?.asObject()
    if (!shape) {
        return undefined
    }

    const dataElements = shape.get('data')?.ifArray()?.getElements() ?? []

    return {
        fileName: shape.get('fileName')?.ifString()?.getValue() ?? '',
        contentType: shape.get('contentType')?.ifString()?.getValue() ?? '',
        imageWidth: shape.get('imageWidth')?.ifString()?.getValue() ?? '',
        imageHeight: shape.get('imageHeight')?.ifString()?.getValue() ?? '',
        hash: shape.get('hash')?.ifString()?.getValue() ?? '',
        chunkSizeBytes: shape.get('chunkSizeBytes')?.ifString()?.getValue() ?? '',
        compressed: shape.get('compressed')?.ifBoolean()?.getValue() ?? false,
        sizeBytes: shape.get('sizeBytes')?.ifString()?.getValue() ?? '',
        sizeCompressed: shape.get('sizeCompressed')?.ifString()?.getValue() ?? '',
        data: dataElements.map((element) => element.ifString()?.getValue() ?? ''),
    }
}

/**
 * Rebuilds a NowAttachShape from a preserved attachment's config, for reconstructing the
 * sys_attachment/sys_attachment_doc records via its own createAssociatedRecords - never rendered
 * into Fluent source as a `Now.attach()` call, just used as a data holder/record builder.
 */
export function buildNowAttachShape(source: Shape, preserved: PreservedAttachmentData): NowAttachShape {
    return new NowAttachShape({
        source,
        path: preserved.fileName,
        baseProperties: {
            average_image_color: '',
            chunk_size_bytes: preserved.chunkSizeBytes,
            compressed: preserved.compressed,
            content_type: preserved.contentType,
            hash: preserved.hash,
            image_height: preserved.imageHeight,
            image_width: preserved.imageWidth,
            size_bytes: preserved.sizeBytes,
            size_compressed: preserved.sizeCompressed,
            data: preserved.data,
        },
    })
}
