import { ArrayShape, CallExpressionShape, ObjectShape, Plugin } from '@servicenow/sdk-build-core'
import { ArrowFunctionShape } from '@servicenow/sdk-build-plugins'
import { ON_DEMAND } from '../constants/permissions-constants'
import {
    getPlaybookProcessTypeSysId,
    PLAYBOOK_API_NAME,
    PLAYBOOK_DEFAULTS,
    PLAYBOOK_KNOWN_PROCESS_TYPE_NAMES,
    isPlaybookProcessTypeSysId,
    PARENT_RECORD_MAPPER_KEY,
} from '../constants/playbook-plugin-constants'
import { collectPlaybookGraph } from '../utils/playbook-graph'
import { validateGoBackActivities } from '../utils/go-back-validator'
import { getNowIdKey } from '../utils/graph-utils'
import { collectBodyActivities } from '../utils/playbook-definition-utils'
import { getFactoryCallConfig } from '../utils/playbook-shapes'
import { VariantDiagnosticsPlugin } from './variant-diagnostics-plugin'

const MAX_TRIGGER_COUNT = 10

/**
 * Validates PlaybookDefinition calls and emits diagnostics for invalid configurations.
 *
 * This plugin runs validation checks on PlaybookDefinition calls and reports errors for:
 * - Setting processType to a non-name value (for example a sys_id or Now.ID reference)
 * - Empty parentTable value
 * - Setting any launcher field (launcherTitle, launcherDescription, etc.) without parentTable
 * - launcherInputs set without inputs declared, or with a key that doesn't match a declared input
 * - Missing parentRecord on triggers whose table differs from parentTable
 * - Exceeding the maximum allowed number of triggers per playbook (10)
 * - executionType 'on_demand' constraints (mirrors type-level restrictions in
 *   PlaybookDefinition.ts that JS callers, `as any`, or spread-from-untyped objects can
 *   bypass): `triggers` being set at all, a `parentTable`, and `allowAsNested: true` outside
 *   of `executionType: 'on_demand'`.
 * - Go Back activity structural/target rules (see go-back-validator.ts)
 * - publicAccess set without parentTable, with an activity whose definition is not
 *   marked publicAccess: true, or with an AI agent activity
 *
 * Variant-specific checks (evaluateVariantChildrenAfter, variants requiring a parentTable/lane,
 * variant label/condition/color) live in `variant-diagnostics-plugin.ts` instead.
 *
 * Note: This plugin returns { success: false } to indicate it is for diagnostics only
 * and does not create records.
 */
export const PlaybookDiagnosticsPlugin = Plugin.create({
    name: 'PlaybookDiagnosticsPlugin',
    noTelemetry: true,
    shapes: [
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],

            async toRecord(callExpression, { diagnostics, transform }) {
                if (callExpression.getCallee() !== PLAYBOOK_API_NAME) {
                    return { success: false }
                }

                // Explicit, not a duplicate call: PlaybookDefinitionPlugin runs next and returns
                // success for this shape, which stops the dispatch loop before it ever reaches
                // VariantDiagnosticsPlugin's own CallExpressionShape entry. Same as ActivityPlugin's
                // explicit call to ActivityDiagnosticsPlugin.
                await transform.toRecord(callExpression, VariantDiagnosticsPlugin)

                const config = callExpression.getArgument(0)?.asObject()
                if (!config) {
                    return { success: false }
                }

                // --- Validate processType ---
                // processType must be one of the SDK-supported mapped names.
                // Do not add arbitrary/custom playbook types in Fluent without explicit
                // SDK support work: each supported type may require its own feature-flag
                // modeling, diagnostics, and transform/build handling.
                const processTypeShape = config.get('processType')
                const processTypeExamples = PLAYBOOK_KNOWN_PROCESS_TYPE_NAMES.map((value) => `"${value}"`).join(', ')

                // isDefined() checks the key is present; isUndefined() checks the value is
                // explicitly `undefined`. Both are needed: isDefined() alone would match a
                // key with value `undefined`, and isUndefined() alone would not confirm presence.
                if (processTypeShape?.isDefined() && !processTypeShape.isUndefined()) {
                    const processTypeValue = processTypeShape.ifString()?.getValue()
                    if (processTypeValue === undefined) {
                        diagnostics.error(
                            processTypeShape,
                            `processType must be a name string. Use a process type name such as ${processTypeExamples}.`
                        )
                    } else if (processTypeValue.trim() === '') {
                        diagnostics.error(
                            processTypeShape,
                            `processType must be a non-empty name string. Use a process type name such as ${processTypeExamples}.`
                        )
                    } else if (isPlaybookProcessTypeSysId(processTypeValue)) {
                        diagnostics.error(
                            processTypeShape,
                            `processType must be a name, not a sys_id. Use a process type name such as ${processTypeExamples}.`
                        )
                    } else if (!getPlaybookProcessTypeSysId(processTypeValue)) {
                        diagnostics.error(
                            processTypeShape,
                            `Unsupported processType "${processTypeValue}". We do not have that process type defined in the SDK mapping. Supported values: ${processTypeExamples}.`
                        )
                    }
                }

                // Future: add type-specific diagnostics here as features are implemented.
                // New playbook types are not plug-and-play: they may support a different
                // set of capabilities (for example publicAccess, decisions, stages,
                // or optional activities), and each supported type needs explicit
                // validation before we allow it in Fluent.

                // --- Resolve executionType up front ---
                // Several checks below (parentTable, access, allowAsNested, triggers) are
                // conditioned on this. Mirrors the same default resolution as
                // playbook-definition-plugin.ts and playbook-config-transform.ts.
                const executionType =
                    config.get('executionType')?.ifString()?.getValue() ?? PLAYBOOK_DEFAULTS.EXECUTION_TYPE
                const isOnDemand = executionType === ON_DEMAND

                // --- Validate parentTable ---
                const parentTableShape = config.get('parentTable')
                const parentTableVal = parentTableShape?.ifString()?.getValue()
                if (parentTableShape && parentTableVal === '') {
                    diagnostics.error(parentTableShape, 'parentTable must be a valid table name.')
                }

                // On-demand playbooks have no triggering record, so parentTable cannot be set.
                // PlaybookDefinitionFunction's TS override types this as `never`, but JS callers
                // (or `as any` in TS) bypass that — mirror the constraint here.
                if (isOnDemand && parentTableShape?.isDefined() && !parentTableShape.isUndefined()) {
                    diagnostics.error(parentTableShape, "parentTable cannot be set when executionType is 'on_demand'.")
                }

                // --- Validate allowAsNested ---
                // Nested-playbook usage is only supported for on-demand playbooks. The TS
                // override types this as `false` outside of 'on_demand', but JS callers (or
                // `as any`) bypass that — mirror the constraint here.
                const allowAsNestedShape = config.get('allowAsNested')
                const allowAsNestedVal = allowAsNestedShape?.ifBoolean()?.getValue()
                if (!isOnDemand && allowAsNestedVal === true) {
                    diagnostics.error(
                        allowAsNestedShape,
                        "allowAsNested can only be true when executionType is 'on_demand'."
                    )
                }

                // --- Validate publicAccess ---
                // Enforces the same constraints Playbook Designer places on public
                // playbooks, so the failure surfaces at build time instead of later.
                const publicAccessShape = config.get('publicAccess')
                if (publicAccessShape?.ifBoolean()?.getValue() === true) {
                    // A public playbook must be tied to a record. On-demand playbooks
                    // cannot have a parentTable at all, so report that directly rather
                    // than telling the author to set a field they cannot set.
                    if (isOnDemand) {
                        diagnostics.error(
                            publicAccessShape,
                            "publicAccess cannot be set when executionType is 'on_demand'. " +
                                'On-demand playbooks have no parent record, so they can never be public.'
                        )
                    } else if (!parentTableVal) {
                        diagnostics.error(
                            publicAccessShape,
                            'publicAccess requires parentTable to be set. A public playbook must be tied to a record.'
                        )
                    }

                    // Every activity's definition must allow public use. The type
                    // system already rejects this on the body entry holding the activity; this
                    // names the exact activity and definition, and is the backstop for
                    // JS/`any`/spread-from-untyped callers.
                    for (const { definition, label, config: activityConfig } of collectBodyActivities(
                        callExpression.getArgument(2)
                    )) {
                        // A public playbook runs without a session, so it cannot contain AI agent
                        // activities. Some public-eligible definitions (the record forms) do support
                        // AI agents, so this combination is reachable and worth catching here.
                        const enableAiAgentShape = activityConfig?.get('enableAiAgent')
                        if (enableAiAgentShape?.ifBoolean()?.getValue() === true) {
                            diagnostics.error(
                                enableAiAgentShape,
                                `Activity "${label}" sets enableAiAgent: true, which is not allowed in public playbooks. ` +
                                    'Public playbooks cannot contain AI agent activities.'
                            )
                        }

                        // An unresolvable definition (e.g. imported from a package the compiler
                        // cannot follow) is left to the platform to reject at activation —
                        // the same way dependent-field validation skips what it cannot resolve.
                        const definitionConfig = getFactoryCallConfig(definition)
                        if (
                            !definitionConfig ||
                            definitionConfig.get('publicAccess')?.ifBoolean()?.getValue() === true
                        ) {
                            continue
                        }
                        const definitionLabel =
                            definitionConfig.get('label')?.ifString()?.getValue() ?? definition.getCode()
                        diagnostics.error(
                            definition,
                            `Activity "${label}" uses activity definition "${definitionLabel}", which is not allowed in public playbooks. ` +
                                'Public playbooks can only contain activities whose definition sets publicAccess: true.'
                        )
                    }
                }

                // --- Validate launcher fields require parentTable ---
                // launcherTitle/launcherDescription are just launcher display text and work
                // fine without a parent table (e.g. standalone playbooks). Only the
                // record-form-related fields need parentTable, since they operate on a record
                // of that table.
                const launcherFieldsRequiringParentTable = [
                    'launcherShowRecordForm',
                    'launcherRecordFormView',
                    'launcherTemplateFields',
                ] as const

                if (!parentTableVal) {
                    for (const field of launcherFieldsRequiringParentTable) {
                        const fieldShape = config.get(field)
                        if (fieldShape?.isDefined() && !fieldShape.isUndefined()) {
                            const strVal = fieldShape.ifString()?.getValue()
                            const boolVal = fieldShape.ifBoolean()?.getValue()
                            if ((strVal !== undefined && strVal !== '') || boolVal === true) {
                                diagnostics.error(
                                    fieldShape,
                                    isOnDemand
                                        ? `${field} cannot be set when executionType is 'on_demand'.`
                                        : `${field} requires parentTable to be set. Set parentTable to the table this playbook operates on.`
                                )
                            }
                        }
                    }
                }

                // --- Validate launcherRecordFormView ---
                // Only valid when launcherShowRecordForm is true
                const showRecordForm = config.get('launcherShowRecordForm')?.ifBoolean()?.getValue() ?? false
                if (!showRecordForm) {
                    const formViewShape = config.get('launcherRecordFormView')
                    if (formViewShape?.isDefined() && !formViewShape.isUndefined()) {
                        const formViewVal = formViewShape.ifString()?.getValue()
                        if (formViewVal !== undefined && formViewVal !== '') {
                            diagnostics.error(
                                formViewShape,
                                'launcherRecordFormView can only be set when launcherShowRecordForm is true.'
                            )
                        }
                    }

                    // --- Validate launcherTemplateFields ---
                    // Only valid when launcherShowRecordForm is true
                    const templateFieldsShape = config.get('launcherTemplateFields')
                    if (templateFieldsShape?.isDefined() && !templateFieldsShape.isUndefined()) {
                        const tfVal = templateFieldsShape.ifString()?.getValue()
                        if (tfVal !== undefined && tfVal !== '') {
                            diagnostics.error(
                                templateFieldsShape,
                                'launcherTemplateFields can only be set when launcherShowRecordForm is true.'
                            )
                        }
                    }
                }

                // --- Validate launcherInputs ---
                // Requires inputs to be declared, and each key must match a declared input name.
                const launcherInputsShape = config.get('launcherInputs')
                if (launcherInputsShape?.isDefined() && !launcherInputsShape.isUndefined()) {
                    const launcherInputsConfig = launcherInputsShape.ifObject()?.asObject()
                    if (launcherInputsConfig) {
                        const inputsConfig = config.get('inputs')?.ifObject()?.asObject()
                        if (!inputsConfig) {
                            diagnostics.error(launcherInputsConfig, 'launcherInputs requires inputs to be declared.')
                        } else {
                            const declaredInputKeys = new Set(inputsConfig.keys())
                            for (const [key, valueShape] of launcherInputsConfig.entries()) {
                                if (!declaredInputKeys.has(key)) {
                                    diagnostics.error(
                                        valueShape,
                                        `launcherInputs key "${key}" does not match a declared input.`
                                    )
                                }
                            }
                        }
                    }
                }

                // Triggers live in the 2nd-arg object. Extract the triggers array.
                const triggersObject = callExpression.getArgument(1)
                if (triggersObject && !triggersObject.isUndefined() && triggersObject.is(ObjectShape)) {
                    const triggersValue = triggersObject.get('triggers')

                    // On-demand playbooks have no triggering record, so triggers cannot be
                    // configured at all. PlaybookDependentConfig's TS override omits the key
                    // entirely (triggers?: never), but JS callers (or `as any`) bypass that —
                    // mirror the constraint here.
                    if (isOnDemand && triggersValue?.isDefined() && !triggersValue.isUndefined()) {
                        diagnostics.error(triggersValue, "triggers cannot be set when executionType is 'on_demand'.")
                    }

                    if (triggersValue && triggersValue.is(ArrayShape)) {
                        const triggers = triggersValue.getElements()

                        // Validate max trigger count
                        if (triggers.length > MAX_TRIGGER_COUNT) {
                            diagnostics.error(
                                triggersValue,
                                `Playbook has ${triggers.length} triggers. The maximum allowed is ${MAX_TRIGGER_COUNT}.`
                            )
                        }

                        // Validate parentRecord on triggers when parentTable is set and non-empty.
                        // Fires in two cases:
                        //   1. Trigger has a table different from parentTable.
                        //   2. Trigger has no table (scheduled triggers) — parent linking still
                        //      requires parentRecord because the trigger cannot supply one.
                        // parentRecord is provided in the 4th-arg mapper callback
                        if (parentTableVal) {
                            for (const element of triggers) {
                                if (!element.is(CallExpressionShape)) {
                                    continue
                                }
                                const triggerCall = element.as(CallExpressionShape)
                                const triggerInputs = triggerCall.getArgument(2)?.ifObject()?.asObject()
                                if (!triggerInputs) {
                                    continue
                                }

                                const triggerTable = triggerInputs.get('table')?.ifString()?.getValue()

                                if (triggerTable !== parentTableVal) {
                                    // Check 4th-arg mapper for parentRecord
                                    const mapperArg = triggerCall.getArgument(3)
                                    let hasParentRecord = false
                                    if (mapperArg && !mapperArg.isUndefined() && mapperArg.is(ArrowFunctionShape)) {
                                        const returnVal = mapperArg.as(ArrowFunctionShape).getReturnValue()
                                        if (returnVal?.is(ObjectShape)) {
                                            const pr = returnVal.as(ObjectShape).get(PARENT_RECORD_MAPPER_KEY)
                                            hasParentRecord = !!pr && !pr.isUndefined()
                                        }
                                    }

                                    if (!hasParentRecord) {
                                        const context = triggerTable
                                            ? `Trigger table '${triggerTable}' differs from`
                                            : 'Scheduled trigger has no record table matching'
                                        diagnostics.error(
                                            triggerInputs,
                                            `${context} playbook parentTable '${parentTableVal}'. parentRecord is required in the trigger's mapper callback.`
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // --- Validate Go Back activities ---
                const bodyArg = callExpression.getArgument(2)
                const lanesArrow = bodyArg?.asObject().get('lanes')
                const lanesArrowFn = lanesArrow?.is(ArrowFunctionShape) ? lanesArrow.as(ArrowFunctionShape) : undefined
                const playbookGraph = lanesArrowFn ? collectPlaybookGraph(lanesArrowFn) : undefined
                if (playbookGraph) {
                    const playbookRestartable = config.get('restartable')?.ifString()?.getValue()
                    const evaluateVariantChildrenAfterKey = getNowIdKey(config.get('evaluateVariantChildrenAfter'))
                    validateGoBackActivities(
                        playbookGraph,
                        playbookRestartable,
                        diagnostics,
                        evaluateVariantChildrenAfterKey
                    )
                }

                // Don't create a record - this is diagnostics only
                return { success: false }
            },
        },
    ],
})
