import { CallExpressionShape, Plugin, type Result, type Shape, ts } from '@servicenow/sdk-build-core'
import { ACTIVITY_REF_CALLEE, DATAPILL_CALLEE } from '../constants/playbook-plugin-constants'
import { getCalleeName } from '../utils/ts-node-utils'
import { ActivityRefPillShape } from '../utils/playbook-pill-resolver'

/** Element-access base text that identifies a `Now.ID['key']` reference. */
const NOW_ID_CALLEE = 'Now.ID'

/**
 * Extract the key from a `Now.ID['key']` argument to activityRef().
 * Only `Now.ID[<string literal>]` is accepted — any other expression returns undefined
 * so the reference is rejected (an activityRef target must be an explicit Now.ID).
 */
function extractNowIdKey(node: ts.Node): string | undefined {
    if (!ts.Node.isElementAccessExpression(node) || node.getExpression().getText() !== NOW_ID_CALLEE) {
        return undefined
    }
    const argExpr = node.getArgumentExpression()
    return argExpr && ts.Node.isStringLiteral(argExpr) ? argExpr.getLiteralValue() : undefined
}

/**
 * Parse a dataPill() argument of the form `activityRef(Now.ID['x']).outputs.<path>`.
 *
 * Walks the property-access chain from the outermost segment down to the base
 * expression, which must be a `wfa.playbook.activityRef(Now.ID['x'])` call. Returns the
 * referenced activity's Now.ID key and the dot-walk path (e.g. `outputs.record`), or
 * undefined when the argument is not an activityRef chain.
 */
function parseActivityRefArg(argNode: ts.Node): { nowIdKey: string; pillPath: string } | undefined {
    // The reference nests outermost-first: `.assigned_to` wraps `.record` wraps `.outputs`
    // wraps the activityRef(...) call. Peel off each property-access layer, collecting its
    // name (unshift restores source order), until we reach the base call expression. This
    // yields the full dot-walk path of any depth and the activityRef call to validate.
    const segments: string[] = []
    let current: ts.Node = argNode
    while (ts.Node.isPropertyAccessExpression(current)) {
        segments.unshift(current.getName())
        current = current.getExpression()
    }

    if (!ts.Node.isCallExpression(current) || getCalleeName(current) !== ACTIVITY_REF_CALLEE) {
        return undefined
    }

    const keyArg = current.getArguments()[0]
    const nowIdKey = keyArg && extractNowIdKey(keyArg)
    if (nowIdKey === undefined) {
        return undefined
    }

    return { nowIdKey, pillPath: segments.join('.') }
}

/**
 * PlaybookActivityRefPlugin — intercepts `wfa.playbook.dataPill(activityRef(...).outputs.*)`
 * at the node level.
 *
 * The activityRef chain has a function call as the base of a property access, which the
 * generic shape builder rejects ("Left side of property access expression is unsupported").
 * This plugin parses the reference straight from the TypeScript AST and emits a
 * `dataPill(ActivityRefPillShape)` shape; the playbook pill resolver later turns it into a
 * `{{act.<guid>.<path>}}` pill. Every other dataPill() (and every non-dataPill call) returns
 * `{ success: false }` so it continues through the normal shape-building path unchanged.
 */
export const PlaybookActivityRefPlugin = Plugin.create({
    name: 'PlaybookActivityRefPlugin',
    noTelemetry: true,
    nodes: [
        {
            node: 'CallExpression',
            fileTypes: ['fluent'],
            toShape(node): Result<Shape> {
                if (getCalleeName(node) !== DATAPILL_CALLEE) {
                    return { success: false }
                }

                const arg = node.getArguments()[0]
                const parsed = arg && parseActivityRefArg(arg)
                if (!parsed) {
                    return { success: false }
                }

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: node,
                        callee: DATAPILL_CALLEE,
                        args: [
                            new ActivityRefPillShape({
                                source: node,
                                nowIdKey: parsed.nowIdKey,
                                pillPath: parsed.pillPath,
                            }),
                        ],
                    }),
                }
            },
        },
        {
            // The activityRef chain (`activityRef(Now.ID['x']).outputs.<path>`) is a property
            // access whose base is a call, which the generic property-access builder rejects.
            // The dataPill() handler above parses it during normal shape building, but the
            // committer re-parses this arg node on its own to check equality before writing;
            // handle it here so that re-parse succeeds and an incremental transform can commit.
            node: 'PropertyAccessExpression',
            fileTypes: ['fluent'],
            toShape(node): Result<Shape> {
                const parsed = parseActivityRefArg(node)
                if (!parsed) {
                    return { success: false }
                }
                return {
                    success: true,
                    value: new ActivityRefPillShape({
                        source: node,
                        nowIdKey: parsed.nowIdKey,
                        pillPath: parsed.pillPath,
                    }),
                }
            },
        },
    ],
})
