import type { Database, Record as SdkRecord, Shape } from '@servicenow/sdk-build-core'
import { CallExpressionShape, IdentifierShape, Plugin } from '@servicenow/sdk-build-core'
import { type ArrowFunctionShape, NowIdShape } from '@servicenow/sdk-build-plugins'
import {
    VARIANT_COLORS,
    VARIANT_DEFAULTS,
    VARIANT_GENERATED_CALLEE,
    VARIANT_TABLE,
    type VariantColor,
} from '../constants/playbook-plugin-constants'
import { VariantShape } from '../utils/playbook-shapes'
import { suppressDeletedChildToFile } from '../utils/delete-multiple-sweep'
import { isPlaybookUnsupported } from '../utils/transform-utils'
import { getConfigWithId, getNowIdKey } from '../utils/graph-utils'
import { parseArrowBodyEntries } from '../utils/arrow-body-parser'
import { type PillContext, resolvePlaybookPill } from '../utils/playbook-pill-resolver'
import { transformConditionPills } from '../utils/playbook-pill-transformer'
import { shapeReferencesParams } from '../utils/shape-params-detector'
import { slugifyString } from '../../utils/slugify'
import { VariantDiagnosticsPlugin } from './variant-diagnostics-plugin'

/**
 * Deterministically picks one of the 8 platform variant colors from a seed string, so that
 * rebuilding the same variant always yields the same color (no round-trip drift) while still
 * spreading different variants across different colors. Does not by itself avoid sibling/parent
 * color collisions — `pickAvoidingCollision` layers that on top; see `resolveVariantColors`.
 */
function pickDeterministicColor(seed: string): VariantColor {
    let hash = 0
    for (let i = 0; i < seed.length; i++) {
        hash = (hash * 31 + seed.charCodeAt(i)) | 0
    }
    return VARIANT_COLORS[Math.abs(hash) % VARIANT_COLORS.length]
}

/**
 * Like `pickDeterministicColor`, but steps forward through `VARIANT_COLORS` (wrapping around)
 * until it finds a value not in `avoid`. Falls back to the plain deterministic pick if every
 * color is already taken (only possible with 8+ siblings under the same parent).
 */
function pickAvoidingCollision(seed: string, avoid: ReadonlySet<VariantColor>): VariantColor {
    const base = pickDeterministicColor(seed)
    if (!avoid.has(base)) {
        return base
    }
    const startIndex = VARIANT_COLORS.indexOf(base)
    for (let offset = 1; offset < VARIANT_COLORS.length; offset++) {
        const candidate = VARIANT_COLORS[(startIndex + offset) % VARIANT_COLORS.length]
        if (!avoid.has(candidate)) {
            return candidate
        }
    }
    return base
}

/**
 * One variant's identity/position for `resolveVariantColors`. `id`/`parentId` are whatever
 * space the caller works in (Now.ID keys for Fluent source, GUIDs for records) — they only need
 * to be internally consistent for tree-linking. `colorSeed` is always the variant's *original*
 * Now.ID key, since that's what a color must be deterministic against regardless of direction.
 */
interface VariantColorNode {
    id: string
    parentId: string | undefined
    order: number
    colorSeed: string
    explicitColor: VariantColor | undefined
}

/**
 * Resolves every variant's color from a flat, order-independent list of variant nodes, mirroring
 * the Designer UI's random-with-avoidance assignment: an auto-assigned color never matches its
 * own parent's color or an already-processed sibling's color. Explicit colors are used as-is —
 * collision avoidance only applies to auto-assignment.
 *
 * Siblings are always processed in ascending `order` (their mandatory tree-display-order field)
 * so the Fluent->XML (fresh assignment, keyed by Now.ID key) and XML->Fluent (recomputing what
 * auto-assignment would have produced, to detect explicit overrides, keyed by GUID) directions
 * replay the identical sequence and agree on the result.
 */
function resolveVariantColors(nodes: VariantColorNode[]): Map<string, VariantColor> {
    const childrenOf = new Map<string | undefined, VariantColorNode[]>()
    for (const node of nodes) {
        const siblings = childrenOf.get(node.parentId)
        if (siblings) {
            siblings.push(node)
        } else {
            childrenOf.set(node.parentId, [node])
        }
    }
    for (const siblings of childrenOf.values()) {
        siblings.sort((a, b) => a.order - b.order)
    }

    const assigned = new Map<string, VariantColor>()
    const assignGroup = (parentId: string | undefined): void => {
        const parentColor = parentId ? assigned.get(parentId) : undefined
        const takenBySiblings = new Set<VariantColor>()
        for (const node of childrenOf.get(parentId) ?? []) {
            const avoid = new Set(takenBySiblings)
            if (parentColor) {
                avoid.add(parentColor)
            }
            const color = node.explicitColor ?? pickAvoidingCollision(node.colorSeed, avoid)
            assigned.set(node.id, color)
            takenBySiblings.add(color)
            assignGroup(node.id)
        }
    }
    assignGroup(undefined)

    return assigned
}

/**
 * Extracts a stable seed string from a variant's `$id` shape for use with
 * `pickDeterministicColor`. `$id` is either a `Now.ID['key']` reference (most common) or a
 * literal string/number.
 */
function getVariantColorSeed(idShape: Shape | undefined): string {
    if (!idShape) {
        return ''
    }
    const nowIdKey = getNowIdKey(idShape)
    if (nowIdKey) {
        return nowIdKey
    }
    return idShape.ifString()?.getValue() ?? String(idShape.ifNumber()?.getValue() ?? '')
}

/**
 * Resolves the color every variant in this playbook will get, from the raw `variants` arrow —
 * before any records exist — so `resolveVariantColors` can see the whole parent/sibling tree up
 * front. Keyed by each variant's own Now.ID key. Used by `VariantPlugin.toRecord` (via
 * `VariantShape.getAssignedColor()`, wired up in `playbook-definition-plugin.ts`) instead of
 * calling `pickDeterministicColor` in isolation per variant.
 */
export function computeVariantColorAssignments(variantsArrow: ArrowFunctionShape): Map<string, VariantColor> {
    const { variables, returnObj } = parseArrowBodyEntries(variantsArrow)
    if (!returnObj?.isObject()) {
        return new Map()
    }

    const nodes: VariantColorNode[] = []
    for (const [, value] of returnObj.asObject().entries()) {
        const resolved = value.isIdentifier() ? (variables.get(value.asIdentifier().getName()) ?? value) : value
        if (!resolved.is(CallExpressionShape)) {
            continue
        }
        const callExpr = resolved.as(CallExpressionShape)
        if (callExpr.getCallee() !== VARIANT_GENERATED_CALLEE) {
            continue
        }
        const config = getConfigWithId(callExpr)
        const key = config ? getNowIdKey(config.get('$id')) : undefined
        if (!config || !key) {
            continue
        }

        let parentKey: string | undefined
        const parentShape = config.get('parentVariant')
        if (parentShape?.isDefined() && !parentShape.isUndefined() && parentShape.isIdentifier()) {
            const parentCallExpr = variables.get(parentShape.asIdentifier().getName())
            const parentConfig = parentCallExpr ? getConfigWithId(parentCallExpr) : undefined
            parentKey = parentConfig ? getNowIdKey(parentConfig.get('$id')) : undefined
        }

        const explicitColorValue = config.get('color')?.ifString()?.getValue()
        const explicitColor =
            explicitColorValue && (VARIANT_COLORS as readonly string[]).includes(explicitColorValue)
                ? (explicitColorValue as VariantColor)
                : undefined

        const order = config.get('order')?.ifNumber()?.getValue() ?? 0

        nodes.push({ id: key, parentId: parentKey, order, colorSeed: key, explicitColor })
    }

    return resolveVariantColors(nodes)
}

/**
 * Reconstruct a `sys_pd_process_variant` record into a `Variant({...})` call shape.
 *
 * A variant's condition can reference an activity's output via `activityRef()`, but only
 * when `evaluateVariantChildrenAfter` is set (see `VariantPlugin.toRecord` below) — it can
 * never reference one via the same-lane `activity` variable/pill, since a variant isn't
 * scoped to a specific point in the flow. This reconstruction passes an empty `activityMap`
 * to `transformConditionPills`, so any `activity_`-prefixed token is left as literal text
 * rather than rebuilt into an `activityRef()` call. This preserves round-trip XML fidelity
 * for the common case (no evaluation point / no activity reference in the condition), but
 * means the regenerated Fluent source won't show a clean `activityRef()` call when one was
 * used — no test currently exercises that combination.
 */
export function buildVariantToShapeResult(
    record: SdkRecord,
    guidToVarName?: Map<string, string>
): { success: true; value: VariantShape; usesCollectionParam: boolean } | { success: false } {
    const parentVariantGuid = record.get('parent_variant')?.ifString()?.getValue()
    const parentVariantVarName = parentVariantGuid ? guidToVarName?.get(parentVariantGuid) : undefined

    const idShape = NowIdShape.from(record)
    // color is mandatory on the platform, so a real record should always already have one.
    // Carry it through as-is rather than recomputing auto-assignment just to detect a match.
    const recordColor = record.get('color')?.ifString()?.getValue()
    const explicitColor =
        recordColor && (VARIANT_COLORS as readonly string[]).includes(recordColor)
            ? (recordColor as VariantColor)
            : undefined

    const configShape = record.transform(({ $ }) => ({
        $id: $.val(idShape),
        label: $.from('label'),
        name: $.from('name'),
        description: $.from('description').def(VARIANT_DEFAULTS.DESCRIPTION),
        condition: $.from('condition').map((v: Shape) => {
            const str = v.ifString()?.getValue()
            if (!str) {
                return v
            }
            return transformConditionPills(str, record, { activityMap: new Map() }) ?? v
        }),
        order: $.from('order').toNumber(),
        ...(explicitColor ? { color: $.val(explicitColor) } : {}),
    }))

    const finalConfigShape = parentVariantVarName
        ? configShape.merge({
              parentVariant: new IdentifierShape({ source: record, name: parentVariantVarName }),
          })
        : configShape

    const variantShape = new VariantShape({ source: record, config: finalConfigShape })

    return {
        success: true,
        value: variantShape,
        usesCollectionParam: shapeReferencesParams(variantShape),
    }
}

export function variantRecordToShape(
    record: SdkRecord,
    _database: Database,
    guidToVarName?: Map<string, string>
): { success: true; value: VariantShape; usesCollectionParam: boolean } | { success: false } {
    return buildVariantToShapeResult(record, guidToVarName)
}

export const VariantPlugin = Plugin.create({
    name: 'VariantPlugin',
    noTelemetry: true,
    records: {
        [VARIANT_TABLE]: {
            toShape(record, { database }, guidToVarName?: Map<string, string>) {
                if (isPlaybookUnsupported(record, database)) {
                    return { success: false }
                }
                return buildVariantToShapeResult(record, guidToVarName)
            },
            toFile: suppressDeletedChildToFile,
        },
    },
    shapes: [
        {
            shape: VariantShape,
            fileTypes: ['fluent'],
            async toRecord(variantShape, { factory, diagnostics, transform }) {
                const config = variantShape.getConfig()

                // Run variant diagnostics (mandatory label/condition checks).
                await transform.toRecord(variantShape, VariantDiagnosticsPlugin)

                const explicitName = config.get('name')?.ifString()?.getValue()
                const labelVal = config.get('label')?.ifString()?.getValue()
                const computedName = explicitName ?? (labelVal ? slugifyString(labelVal) : '')

                // color is optional. If the user sets a valid value, use it; otherwise use the
                // color `computeVariantColorAssignments` already resolved for this variant (see
                // playbook-definition-plugin.ts), which auto-assigns deterministically from $id
                // while avoiding collisions with this variant's parent/sibling colors.
                // VariantDiagnosticsPlugin (run above) has already errored on an invalid
                // explicit value. Falls back to a plain deterministic pick if for some reason
                // no precomputed assignment is available (e.g. a non-standard callee/shape).
                const explicitColor = config.get('color')?.ifString()?.getValue()
                const assignedColor =
                    explicitColor && (VARIANT_COLORS as readonly string[]).includes(explicitColor)
                        ? (explicitColor as VariantColor)
                        : (variantShape.getAssignedColor() ??
                          pickDeterministicColor(getVariantColorSeed(config.get('$id'))))

                const playbookBodyParamsNames: string[] = []
                const variantsParamName = variantShape.getPlaybookBodyParamsName()
                if (variantsParamName) {
                    playbookBodyParamsNames.push(variantsParamName)
                }

                // By default, variants can't reference activity output — only playbook inputs
                // and the parent record are valid pill sources for a variant's condition. When
                // the playbook has a custom evaluateVariantChildrenAfter point, activities that
                // are guaranteed ancestors of that point are also safe to reference, via
                // wfa.playbook.activityRef(Now.ID['x']).outputs.* (see computeAncestorIds()).
                const ancestorActivityIds = variantShape.getAncestorActivityIds()
                const hasAncestorActivityIds = !!ancestorActivityIds && ancestorActivityIds.size > 0
                const conditionPillContext: PillContext = {
                    format: 'condition',
                    factory,
                    diagnostics,
                    playbookBodyParamsNames,
                    allowedSources: {
                        paramsInputs: true,
                        paramsParentRecord: true,
                        ...(hasAncestorActivityIds ? { activityReference: true } : {}),
                    },
                    ...(hasAncestorActivityIds ? { activityIds: ancestorActivityIds } : {}),
                }

                const conditionShape = config.get('condition')
                const resolvedCondition =
                    conditionShape && !conditionShape.isUndefined()
                        ? await resolvePlaybookPill(conditionShape, conditionPillContext)
                        : undefined

                const variantRecord = await factory.createRecord({
                    source: variantShape,
                    table: VARIANT_TABLE,
                    explicitId: config.get('$id'),
                    properties: config.transform(({ $ }) => ({
                        label: $,
                        name: $.val(computedName),
                        description: $.def(VARIANT_DEFAULTS.DESCRIPTION),
                        condition: resolvedCondition ? $.val(resolvedCondition) : $.from('condition'),
                        order: $,
                        color: $.val(assignedColor),
                        parent_variant: $.from('parentVariant'),
                        process_definition: $.from('processDefinition'),
                    })),
                })

                return {
                    success: true,
                    value: variantRecord,
                }
            },
        },
    ],
})
