import { CallExpressionShape, type ObjectShape, type Shape } from '@servicenow/sdk-build-core'
import { ArrowFunctionShape, NowIdShape } from '@servicenow/sdk-build-plugins'
import { ACTIVITY_CALLEE_NAMES, LANE_CALLEE_NAMES } from '../constants/playbook-plugin-constants'
import { DECISION_ACTIVITY_DEF_KEY } from '../constants/activity-ootb-maps'
import { parseArrowBodyEntries } from './arrow-body-parser'
import { extractIdFromCallExpression } from '../transforms/reference-resolver'
import { getActivityConfig } from './activity-utils'
import { isOptionalActivity } from './start-rule-resolver'

/**
 * Collect the Now.ID keys of every non-Decision, non-optional activity declared in the
 * playbook body (arg 2), across all lanes and stage-level activities. Decision activities
 * and optional (manually-started) activities are excluded — neither can be targeted by a
 * permission's `activityRef`: Decision activities express no output fields, and an optional
 * activity may never run, so a permission depending on it could never resolve reliably.
 * Used to validate cross-scope `wfa.playbook.activityRef(Now.ID['x'])` references in
 * permissions at build time.
 */
export function collectActivityNowIdKeysForPermissions(bodyArg: Shape | undefined): Set<string> {
    const ids = new Set<string>()
    const lanesArrow = bodyArg?.ifObject()?.asObject()?.get('lanes')
    if (!lanesArrow?.is(ArrowFunctionShape)) {
        return ids
    }

    const addFromCall = (call: CallExpressionShape): void => {
        const callee = call.getCallee()
        if (ACTIVITY_CALLEE_NAMES.has(callee)) {
            const isDecision = call.getArgument(0, false)?.getCode() === DECISION_ACTIVITY_DEF_KEY
            if (isDecision) {
                return
            }
            const config = getActivityConfig(call)
            const isManual = config && isOptionalActivity(config.get('startRule'))
            if (isManual) {
                return
            }
            const idShape = extractIdFromCallExpression(call)
            if (idShape instanceof NowIdShape) {
                ids.add(String(idShape.getValue()))
            }
            return
        }
        if (LANE_CALLEE_NAMES.has(callee)) {
            const activities = call.getArgument(0)?.ifObject()?.asObject()?.get('activities')
            if (activities?.is(ArrowFunctionShape)) {
                for (const actCall of parseArrowBodyEntries(activities.as(ArrowFunctionShape)).variables.values()) {
                    addFromCall(actCall)
                }
            }
        }
    }

    for (const call of parseArrowBodyEntries(lanesArrow.as(ArrowFunctionShape)).variables.values()) {
        addFromCall(call)
    }
    return ids
}

/** A single `Activity(...)` call found while walking a playbook body. */
export interface BodyActivityRef {
    /** The activity definition argument, e.g. `ActivityDefinitions.Core.SendEmail`. */
    definition: Shape
    /** The activity's `label`, or `'(unknown)'` when it isn't a plain string. */
    label: string
    /** The activity's config object, when it resolves to one. */
    config?: ObjectShape
}

/**
 * The call expressions an arrow function actually *returns*, resolving `return { x }`
 * identifiers back to their `const x = ...` initializer.
 *
 * This deliberately walks the return object rather than every declared variable, mirroring
 * `processChildCollectionToRecord`: a lane or activity that is declared but left out of the
 * return never becomes a record. Collecting it anyway would make a validation error on
 * something that never ships — and TypeScript, which only checks the returned object,
 * would disagree with the diagnostic.
 */
function collectReturnedCalls(arrow: ArrowFunctionShape): CallExpressionShape[] {
    const { variables, returnObj } = parseArrowBodyEntries(arrow)
    const entries = returnObj?.ifObject()?.asObject()?.entries()
    if (!entries) {
        return []
    }

    const calls: CallExpressionShape[] = []
    for (const [, value] of entries) {
        const resolved = value.isIdentifier() ? (variables.get(value.asIdentifier().getName()) ?? value) : value
        if (resolved.is(CallExpressionShape)) {
            calls.push(resolved.as(CallExpressionShape))
        }
    }
    return calls
}

/**
 * Collect every activity the playbook body (arg 3) actually contributes, across all lanes
 * and stage-level activities, paired with the definition each one is built from. Unlike
 * {@link collectActivityNowIdKeysForPermissions} nothing is filtered out — Decision and
 * optional activities are subject to the same public-playbook rules as any other activity.
 */
export function collectBodyActivities(bodyArg: Shape | undefined): BodyActivityRef[] {
    const activities: BodyActivityRef[] = []
    const lanesArrow = bodyArg?.ifObject()?.asObject()?.get('lanes')
    if (!lanesArrow?.is(ArrowFunctionShape)) {
        return activities
    }

    const addFromCall = (call: CallExpressionShape): void => {
        const callee = call.getCallee()
        if (ACTIVITY_CALLEE_NAMES.has(callee)) {
            const definition = call.getArgument(0, false)
            if (!definition) {
                return
            }
            const activityConfig = getActivityConfig(call)
            const label = activityConfig?.get('label')?.ifString()?.getValue() ?? '(unknown)'
            activities.push({ definition, label, config: activityConfig })
            return
        }
        if (LANE_CALLEE_NAMES.has(callee)) {
            const laneActivities = call.getArgument(0)?.ifObject()?.asObject()?.get('activities')
            if (laneActivities?.is(ArrowFunctionShape)) {
                for (const actCall of collectReturnedCalls(laneActivities.as(ArrowFunctionShape))) {
                    addFromCall(actCall)
                }
            }
        }
    }

    for (const call of collectReturnedCalls(lanesArrow.as(ArrowFunctionShape))) {
        addFromCall(call)
    }
    return activities
}
