import { PropertyAccessShape, type Shape } from '@servicenow/sdk-build-core'

/**
 * Resolve a `params.variants.<key>` reference (an activity's `variant` or
 * `variantOverrides[].variant` field) to the referenced variant's real GUID.
 *
 * Unlike a variant's own `parentVariant` field, which can bind a sibling variant identifier
 * directly from within the same `variants` callback scope, `params.variants.<key>` is resolved
 * from the property-name (JS object key) the variant was declared under — activities are
 * declared in a separate scope with no direct reference to the `variants` callback's local
 * variables.
 */
export function resolveVariantReferenceToGuid(
    variantRefShape: Shape | undefined,
    variantKeyToGuid: Map<string, string>,
    playbookBodyParamsNames: string[]
): string | undefined {
    const key = getVariantRefKey(variantRefShape, playbookBodyParamsNames)
    return key !== undefined ? variantKeyToGuid.get(key) : undefined
}

/**
 * Extract the `<key>` from a `params.variants.<key>` reference without resolving it to a GUID.
 * Returns undefined when `variantRefShape` isn't a bare PropertyAccessShape rooted at a
 * PlaybookBodyParams parameter with a `.variants.<key>` shape (this reference is never wrapped
 * in `wfa.playbook.dataPill(...)`, unlike other params-derived pills).
 *
 * Used by `ActivityDiagnosticsPlugin` to check that `variant`/`variantOverrides[].variant`
 * reference a variant actually declared in this playbook.
 */
export function getVariantRefKey(
    variantRefShape: Shape | undefined,
    playbookBodyParamsNames: string[]
): string | undefined {
    if (!variantRefShape || variantRefShape.isUndefined() || !variantRefShape.is(PropertyAccessShape)) {
        return undefined
    }
    const elements = variantRefShape.as(PropertyAccessShape).getElements()
    if (elements.length !== 3) {
        return undefined
    }
    const rootName = elements[0]?.getName()
    if (!rootName || !playbookBodyParamsNames.includes(rootName)) {
        return undefined
    }
    if (elements[1]?.getName() !== 'variants') {
        return undefined
    }
    return elements[2]?.getName()
}

/**
 * Build a `<playbookBodyParamsName>.variants.<key>` property-access reference for the given
 * variant GUID, for reconstructing an activity's `variant`/`variantOverrides[].variant` field
 * in the toShape (database → Fluent) direction.
 *
 * Falls back to using the raw GUID as the key when the variant isn't in `variantGuidToKey`
 * (e.g. an override whose variant was deleted out from under it). This is intentional: it
 * reconstructs an unresolvable property key (`params.variants.<guid>`) rather than silently
 * dropping the reference, so the regenerated Fluent surfaces a visible problem — the
 * diagnostics check in `ActivityDiagnosticsPlugin` flags a key that doesn't match any declared
 * variant as an error, instead of the dangling reference vanishing unnoticed.
 */
export function buildVariantRefShape(
    source: Shape,
    variantGuid: string,
    variantGuidToKey: Map<string, string>,
    playbookBodyParamsName: string
): PropertyAccessShape {
    const key = variantGuidToKey.get(variantGuid) ?? variantGuid
    return new PropertyAccessShape({
        source,
        elements: [playbookBodyParamsName, 'variants', key],
    })
}
