import {
    CallExpressionShape,
    PropertyAccessShape,
    type Shape,
    TemplateExpressionShape,
} from '@servicenow/sdk-build-core'

/**
 * Detects whether a reconstructed shape references a collection callback's `params`
 * parameter (e.g. `params.inputs.foo` or `params.parentRecord.bar`) anywhere within it.
 *
 * Domain-agnostic — used by any `toShape` reconstruction that needs to decide whether its
 * enclosing callback (e.g. `lanes`, `variants`) must declare `params` in its signature.
 */
export function shapeReferencesParams(shape: Shape | undefined): boolean {
    if (!shape) {
        return false
    }
    if (shape instanceof PropertyAccessShape) {
        const [root] = shape.getElements()
        return root?.getName() === 'params'
    }
    if (shape instanceof CallExpressionShape) {
        return shape.getArguments(false).some((arg) => shapeReferencesParams(arg))
    }
    if (shape instanceof TemplateExpressionShape) {
        return shape.getSpans().some((span) => shapeReferencesParams(span.getExpression()))
    }
    const obj = shape.ifObject()
    if (obj) {
        return obj.entries().some(([, value]) => shapeReferencesParams(value))
    }
    const arr = shape.ifArray()
    if (arr) {
        return arr.getElements().some((element) => shapeReferencesParams(element))
    }
    return false
}
