import { CallExpressionShape, Plugin, type Result, type Shape, ts } from '@servicenow/sdk-build-core'
import type { Diagnostics } from '@servicenow/sdk-build-core'
import { AUTOMATION_PLAN_CALLEE, DATAPILL_CALLEE } from '../constants/playbook-plugin-constants'
import { getCalleeName } from '../utils/ts-node-utils'
import { AutomationPlanPillShape } from '../utils/playbook-pill-resolver'

/**
 * Peel `.inputs`/`.outputs.<path>` property-access layers off `argNode` until reaching a
 * `wfa.playbook.automationPlan(uiId?)` call expression. Mirrors `parseActivityRefArg` in
 * `playbook-activity-ref-plugin.ts` — the dot-walk base is a call expression, not a plain
 * identifier, so the generic property-access builder rejects it and this must run first.
 *
 * Emits a diagnostic (rather than silently rejecting) once the base is confirmed to be an
 * `automationPlan(...)` call but its argument isn't a string literal — at that point the
 * author's intent is clear and a targeted message beats the generic property-access fallback.
 */
function parseAutomationPlanArg(
    argNode: ts.Node,
    diagnostics: Diagnostics
): { uiId: string | undefined; pillPath: string } | undefined {
    const segments: string[] = []
    let current: ts.Node = argNode
    while (ts.Node.isPropertyAccessExpression(current)) {
        segments.unshift(current.getName())
        current = current.getExpression()
    }

    if (!ts.Node.isCallExpression(current) || getCalleeName(current) !== AUTOMATION_PLAN_CALLEE) {
        return undefined
    }

    const uiIdArg = current.getArguments()[0]
    let uiId: string | undefined
    if (uiIdArg) {
        if (!ts.Node.isStringLiteral(uiIdArg)) {
            diagnostics.error(
                uiIdArg,
                'wfa.playbook.automationPlan() expects its uiId argument to be a string literal, ' +
                    "e.g. automationPlan('my_ui_id'). Variables and other expressions are not supported."
            )
            return undefined
        }
        uiId = uiIdArg.getLiteralValue()
    }

    return { uiId, pillPath: segments.join('.') }
}

export const PlaybookAutomationPlanPlugin = Plugin.create({
    name: 'PlaybookAutomationPlanPlugin',
    noTelemetry: true,
    nodes: [
        {
            node: 'CallExpression',
            fileTypes: ['fluent'],
            toShape(node, { diagnostics }): Result<Shape> {
                if (getCalleeName(node) !== DATAPILL_CALLEE) {
                    return { success: false }
                }

                const arg = node.getArguments()[0]
                const parsed = arg && parseAutomationPlanArg(arg, diagnostics)
                if (!parsed) {
                    return { success: false }
                }

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: node,
                        callee: DATAPILL_CALLEE,
                        args: [
                            new AutomationPlanPillShape({
                                source: node,
                                uiId: parsed.uiId,
                                pillPath: parsed.pillPath,
                            }),
                        ],
                    }),
                }
            },
        },
        {
            // Same rationale as PlaybookActivityRefPlugin's second node handler: the
            // committer re-parses this arg node on its own to check equality before writing,
            // so it must independently resolve to the same shape for an incremental transform
            // to commit correctly.
            node: 'PropertyAccessExpression',
            fileTypes: ['fluent'],
            toShape(node, { diagnostics }): Result<Shape> {
                const parsed = parseAutomationPlanArg(node, diagnostics)
                if (!parsed) {
                    return { success: false }
                }
                return {
                    success: true,
                    value: new AutomationPlanPillShape({
                        source: node,
                        uiId: parsed.uiId,
                        pillPath: parsed.pillPath,
                    }),
                }
            },
        },
    ],
})
