export const PLAYBOOK_DEFAULTS = {
    ACTIVE: true,
    ACCESS: 'public',
    STATUS: 'draft',
    RESTARTABLE: 'RESTARTABLE_FALSE',
    ALLOW_AS_NESTED: false,
    PUBLIC_ACCESS: false,
    RUN_STRATEGY: 'run_once',
    RUN_STRATEGY_ON_PROCESS_DEFINITION: true,
    EXECUTION_TYPE: 'record_driven',
    PROCESS_TYPE: 'Standard playbook',
    SCHEMA_VERSION: 3,
    /**
     * Default/fallback schema version Fluent writes when `schemaVersion` isn't specified.
     * Despite the name, this isn't an enforced ceiling — Fluent doesn't validate an upper
     * bound on `schemaVersion` at all; it's the safe baseline that works across every
     * supported release.
     *
     * The highest schema version a given instance actually accepts depends on its release —
     * Australia and older releases cap out at 3, Brazil and newer releases also accept 4. This
     * default of 3 keeps generated playbooks compatible with Australia and older instances;
     * when deploying to a Brazil-or-newer instance, set `PlaybookConfig.schemaVersion` explicitly
     * to 4 to opt into the newer schema. Don't infer the ceiling from the release name alone —
     * confirm it against the target instance's `com.glide.pad.core.model.maxSupportedSchemaVersion`
     * system property. See **schemaVersion** in `playbook-api` for details.
     */
    MAX_SUPPORTED_SCHEMA_VERSION: 3,
    START_NON_BLOCKING: true,
    DATA_RETENTION_PERIOD_OVERRIDE: '6_week',
    VIEW_TYPE: 'DIAGRAM',
    PERMISSION: '{}',
} as const

