/** Platform-internal search token mapped to the human-readable 'keywords' field name */
export const KEYWORDS_PLATFORM_TOKEN = '123TEXTQUERY321'

/**
 * Regex matching `keywords` only in *field position* (start of a condition segment).
 * Segments are delimited by `^` or `^OR`, so the word must appear right after one of
 * those delimiters (or at the very start of the string).
 */
const KEYWORDS_FIELD_REGEX = /(?<=^|\^(?:OR)?)keywords\b/g

/**
 * Same positional constraint but for the platform token (decode direction).
 */
const KEYWORDS_TOKEN_FIELD_REGEX = new RegExp(`(?<=^|\\^(?:OR)?)${KEYWORDS_PLATFORM_TOKEN}\\b`, 'g')

/**
 * Build direction: replace the human-readable `keywords` field name with the
 * platform-internal token when it appears in field position inside a condition string.
 */
export function encodeKeywordsToken(condition: string): string {
    return condition.replace(KEYWORDS_FIELD_REGEX, KEYWORDS_PLATFORM_TOKEN)
}

/**
 * Download direction: replace the platform-internal token back to the human-readable
 * `keywords` field name when it appears in field position inside a condition string.
 */
export function decodeKeywordsToken(condition: string): string {
    return condition.replace(KEYWORDS_TOKEN_FIELD_REGEX, 'keywords')
}

