import {
    CallExpressionShape,
    type ObjectShape,
    Shape,
    TemplateExpressionShape,
    TemplateSpanShape,
    TemplateValueShape,
} from '@servicenow/sdk-build-core'
import type { Record as SdkRecord, Source } from '@servicenow/sdk-build-core'
import { DATAPILL_CALLEE } from '../constants/playbook-plugin-constants'

type LiteralPart = { type: 'literal'; text: string }
type ExprPart = { type: 'expr'; shape: Shape }
type Part = LiteralPart | ExprPart

/**
 * Converts a `TemplateValueShape` into the equivalent `field=value^field=value`
 * string representation, preserving dataPill expressions as template spans.
 *
 * Returns a `TemplateExpressionShape` when the value contains dataPills, or a
 * plain `StringShape` when all values are static. Non-TemplateValueShape inputs
 * are returned unchanged.
 *
 * ## Why this is needed
 *
 * `TemplateValue({ approval: wfa.playbook.dataPill(x), work_notes: 'Updated' })`
 * is a `CallExpressionShape` — the playbook pill resolver only handles
 * `StringShape`, `TemplateExpressionShape`, and bare dataPill calls. Converting
 * to a template expression lets both the pill resolver and the field validator
 * process the value through their standard paths.
 *
 * ## Example
 *
 * ```ts
 * TemplateValue({
 *     short_description: `No laptop for: ${wfa.playbook.dataPill(params.trigger.current.name)}`,
 *     priority: 2,
 * })
 * ```
 *
 * becomes the equivalent of:
 *
 * ```ts
 * `short_description=No laptop for: ${wfa.playbook.dataPill(params.trigger.current.name)}^priority=2`
 * ```
 *
 * @returns The original shape unchanged if it is not a `TemplateValueShape`.
 */
export function normalizeTemplateValue(shape: Shape): Shape {
    if (!(shape instanceof TemplateValueShape)) {
        return shape
    }

    const source = shape.getSource()
    const entries = shape.getTemplateValue().entries()

    if (entries.length === 0) {
        return shape
    }

    const parts: Part[] = []

    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i]!
        if (i > 0) {
            parts.push({ type: 'literal', text: '^' })
        }
        parts.push({ type: 'literal', text: `${entry[0]}=` })
        flattenValueIntoParts(entry[1], parts)
    }

    return assembleTemplateExpression(source, parts)
}

/**
 * Decomposes a property value shape into literal and expression parts.
 *
 * - dataPill calls → expression part (preserved for pill resolution)
 * - Template expressions → head literal + flattened spans (so nested
 *   dataPills are preserved while literal text is inlined)
 * - String/number literals → literal text (with `^` escaped to `^^`)
 * - Anything else → stringified as literal (best-effort)
 */
function flattenValueIntoParts(value: Shape, parts: Part[]): void {
    // Direct dataPill call: wfa.playbook.dataPill(...)
    if (value instanceof CallExpressionShape && value.getCallee() === DATAPILL_CALLEE) {
        parts.push({ type: 'expr', shape: value })
        return
    }

    // Template expression: `prefix ${dataPill} suffix`
    // Walk its head literal and spans so dataPill expressions are preserved
    // as expression parts while surrounding text becomes literal parts.
    if (value instanceof TemplateExpressionShape) {
        const headText = value.getLiteralText()
        if (headText) {
            parts.push({ type: 'literal', text: escapeCarets(headText) })
        }
        for (const span of value.getSpans()) {
            flattenValueIntoParts(span.getExpression(), parts)
            const trailingText = span.getLiteralText()
            if (trailingText) {
                parts.push({ type: 'literal', text: escapeCarets(trailingText) })
            }
        }
        return
    }

    // Plain string or number — inline as escaped literal text.
    const strShape = value.ifString()
    if (strShape) {
        parts.push({ type: 'literal', text: escapeCarets(strShape.getValue()) })
        return
    }
    const numShape = value.ifNumber()
    if (numShape) {
        parts.push({ type: 'literal', text: String(numShape.getValue()) })
        return
    }

    // Fallback: stringify whatever we have.
    parts.push({ type: 'literal', text: escapeCarets(value.toString().getValue()) })
}

/**
 * Assembles a flat parts list into a `TemplateExpressionShape` (when expression
 * parts are present) or a plain `StringShape` (when everything is literal).
 */
function assembleTemplateExpression(source: Source, parts: Part[]): Shape {
    // Merge consecutive literal parts.
    const merged: Part[] = []
    for (const part of parts) {
        const last = merged[merged.length - 1]
        if (part.type === 'literal' && last?.type === 'literal') {
            last.text += part.text
        } else {
            merged.push({ ...part })
        }
    }

    // All literals → return a plain StringShape.
    if (merged.every((p): p is LiteralPart => p.type === 'literal')) {
        const text = merged.map((p) => p.text).join('')
        return Shape.from(source, text).asString()
    }

    // Build head literal (everything before the first expression).
    let headText = ''
    let startIdx = 0
    const first = merged[0]
    if (first?.type === 'literal') {
        headText = first.text
        startIdx = 1
    }

    // Build spans: each expression paired with the literal text that follows it.
    const spans: TemplateSpanShape[] = []
    for (let i = startIdx; i < merged.length; i++) {
        const part = merged[i]!
        if (part.type !== 'expr') {
            continue
        }
        let trailingText = ''
        const next = merged[i + 1]
        if (next?.type === 'literal') {
            trailingText = next.text
            i++
        }
        spans.push(new TemplateSpanShape({ source, expression: part.shape, literalText: trailingText }))
    }

    return new TemplateExpressionShape({ source, literalText: headText, spans })
}

/** Escapes `^` as `^^` to avoid conflicts with the field separator. */
function escapeCarets(text: string): string {
    return text.replace(/\^/g, '^^')
}

/**
 * Parses a `field=value^` encoded string into `[fieldName, Shape]` entries.
 *
 * Handles `^^` as an escaped literal caret (e.g. `description=a^^b` → field
 * `description` with value `a^b`). Empty and malformed segments are skipped.
 *
 * Shared by `reconstructTemplateValue` (XML→Fluent) and `convertToTemplateValue`
 * in `transform-utils.ts` (also XML→Fluent, with optional pill context).
 * Using one parser ensures both directions handle `^^` escaping identically.
 */
export function parseTemplateValueEntries(rawString: string, source: Source): [string, Shape][] {
    if (rawString === '') {
        return []
    }

    // Replace `^^` with a sentinel so splitting on `^` doesn't break escaped carets.
    const SENTINEL = '\x00'
    const escaped = rawString.replace(/\^\^/g, SENTINEL)
    const segments = escaped.split('^').map((s) => s.replace(new RegExp(SENTINEL, 'g'), '^'))

    const entries: [string, Shape][] = []
    for (const segment of segments) {
        if (segment === '') {
            continue // trailing `^` produces an empty segment
        }
        const eqIdx = segment.indexOf('=')
        if (eqIdx === -1) {
            continue // malformed segment — skip
        }
        const fieldName = segment.slice(0, eqIdx)
        const fieldValue = segment.slice(eqIdx + 1)
        if (fieldName === '') {
            continue
        }
        entries.push([fieldName, Shape.from(source, fieldValue).asString()])
    }

    return entries
}

/**
 * Reconstructs a `TemplateValueShape` (or raw `StringShape`) from a
 * `field=value^` encoded string stored in an XML record field.
 *
 * Used when transforming launcher_template_fields from XML → Fluent so the
 * generated code contains `TemplateValue({ ... })` instead of the raw string.
 *
 * Returns an empty `StringShape` when the field is empty or absent, which the
 * caller's `.def('')` will suppress from the generated output.
 * Falls back to the raw `StringShape` if parsing produces no valid pairs.
 */
export function reconstructTemplateValue(record: SdkRecord, field: string): Shape {
    const rawShape = record.get(field)
    const source = rawShape.getSource()
    // Use isString() guard — record fields are not always StringShape (e.g. empty/missing fields)
    const rawString = rawShape.isString() ? (rawShape.ifString()?.getValue() ?? '') : ''

    if (rawString === '') {
        return Shape.from(source, '').asString()
    }

    const entries = parseTemplateValueEntries(rawString, source)

    if (entries.length === 0) {
        return Shape.from(source, rawString).asString()
    }

    return new TemplateValueShape({
        source,
        value: Object.fromEntries(entries),
    })
}

/**
 * Normalizes the launcher template fields shape from a Fluent config object
 * (Fluent → XML direction) by calling the existing `normalizeTemplateValue`
 * on whichever shape is stored at `key` in `config`.
 */
export function resolveTemplateValueFieldToXML(config: ObjectShape, key: string): Shape {
    const shape = config.get(key)
    if (!shape) {
        return Shape.from(config.getSource(), '').asString()
    }
    return normalizeTemplateValue(shape)
}
